"""Conversão dos atributos (1 a 20) em forças compostas por fase do jogo.

Cada fase usa uma combinação ponderada de atributos. O papel tático muda essa
combinação: o mesmo volante rende diferente como Trinco ou como Regista,
porque cada papel valoriza atributos diferentes.
"""
from __future__ import annotations

from typing import Dict, Mapping, Optional, Union

from .entidades import Jogador
