PAPEIS_DE_GOLEIRO = (Papel.GOLEIRO, Papel.GOLEIRO_LIBERO)


def media_ponderada(jogador: Jogador, pesos: Mapping[str, float]) -> float:
    """Média ponderada de atributos do jogador."""
    soma = 0.0
    total = 0.0
    for nome, peso in pesos.items():
        soma += jogador.atributo(nome) * peso
        total += peso
    return soma / total if total else 0.0


def composto_fase(jogador: Jogador, fase: Fase, papel: Optional[Papel] = None) -> float:
    """Força do jogador numa fase do jogo, considerando o papel tático."""
    if papel is not None:
        eh_goleiro = papel in PAPEIS_DE_GOLEIRO
    else:
        eh_goleiro = jogador.posicao == Posicao.GOL
    if fase == Fase.CONSTRUCAO and eh_goleiro:
        base = media_ponderada(jogador, PESOS_ESPECIAIS["goleiro_construcao"])
    else:
        base = media_ponderada(jogador, PESOS_FASE[fase])
    if papel is not None:
        ajuste = AJUSTE_PAPEL.get(papel, {}).get(fase)
        if ajuste:
            return 0.5 * base + 0.5 * media_ponderada(jogador, ajuste)
    return base


def ajustes_corporais(jogador: Jogador) -> Dict[ChaveComposta, float]:
    """Efeito da altura e do peso reais nos duelos físicos e aéreos.

    Altura: cada 10 cm acima de 181 cm vale +0,9 no jogo aéreo (teto de 1,5).
    Goleiro: cada 10 cm acima de 188 cm vale +0,5 na defesa do gol.
    Massa corporal (IMC): corpo mais pesado protege melhor a bola e ganha
    mais trombadas, mas perde um pouco de arranque.
    """
    ajustes: Dict[ChaveComposta, float] = {}
    if jogador.altura_cm:
        bonus_altura = limitar((jogador.altura_cm - 181) / 10.0 * 0.9, -1.5, 1.5)
        ajustes["cabeceio_ataque"] = bonus_altura
        ajustes["duelo_aereo_def"] = bonus_altura
        if jogador.posicao == Posicao.GOL:
            ajustes["goleiro_defesa"] = limitar((jogador.altura_cm - 188) / 10.0 * 0.5, -1.0, 0.8)
    imc = jogador.imc
    if imc is not None:
        corpo = limitar((imc - 23.0) * 0.25, -0.8, 0.8)
        ajustes[Fase.PROTECAO] = ajustes.get(Fase.PROTECAO, 0.0) + corpo * 0.6
        ajustes["duelo_aereo_def"] = ajustes.get("duelo_aereo_def", 0.0) + corpo * 0.5
        ajustes["cabeceio_ataque"] = ajustes.get("cabeceio_ataque", 0.0) + corpo * 0.3
        ajustes["velocidade"] = ajustes.get("velocidade", 0.0) - corpo * 0.4
    return ajustes


def compostos_jogador(jogador: Jogador, papel: Optional[Papel] = None) -> Dict[ChaveComposta, float]:
    """Todas as forças compostas do jogador (fases e lances especiais)."""
    valores: Dict[ChaveComposta, float] = {}
    for fase in Fase:
        valores[fase] = composto_fase(jogador, fase, papel)
    for chave, pesos in PESOS_ESPECIAIS.items():
        valores[chave] = media_ponderada(jogador, pesos)
    for chave, ajuste in ajustes_corporais(jogador).items():
        valores[chave] = max(1.0, valores[chave] + ajuste)
    return valores


# Como cada posição pesa as forças compostas para gerar o nível geral.
PESO_NIVEL_POSICAO: Dict[Posicao, Dict[ChaveComposta, float]] = {
    Posicao.GOL: {"goleiro_defesa": 0.80, Fase.CONSTRUCAO: 0.20},
    Posicao.ZAG: {Fase.PROTECAO: 0.55, Fase.CONTENCAO: 0.20, Fase.CONSTRUCAO: 0.15, "duelo_aereo_def": 0.10},
    Posicao.LAT: {Fase.PROTECAO: 0.30, Fase.CONTENCAO: 0.15, Fase.PROGRESSAO: 0.25,
                  Fase.CRIACAO: 0.20, Fase.CONSTRUCAO: 0.10},
    Posicao.VOL: {Fase.CONTENCAO: 0.40, Fase.PROGRESSAO: 0.30, Fase.CONSTRUCAO: 0.20, Fase.PROTECAO: 0.10},
    Posicao.MEI: {Fase.PROGRESSAO: 0.35, Fase.CRIACAO: 0.40, "chute_pe": 0.10, Fase.PRESSAO: 0.15},
    Posicao.PON: {Fase.CRIACAO: 0.50, Fase.PROGRESSAO: 0.15, "chute_pe": 0.20, Fase.PRESSAO: 0.15},
    Posicao.ATA: {"chute_pe": 0.40, Fase.CRIACAO: 0.25, "cabeceio_ataque": 0.15,
                  "presenca_area": 0.10, Fase.PRESSAO: 0.10},
}


def nivel_geral(jogador: Jogador) -> float:
    """Nível geral do jogador na posição de origem (escala de 1 a 20)."""
    valores = compostos_jogador(jogador)
    pesos = PESO_NIVEL_POSICAO[jogador.posicao]
    return sum(valores[chave] * peso for chave, peso in pesos.items()) / sum(pesos.values())


_POSICOES_VIZINHAS = {
    frozenset(par)
    for par in (
        (Posicao.ZAG, Posicao.LAT), (Posicao.ZAG, Posicao.VOL), (Posicao.LAT, Posicao.PON),
        (Posicao.VOL, Posicao.MEI), (Posicao.MEI, Posicao.PON), (Posicao.MEI, Posicao.ATA),
        (Posicao.PON, Posicao.ATA),
    )
}


def adequacao_posicao(jogador: Jogador, posicao: Posicao) -> float:
    """Multiplicador de rendimento por jogar fora da posição de origem."""
    if posicao == jogador.posicao:
        return 1.0
    if posicao in jogador.posicoes_secundarias:
        return 0.94
    if Posicao.GOL in (posicao, jogador.posicao):
        return 0.25
    base = 0.85 if frozenset((posicao, jogador.posicao)) in _POSICOES_VIZINHAS else 0.68
    return min(0.94, base + (jogador.ocultos.versatilidade - 10) * 0.012)

