"""Calendário da carreira: datas de competições e janelas de transferência.

Datas reais do calendário da CBF (fontes no fim do arquivo):
1. 2026: Série A de 28/01 a 02/12; estaduais de 11/01 a 08/03; Copa do Nordeste, Copa Verde e Copa Sul
   Sudeste de 25/03 a 07/06; Copa do Brasil de 18/02 a 06/12; janelas de 05/01 a 03/03, janela
   doméstica complementar de 04/03 a 27/03 e segunda janela de 20/07 a 11/09; Copa do Mundo de 01/06 a 20/07.
2. 2027: Série A de 27/01 a 01/12; Série B de 20/03 a 27/11; Série C de 04/04 a 31/10; Série D de 04/04 a
   12/09; regionais de 24/03 a 13/06; janelas de 04/01 a 02/03 e de 19/07 a 10/09.

As Séries B, C e D de 2026 seguem o padrão divulgado para 2027 (datas de 2026: CONFIRMAR). Os outros
países usam datas de jogo do Megafut, marcadas como CONFIRMAR. De 2028 em diante o padrão de 2027 se repete.
"""
from __future__ import annotations

from dataclasses import dataclass
from datetime import date, timedelta
from typing import Dict, List, Optional, Tuple

FONTES_CALENDARIO = [
    "https://www.itatiaia.com.br/esportes/futebol/futebol-nacional/veja-todas-as-datas-do-novo-calendario-do-futebol-brasileiro-em-2026/",
    "https://atarde.com.br/esportes/cbf-amplia-janela-de-transferencias-nas-series-a-e-b-do-brasileirao-1380627",
    "https://www.tupi.fm/?p=2239370",
    "https://tribunadejundiai.com.br/mais/esportes/cbf-divulga-calendario-do-brasil-em-2027/",
]


@dataclass(frozen=True)
class Periodo:
    inicio: date
    fim: date
    nome: str = ""
    confirmado: bool = True

    def contem(self, dia: date) -> bool:
        return self.inicio <= dia <= self.fim


def _d(ano: int, mes: int, dia: int) -> date:
    return date(ano, mes, dia)


# Pausas sem jogos de liga (Copa do Mundo 2026)
PAUSAS = {2026: [Periodo(_d(2026, 6, 1), _d(2026, 7, 20), "Copa do Mundo")]}

LIGAS_BRASIL = {
    "Campeonato Brasileiro Série A": {
        2026: Periodo(_d(2026, 1, 28), _d(2026, 12, 2), "Série A 2026"),
        2027: Periodo(_d(2027, 1, 27), _d(2027, 12, 1), "Série A 2027"),
    },
    "Campeonato Brasileiro Série B": {
        2026: Periodo(_d(2026, 3, 20), _d(2026, 11, 27), "Série B 2026", confirmado=False),
        2027: Periodo(_d(2027, 3, 20), _d(2027, 11, 27), "Série B 2027"),
    },
    "Campeonato Brasileiro Série C": {
        2026: Periodo(_d(2026, 4, 4), _d(2026, 10, 31), "Série C 2026", confirmado=False),
        2027: Periodo(_d(2027, 4, 4), _d(2027, 10, 31), "Série C 2027"),
    },
    "Campeonato Brasileiro Série D": {
        2026: Periodo(_d(2026, 4, 4), _d(2026, 9, 12), "Série D 2026", confirmado=False),
        2027: Periodo(_d(2027, 4, 4), _d(2027, 9, 12), "Série D 2027"),
    },
}

JANELAS_BRASIL = {
    2026: [Periodo(_d(2026, 1, 5), _d(2026, 3, 3), "Primeira janela"),
           Periodo(_d(2026, 3, 4), _d(2026, 3, 27), "Janela doméstica complementar"),
           Periodo(_d(2026, 7, 20), _d(2026, 9, 11), "Segunda janela")],
    2027: [Periodo(_d(2027, 1, 4), _d(2027, 3, 2), "Primeira janela"),
           Periodo(_d(2027, 7, 19), _d(2027, 9, 10), "Segunda janela")],
}

COPAS_REGIONAIS_BRASIL = {
    2026: Periodo(_d(2026, 3, 25), _d(2026, 6, 7), "Copas regionais 2026"),
    2027: Periodo(_d(2027, 3, 24), _d(2027, 6, 13), "Copas regionais 2027"),
}

# Outros países: temporada de jogo do Megafut (CONFIRMAR as datas reais de cada liga)
TEMPORADA_PADRAO = (Periodo(_d(2026, 2, 7), _d(2026, 11, 28), "Temporada de jogo", confirmado=False))


def _no_ano(periodo: Periodo, ano: int) -> Periodo:
    def mover(d: date) -> date:
        try:
            return d.replace(year=d.year + (ano - periodo.inicio.year))
        except ValueError:  # 29 de fevereiro
            return d.replace(year=d.year + (ano - periodo.inicio.year), day=28)
    return Periodo(mover(periodo.inicio), mover(periodo.fim), periodo.nome, confirmado=False)


def periodo_da_liga(pais: str, liga: str, ano: int) -> Periodo:
    if pais == "Brasil" and liga in LIGAS_BRASIL:
        por_ano = LIGAS_BRASIL[liga]
        if ano in por_ano:
            return por_ano[ano]
        return _no_ano(por_ano[2027], ano)
    return _no_ano(TEMPORADA_PADRAO, ano)


def janelas(pais: str, ano: int) -> List[Periodo]:
    """Janelas de transferência. Fora do Brasil, as do Brasil servem de padrão de jogo (CONFIRMAR)."""
    if ano in JANELAS_BRASIL:
        base = JANELAS_BRASIL[ano]
    else:
        base = [_no_ano(p, ano) for p in JANELAS_BRASIL[2027]]
    if pais == "Brasil":
        return list(base)
    return [Periodo(p.inicio, p.fim, p.nome, confirmado=False) for p in base if "doméstica" not in p.nome]


def janela_aberta(pais: str, dia: date, domestica: bool = True) -> Optional[Periodo]:
    for periodo in janelas(pais, dia.year):
        if not domestica and "doméstica" in periodo.nome:
            continue
        if periodo.contem(dia):
            return periodo
    return None


def proxima_janela(pais: str, dia: date) -> Optional[Periodo]:
    candidatas = [p for ano in (dia.year, dia.year + 1) for p in janelas(pais, ano) if p.inicio > dia]
    return min(candidatas, key=lambda p: p.inicio) if candidatas else None


def pausas(ano: int) -> List[Periodo]:
    return PAUSAS.get(ano, [])


def datas_das_rodadas(periodo: Periodo, rodadas: int, ano: int) -> List[date]:
    """Espalha as rodadas no período, sem cair nas pausas, em quartas e domingos quando cabe."""
    dias_validos = []
    dia = periodo.inicio
    while dia <= periodo.fim:
        if not any(p.contem(dia) for p in pausas(ano)):
            dias_validos.append(dia)
        dia += timedelta(days=1)
    if not dias_validos:
        dias_validos = [periodo.inicio]
    preferidos = [d for d in dias_validos if d.weekday() in (2, 6)] or dias_validos
    if rodadas <= 1:
        return [preferidos[0]] * max(1, rodadas)
    if rodadas > len(preferidos):
        preferidos = dias_validos
    passo = (len(preferidos) - 1) / (rodadas - 1) if rodadas > 1 else 0
    datas = []
    for i in range(rodadas):
        datas.append(preferidos[min(len(preferidos) - 1, int(round(i * passo)))])
    for i in range(1, len(datas)):  # nunca duas rodadas no mesmo dia
        if datas[i] <= datas[i - 1]:
            datas[i] = datas[i - 1] + timedelta(days=1)
    return datas


def fim_da_temporada(ano: int) -> date:
    return _d(ano, 12, 15)


def inicio_da_temporada(ano: int) -> date:
    return _d(ano, 1, 5)

