"""Características principais do atleta para a tela de contratação: o que se destaca nele e o que pesa contra.

Os rótulos saem dos atributos do Megafut (estimados pelo nível e pela posição) e, quando existe, dos estilos de
jogo do EA SPORTS FC 26 (com fonte). Nada aqui é afirmação sobre a pessoa real.
"""
from __future__ import annotations

from typing import Any, Dict, List, Tuple

from .entidades import Jogador
from .enums import Posicao

ESTILOS_EA = {
    "First Touch": "Primeiro toque", "Rapid": "Arrancada", "Quick Step": "Passo rápido", "Power Header": "Cabeceio forte",
    "Precision Header": "Cabeceio preciso", "Finesse Shot": "Chute colocado", "Low Driven Shot": "Chute rasteiro",
