}


def _media(valores: List[int]) -> float:
    return sum(valores) / len(valores) if valores else 10.0


def caracteristicas(j: Jogador, capitao: bool = False, real: bool = True) -> List[Tuple[str, str]]:
    """Lista de (rótulo, tom) com tom "bom", "ruim" ou "" (neutro). No máximo oito, as mais marcantes primeiro.
    Atleta real (pessoa que existe) não recebe ponto fraco de caráter, saúde ou comportamento: o jogo não
    atribui fama a ninguém. Esses rótulos só aparecem nos atletas gerados pelo jogo."""
    t, m, f, o, p = j.tecnicos, j.mentais, j.fisicos, j.ocultos, j.personalidade
    goleiro = j.posicao == Posicao.GOL
    saida: List[Tuple[float, str, str]] = []
    # Pontos fortes relativos ao próprio jogador (todo atleta tem algo que se destaca)
    if goleiro:
        g = j.goleiro
        base = _media([g.reflexos, g.manejo, g.jogo_aereo, g.um_contra_um, g.reposicao, g.comando_area])
        opcoes = ((g.reflexos, "Reflexos rápidos"), (g.jogo_aereo, "Seguro no jogo aéreo"),
                  (g.um_contra_um, "Bom no mano a mano"), (g.reposicao, "Boa reposição"), (g.comando_area, "Comanda a área"),
                  (g.manejo, "Mãos seguras"))
        for valor, rotulo in opcoes:
            if valor >= base + 1:
                saida.append((valor - base, rotulo, "bom"))
        if not saida:
            valor, rotulo = max(opcoes)
            saida.append((0.5, rotulo, "bom"))
    else:
        tecnicos = {"finalizacao": "Finalizador", "drible": "Driblador", "passe": "Bom passe", "cruzamento": "Bom cruzamento",
                    "cabeceio": "Forte no jogo aéreo", "desarme": "Bom desarme", "marcacao": "Marca bem",
                    "chute_de_longe": "Chute de longe", "bola_parada": "Bola parada", "penalti": "Bom cobrador de pênalti"}
        base = _media([getattr(t, k) for k in tecnicos])
        for k, rotulo in tecnicos.items():
            valor = getattr(t, k)
            if valor >= base + 3:
                saida.append((valor - base, rotulo, "bom"))
        if not saida:
            k = max(tecnicos, key=lambda c: getattr(t, c))
            saida.append((0.5, tecnicos[k], "bom"))
        if f.velocidade >= 14 and f.aceleracao >= 13:
            saida.append((f.velocidade - 10, "Veloz", "bom"))
        if f.forca >= 15:
            saida.append((f.forca - 11, "Forte fisicamente", "bom"))
        if m.visao >= 14 and t.passe >= 13:
            saida.append((m.visao - 10, "Visão de jogo", "bom"))
    # Mentalidade (relativa ao próprio jogador, para não punir quem joga numa divisão menor)
    mm = _media([m.visao, m.decisao, m.compostura, m.posicionamento, m.antecipacao, m.concentracao, m.movimentacao,
                 m.trabalho_em_equipe, m.determinacao, m.lideranca, m.agressividade])
    if m.determinacao >= mm + 3 and m.agressividade >= mm:
        saida.append((m.determinacao - mm + 3, "Raçudo", "bom"))
    elif m.determinacao <= mm - 4:
        saida.append((mm - m.determinacao, "Pouca entrega", "ruim"))
    if m.trabalho_em_equipe >= mm + 2 and p.profissionalismo >= 11:
        saida.append((m.trabalho_em_equipe - mm + 2, "Bom de grupo", "bom"))
    elif p.temperamento <= 8 and m.trabalho_em_equipe <= mm - 3:
        saida.append((mm - m.trabalho_em_equipe, "Individualista", "ruim"))
    if m.lideranca >= mm + 3 or capitao:
        saida.append((max(m.lideranca - mm, 3) + 2, "Líder", "bom"))
    if m.antecipacao >= mm + 3 and m.posicionamento >= mm + 1:
        saida.append((m.antecipacao - mm, "Lê bem o jogo", "bom"))
    if o.jogos_grandes >= 15 or p.pressao >= 16:
        saida.append((max(o.jogos_grandes, p.pressao) - 9, "Cresce em jogo grande", "bom"))
    elif p.pressao <= 6:
        saida.append((10 - p.pressao, "Sente a pressão", "ruim"))
    if p.profissionalismo >= 16:
        saida.append((p.profissionalismo - 10, "Muito profissional", "bom"))
    elif p.profissionalismo <= 6:
        saida.append((10 - p.profissionalismo, "Pouco profissional", "ruim"))
    if p.temperamento <= 6:
        saida.append((10 - p.temperamento, "Temperamental", "ruim"))
    if p.lealdade >= 17:
        saida.append((p.lealdade - 11, "Leal ao clube", "bom"))
    if p.ambicao >= 17:
        saida.append((p.ambicao - 11, "Ambicioso", ""))
    if o.consistencia >= 15:
        saida.append((o.consistencia - 9, "Regular", "bom"))
    elif o.consistencia <= 6:
        saida.append((10 - o.consistencia, "Irregular", "ruim"))
    if o.propensao_lesao >= 14:
        saida.append((o.propensao_lesao - 8, "Propenso a lesões", "ruim"))
    elif o.propensao_lesao <= 5:
        saida.append((8 - o.propensao_lesao, "Raramente se machuca", "bom"))
    if f.resistencia >= 15:
        saida.append((f.resistencia - 10, "Fôlego de sobra", "bom"))
    if o.deslealdade >= 15:
        saida.append((o.deslealdade - 10, "Faltoso", "ruim"))
    saida.sort(key=lambda x: -x[0])
    vistos = set()
    final = []
    for _, rotulo, tom in saida:
        if real and tom == "ruim":
            continue
        if rotulo not in vistos:
            vistos.add(rotulo)
            final.append((rotulo, tom))
    return final[:8]


def resumo_de_atributos(j: Jogador) -> List[Tuple[str, int]]:
    """Seis números de 1 a 20 que resumem o atleta (no estilo das cartas)."""
    t, m, f = j.tecnicos, j.mentais, j.fisicos
    if j.posicao == Posicao.GOL:
        g = j.goleiro
        return [("Reflexos", g.reflexos), ("Manejo", g.manejo), ("Jogo aéreo", g.jogo_aereo),
                ("Mano a mano", g.um_contra_um), ("Reposição", g.reposicao), ("Concentração", m.concentracao)]
    return [("Ritmo", round((f.velocidade + f.aceleracao) / 2)), ("Finalização", round((t.finalizacao + t.chute_de_longe) / 2)),
            ("Passe", round((t.passe + m.visao) / 2)), ("Drible", round((t.drible + t.tecnica) / 2)),
            ("Defesa", round((t.desarme + t.marcacao) / 2)), ("Físico", round((f.forca + f.resistencia) / 2))]


def estilos_ea(ref: Dict[str, Any]) -> List[str]:
    saida = []
    for nome in ref.get("estilos_ea", []):
        elite = "(elite)" in nome
        base = nome.replace(" (elite)", "").strip()
        saida.append(ESTILOS_EA.get(base, base) + (" (elite)" if elite else ""))
    return saida

