    return f"{normalizar_nome(clube.pais)}_{normalizar_nome(clube.nome)}"


def mapa_de_ids(almanaques: Sequence[Almanaque]) -> Dict[str, ClubeCatalogado]:
    mapa: Dict[str, ClubeCatalogado] = {}
    for clube in todos_os_clubes(almanaques):
        chave = id_do_clube(clube)
        if chave in mapa:
            chave = f"{chave}_{normalizar_nome(clube.liga)}"
