def _posicao_detalhada(texto: str) -> Optional[Tuple[str, Tuple[str, ...]]]:
    t = " ".join(sem_hifen(texto).lower().split())
    if not t:
        return None
    if any(p in t for p in ("goleiro", "goalkeeper")) or t in ("gk", "gol"):
        return ("Goleiro", ())
    if "zagueiro" in t or "central" in t or "centre back" in t or "center back" in t or t == "cb":
        return ("Zagueiro", ())
    if "lateral" in t or t.startswith("ala") or "full back" in t or t in ("rb", "lb", "lwb", "rwb"):
        return ("Lateral", ())
    if "volante" in t or "defensive mid" in t or t == "dm":
        return ("Volante", ("Meia",))
    if "meia atacante" in t or "meia ofensivo" in t or "attacking mid" in t:
        return ("Meia", ("Ponta",))
    if "meia" in t or "meio" in t or "midfield" in t or t == "mf" or "armador" in t:
        return ("Meia", ("Volante",))
    if "ponta" in t or "extremo" in t or "winger" in t:
        return ("Ponta", ("Meia", "Centroavante"))
    if "atacante" in t or "centroavante" in t or "forward" in t or "striker" in t or t == "fw":
        return ("Centroavante", ("Ponta",))
    if "defens" in t or "defender" in t or t == "df":
        return ("Zagueiro", ("Lateral",))
    return None


def _estrelas_por_clube(referencia: date) -> Dict[str, List[Dict[str, Any]]]:
    """Craques pesquisados com fonte, agrupados pelo clube atual (nome normalizado, sem parênteses)."""
    por_clube: Dict[str, List[Dict[str, Any]]] = {}
    for entradas in carregar_listas_de_craques().values():
        for entrada in entradas:
            clube = str(entrada.get("clube_atual", ""))
            if clube.lower().startswith("sem clube"):
                continue
            base = re.split(r"\s*\(", clube)[0].strip()
            por_clube.setdefault(normalizar_nome(base), []).append(entrada)
    return por_clube


def _mesmo_jogador(nome_lista: str, entrada: Dict[str, Any]) -> bool:
    a = normalizar_nome(nome_lista)
    b = normalizar_nome(str(entrada.get("nome_exibicao", "")))
    completo = normalizar_nome(str(entrada.get("nome_completo", "")))
    return bool(b) and (a == b or (len(b) >= 4 and b in a) or (len(a) >= 4 and a in b) or (completo and a in completo))


REFERENCIAS_BRASIL_CONFLITANTES = {"hulk", "philippecoutinho"}  # almanaque diverge da pesquisa com fonte


def _referencias_do_almanaque(almanaques: Sequence[Almanaque]) -> Dict[str, List[str]]:
    """Jogadores de referência recente do almanaque da América do Sul, por clube (sem os conflitantes)."""
    refs: Dict[str, List[str]] = {}
    for almanaque in almanaques:
        lista = almanaque.dados.get("jogadores", {}).get("brasil_referencias_recentes", {}).get("lista", [])
        for item in lista:
            if normalizar_nome(item.get("nome", "")) in REFERENCIAS_BRASIL_CONFLITANTES:
                continue
            refs.setdefault(normalizar_nome(sem_hifen(item.get("clube", ""))), []).append(sem_hifen(item["nome"]))
    return refs


def importar_elenco_detalhado(dados: Dict[str, Any], catalogado: ClubeCatalogado, clube_id: int, id_inicial: int,
                              referencia: date, estrelas: Sequence[Dict[str, Any]],
                              referencias: Sequence[str]) -> Clube:
    """Clube jogável a partir de um elenco real com posição detalhada (formato da pesquisa da Série A).

    Craque que já tem pesquisa própria entra com os dados dela (nascimento, medidas,
    títulos) e o perfil do Megafut. Os demais entram com o nível típico da liga e do
    clube, mais um ponto para referência do almanaque, meio ponto para o capitão e
    pequena variação fixa pelo nome. Nascimento, pé, altura e peso: CONFIRMAR.
    """
    nivel_base = nivel_tecnico_estimado(catalogado)
    referencias_norm = {normalizar_nome(r) for r in referencias}
    jogadores: List[Jogador] = []
    capitaes: List[Jogador] = []
    proximo = id_inicial
    for item in dados.get("jogadores", []):
        mapeada = _posicao_detalhada(str(item.get("posicao", "")))
        if mapeada is None:
            continue
        posicao, secundarias = mapeada
        nome = sem_hifen(str(item.get("nome_exibicao", ""))).strip()
        if not nome:
            continue
        estrela = next((e for e in estrelas if _mesmo_jogador(nome, e)), None)
        if estrela is not None:
            entrada = dict(estrela)
            entrada["clube_atual"] = catalogado.nome
            nivel = None
        else:
            variacao = (zlib.crc32(("nivel" + nome).encode("utf8")) % 1201) / 1000.0 - 0.6
            destaque = 1.0 if normalizar_nome(nome) in referencias_norm else 0.0
            capitao = 0.5 if item.get("capitao") else 0.0
            nivel = nivel_base + variacao + destaque + capitao
            entrada = {
                "nome_exibicao": nome, "posicao": posicao, "posicoes_secundarias": list(secundarias),
                "data_nascimento": "CONFIRMAR", "nacionalidade": sem_hifen(str(item.get("nacionalidade") or "CONFIRMAR")),
                "pe": "CONFIRMAR", "altura_cm": "CONFIRMAR", "peso_kg": "CONFIRMAR", "clube_atual": catalogado.nome,
                "fontes": [u for u in (dados.get("fonte_elenco"),) if u], "titulos": [],
            }
        jogador = jogador_real(entrada, proximo, referencia, nivel_estimado=nivel)
        proximo += 1
        if jogador is None:
            continue
        if estrela is None:
            jogador.origem = ORIGEM_ELENCO_COM_FONTE
        if item.get("capitao"):
            capitaes.append(jogador)
        jogadores.append(jogador)
    definir_status_e_hierarquia(jogadores)
    for jogador in capitaes:
        jogador.hierarquia = Hierarquia.LIDER
    nome_tecnico = sem_hifen(str(dados.get("tecnico") or "")).strip()
    tecnico = Tecnico(nome=nome_tecnico if nome_tecnico and nome_tecnico != "CONFIRMAR" else "Técnico CONFIRMAR",
                      leitura_de_jogo=13)
    clube = criar_clube_real(catalogado, clube_id, jogadores, tecnico)
    clube.fontes = [u for u in (dados.get("fonte_elenco"), dados.get("fonte_tecnico")) if u] + clube.fontes
    return clube


def carregar_dados_de_elencos() -> List[Dict[str, Any]]:
    elencos: List[Dict[str, Any]] = []
    for nome in ARQUIVOS_DE_ELENCOS:
        try:
            elencos.extend(ler_dados(nome).get("elencos", []))
        except FileNotFoundError:
            continue
    return elencos


class FabricaDeClubes:
    """Monta clubes jogáveis sempre do mesmo jeito (mesmos ids), para carreira, save e amistoso."""

    def __init__(self, almanaques: Optional[Sequence[Almanaque]] = None, referencia: date = REFERENCIA):
        self.almanaques = list(almanaques) if almanaques is not None else carregar_almanaques()
        self.referencia = referencia
        self.ids = mapa_de_ids(self.almanaques)
        self.id_por_objeto = {id(c): chave for chave, c in self.ids.items()}
        self._dados_elencos = {self._chave(e): e for e in carregar_dados_de_elencos()}
        self._estrelas = _estrelas_por_clube(referencia)
        self._referencias = _referencias_do_almanaque(self.almanaques)
        self._almanaque_elencos = {}
        for almanaque in self.almanaques:
            for dados in almanaque.dados.get("elencos", []):
                catalogado = self._catalogado(str(dados.get("clube", "")), str(dados.get("pais", "")))
                if catalogado is not None:
                    self._almanaque_elencos[self.id_por_objeto[id(catalogado)]] = dados

    def _catalogado(self, nome: str, pais: str) -> Optional[ClubeCatalogado]:
        chave = normalizar_nome(nome)
        for clube in self.ids.values():
            if pais and normalizar_nome(pais) != normalizar_nome(clube.pais):
                continue
            if chave in {normalizar_nome(n) for n in clube.nomes()}:
                return clube
        return None

    def _chave(self, dados: Dict[str, Any]) -> str:
        catalogado = self._catalogado(str(dados.get("clube", "")), str(dados.get("pais", "Brasil")))
        return self.id_por_objeto[id(catalogado)] if catalogado is not None else ""

    def tem_elenco(self, clube_id: str) -> bool:
        return clube_id in self._dados_elencos or clube_id in self._almanaque_elencos

    def ids_jogaveis(self) -> List[str]:
        return sorted(set(k for k in self._dados_elencos if k) | set(self._almanaque_elencos))

    def tamanho_do_elenco(self, clube_id: str) -> int:
        dados = self._dados_elencos.get(clube_id) or self._almanaque_elencos.get(clube_id) or {}
        return len(dados.get("jogadores", []))

    def estrelas_do_clube(self, catalogado: ClubeCatalogado) -> List[Dict[str, Any]]:
        encontrados: List[Dict[str, Any]] = []
        for nome in catalogado.nomes():
            encontrados.extend(self._estrelas.get(normalizar_nome(nome), []))
        vistos, unicos = set(), []
        for e in encontrados:
            if e["nome_exibicao"] not in vistos:
                vistos.add(e["nome_exibicao"])
                unicos.append(e)
        return unicos

    def referencias_do_clube(self, catalogado: ClubeCatalogado) -> List[str]:
        nomes: List[str] = []
        for nome in catalogado.nomes():
            nomes.extend(self._referencias.get(normalizar_nome(nome), []))
        return list(dict.fromkeys(nomes))

    def montar(self, clube_id: str, numero: int) -> Clube:
        """Clube jogável número `numero` (define os ids de clube e de jogadores)."""
        catalogado = self.ids[clube_id]
        id_clube = 100 + numero
        id_jogadores = 100_000 + numero * 200
        if clube_id in self._dados_elencos:
            clube = importar_elenco_detalhado(self._dados_elencos[clube_id], catalogado, id_clube, id_jogadores,
                                              self.referencia, self.estrelas_do_clube(catalogado),
                                              self.referencias_do_clube(catalogado))
        elif clube_id in self._almanaque_elencos:
            from .mundo_real import importar_elenco_por_grupos
            clube = importar_elenco_por_grupos(self._almanaque_elencos[clube_id], catalogado, id_clube,
                                               id_jogadores, self.referencia)
        else:
            raise ValueError(f"{catalogado.nome}: elenco real ainda não importado")
        orcamento = orcamento_estimado(catalogado)
        clube.orcamento_transferencias = orcamento["transferencias"]
        clube.orcamento_salarial = orcamento["folha_mensal"]
        clube.satisfacao_torcida = humor_inicial_da_torcida(catalogado)[0]
        clube.satisfacao_diretoria = 60.0
        clube.objetivo = objetivo_relativo(catalogado, self.almanaques)
        return clube


