FATOR_ECONOMICO_DO_PAIS = {  # tamanho relativo do mercado, parâmetro de jogo do Megafut
    "Brasil": 1.0, "México": 0.55, "Estados Unidos": 0.6, "Canadá": 0.08, "Argentina": 0.3, "Uruguai": 0.12,
    "Paraguai": 0.1, "Chile": 0.12, "Colômbia": 0.15, "Equador": 0.12, "Peru": 0.1, "Bolívia": 0.06,
    "Venezuela": 0.04, "Costa Rica": 0.06, "Honduras": 0.04, "Guatemala": 0.04, "El Salvador": 0.03,
    "Panamá": 0.03, "Nicarágua": 0.02, "Belize": 0.01, "Guiana": 0.01, "Suriname": 0.01, "Guiana Francesa": 0.01,
}
RECEITA_AGREGADA_SERIE_A_2025 = 14_900_000_000.0  # EY, exercício de 2025, 20 clubes (almanaque da América do Sul)
CURVA_DA_RECEITA = 0.08
_ANCORA_SERIE_A: Optional[float] = None


def _ancora_brasil() -> float:
    """Receita de jogo de um clube de reputação 70, calibrada para a Série A somar a receita agregada da EY."""
    global _ANCORA_SERIE_A
    if _ANCORA_SERIE_A is None:
        serie_a = [c for c in todos_os_clubes(carregar_almanaques())
                   if c.pais == "Brasil" and c.liga == "Campeonato Brasileiro Série A"]
        soma = sum(math.exp(CURVA_DA_RECEITA * (reputacao_estimada(c) - 70)) for c in serie_a) or 1.0
        _ANCORA_SERIE_A = RECEITA_AGREGADA_SERIE_A_2025 / soma
    return _ANCORA_SERIE_A


def orcamento_estimado(clube: ClubeCatalogado) -> Dict[str, Any]:
    """Orçamento de jogo (estimativa do Megafut). O real fica CONFIRMAR."""
    fator = FATOR_ECONOMICO_DO_PAIS.get(clube.pais, 0.02)
    receita = _ancora_brasil() * math.exp(CURVA_DA_RECEITA * (reputacao_estimada(clube) - 70)) * fator
    if clube.equipe_de_desenvolvimento:
        receita *= 0.1
    transferencias = round(receita * 0.12, -5)
    folha_mensal = round(receita * 0.55 / 12, -4)
    return {"real": "CONFIRMAR", "receita_anual": round(receita, -5), "transferencias": transferencias,
            "folha_mensal": folha_mensal, "estimativa": True,
            "base": "Receita agregada da Série A em 2025 (EY): R$ 14,9 bi; o resto é estimativa do Megafut"}


def humor_inicial_da_torcida(clube: ClubeCatalogado) -> Tuple[float, List[str]]:
    """Humor inicial (0 a 100) a partir de fatos de 2026 do almanaque. Estimativa do Megafut."""
    valor = 60.0
    motivos: List[str] = []
    for conquista in clube.conquistas:
        texto = conquista.lower()
        if "2026" in texto and texto.startswith("campeão do campeonato"):
            valor += 12
            motivos.append(conquista)
        elif "2026" in texto and texto.startswith("vice campeão do campeonato"):
            valor += 4
            motivos.append(conquista)
        elif "campeão da série c 2026" in texto:
            valor += 15
            motivos.append(conquista)
        elif "vice campeã da série c 2026" in texto:
            valor += 8
            motivos.append(conquista)
        elif "mls cup 2025" in texto or "copa centroamericana 2025" in texto:
            valor += 10
            motivos.append(conquista)
        elif "leagues cup 2025" in texto:
            valor += 6
            motivos.append(conquista)
    if clube.grande_torcida and clube.divisao >= 2:
        valor -= 8
        motivos.append("Clube de massa fora da elite: torcida cobra o acesso")
    return max(25.0, min(90.0, valor)), motivos


LIGAS_SEM_REBAIXAMENTO = ("Major League Soccer", "USL Championship", "USL League One", "MLS NEXT Pro",
                          "Canadian Premier League", "Liga MX")


def objetivo_relativo(clube: ClubeCatalogado, almanaques: Sequence[Almanaque]) -> str:
    """Meta da diretoria pela reputação do clube dentro da própria liga (estimativa do Megafut)."""
    if clube.divisao == 0:
        return "CONFIRMAR (divisão de 2026 não informada no almanaque)"
    rivais = [c for c in todos_os_clubes(almanaques) if c.pais == clube.pais and c.liga == clube.liga]
    ordem = sorted(rivais, key=lambda c: (-reputacao_estimada(c), c.nome))
    posicao = next((i for i, c in enumerate(ordem) if c is clube), 0)
    fatia = posicao / max(1, len(ordem))
    if clube.liga in LIGAS_SEM_REBAIXAMENTO:
        if fatia < 0.2:
            return OBJETIVOS[0]
        return "Classificação para a fase final" if fatia < 0.6 else "Evoluir na tabela"
    if clube.divisao >= 2:
        if fatia < 0.25:
            return OBJETIVOS[4]
        return OBJETIVOS[2] if fatia < 0.8 else OBJETIVOS[3]
    if fatia < 0.2:
        return OBJETIVOS[0]
    if fatia < 0.5:
        return OBJETIVOS[1]
    return OBJETIVOS[2] if fatia < 0.8 else OBJETIVOS[3]


def _rivais_com_peso(clube: ClubeCatalogado) -> List[Dict[str, Any]]:
    nomes = {normalizar_nome(n) for n in clube.nomes()}
    saida = []
    for classico in CLASSICOS:
        a = {normalizar_nome(n) for n in classico.clube_a}
        b = {normalizar_nome(n) for n in classico.clube_b}
        if clube.pais not in classico.paises_validos:
            continue
        if nomes & a:
            saida.append({"rival": classico.clube_b[0], "apelido": classico.apelido, "peso": classico.peso})
        elif nomes & b:
            saida.append({"rival": classico.clube_a[0], "apelido": classico.apelido, "peso": classico.peso})
    return sorted(saida, key=lambda r: -r["peso"])


def _titulos_pesquisados(dados_elenco: Optional[Dict[str, Any]]) -> List[str]:
    if not dados_elenco:
        return []
    saida = []
    for t in dados_elenco.get("titulos", []):
        quantidade = t.get("quantidade")
        if not isinstance(quantidade, int) or quantidade <= 0:
            continue
        anos = str(t.get("anos") or "")
        anos = "" if "CONFIRMAR" in anos.upper() else anos
        texto = f"{sem_hifen(str(t.get('competicao', '')))}: {quantidade}"
        if anos and len(anos) <= 60:
            texto += f" ({sem_hifen(anos)})"
        saida.append(texto)
    return saida


def resumo_do_clube(clube: ClubeCatalogado, fabrica: FabricaDeClubes) -> Dict[str, Any]:
    chave = fabrica.id_por_objeto[id(clube)]
    dados_elenco = fabrica._dados_elencos.get(chave)
    titulos = _titulos_pesquisados(dados_elenco)
    if not titulos:
        if clube.libertadores:
            titulos.append(f"Libertadores: {clube.libertadores} (até 2025)")
        if clube.titulos_nacionais:
            titulos.append(f"Títulos nacionais: {clube.titulos_nacionais}")
        titulos.extend(clube.conquistas)
    else:
        titulos.extend(c for c in clube.conquistas if "2026" in c)
    jogadores: List[Dict[str, str]] = []
    for estrela in fabrica.estrelas_do_clube(clube):
        perfil = PERFIS_MEGAFUT.get(estrela["nome_exibicao"])
        jogadores.append({"nome": sem_hifen(estrela["nome_exibicao"]), "detalhe": str(estrela.get("posicao", "")),
                          "origem": "pesquisa com fonte", "nivel": f"{perfil[0]:.1f}".replace(".", ",") if perfil else ""})
    nomes_na_lista = {normalizar_nome(j["nome"]) for j in jogadores}
    for nome in fabrica.referencias_do_clube(clube):
        if normalizar_nome(nome) not in nomes_na_lista:
            jogadores.append({"nome": nome, "detalhe": "", "origem": "referência recente do almanaque", "nivel": ""})
    if dados_elenco:
        for item in dados_elenco.get("jogadores", []):
            if item.get("capitao"):
                nome = sem_hifen(str(item.get("nome_exibicao", "")))
                if normalizar_nome(nome) not in {normalizar_nome(j["nome"]) for j in jogadores}:
                    jogadores.append({"nome": nome, "detalhe": str(item.get("posicao", "")), "origem": "capitão no elenco",
                                      "nivel": ""})
    almanaque_elenco = fabrica._almanaque_elencos.get(chave)
    if almanaque_elenco:
        motivos = almanaque_elenco.get("destaques_motivo", {})
        for nome, motivo in motivos.items():
            jogadores.append({"nome": nome, "detalhe": motivo, "origem": "dossiê", "nivel": ""})
    for referencia in clube.jogadores_referencia:
        nome = referencia.split(" (")[0]
        if normalizar_nome(nome) not in {normalizar_nome(j["nome"]) for j in jogadores}:
            detalhe = referencia[len(nome):].strip(" ()")
            jogadores.append({"nome": nome, "detalhe": detalhe, "origem": "almanaque", "nivel": ""})
    humor, motivos = humor_inicial_da_torcida(clube)
    torcida_fato = ""
    if clube.torcida_pct is not None:
        torcida_fato = f"{clube.torcida_pct:.1f}".replace(".", ",") + "% dos torcedores do país (pesquisa de 2026)"
    elif clube.grande_torcida:
        torcida_fato = "Entre as grandes torcidas do país (lista do almanaque)"
    orcamento = orcamento_estimado(clube)
    if clube.folha_anual_usd:
        orcamento["folha_real_usd"] = clube.folha_anual_usd
    jogavel = fabrica.tem_elenco(chave)
    return {
        "id": chave, "nome": clube.nome, "sigla": sigla_para(clube.nome), "pais": clube.pais, "liga": clube.liga,
        "divisao": clube.divisao, "grupo": clube.grupo, "cidade": clube.cidade, "estado": clube.estado,
        "estadio": clube.estadio, "fundacao": clube.fundacao, "apelidos": clube.apelidos[:3],
        "reputacao": reputacao_estimada(clube), "nivel": round(nivel_tecnico_estimado(clube), 1),
        "titulos": titulos[:8], "jogadores": jogadores[:6], "idolos": clube.idolos[:6],
        "torcida": {"humor": round(humor), "rotulo": rotulo_satisfacao(humor), "motivos": motivos, "fato": torcida_fato},
        "objetivo": objetivo_relativo(clube, fabrica.almanaques), "orcamento": orcamento,
        "classicos": _rivais_com_peso(clube)[:5], "perfil": clube.perfil, "tecnico": (dados_elenco or {}).get("tecnico")
        or clube.tecnico or "", "jogavel": jogavel, "elenco": fabrica.tamanho_do_elenco(chave),
        "fonte": clube.fonte, "situacao": clube.situacao_da_lista,
    }


