_PREFIXOS_DE_ICONE = tuple(emoji + " " for emoji, _texto in _ICONES.values()) + tuple(
    texto + " " for _emoji, texto in _ICONES.values())


def _texto_limpo(texto: str) -> str:
    for prefixo in _PREFIXOS_DE_ICONE:
        if texto.startswith(prefixo):
            return texto[len(prefixo):]
    return texto


def _lado(resultado, clube: Clube) -> Dict[str, Any]:
    st = resultado.stats_de(clube)
    return {
        "nome": clube.nome, "sigla": clube.sigla, "gols": st.gols, "xg": round(st.xg, 2),
        "finalizacoes": st.finalizacoes, "no_alvo": st.no_alvo, "posse": round(resultado.posse(clube)),
        "escanteios": st.escanteios, "faltas": st.faltas, "amarelos": st.amarelos, "vermelhos": st.vermelhos,
        "impedimentos": st.impedimentos, "defesas": st.defesas, "xg_faixa": [round(x, 2) for x in st.xg_por_faixa],
    }


def resultado_para_dict(resultado, ids: Optional[Dict[int, str]] = None) -> Dict[str, Any]:
    ids = ids or {}
    jogadores = []
    for part in resultado.participacoes.values():
        if part.situacao not in (SituacaoJogo.TITULAR, SituacaoJogo.ENTROU):
            continue
        jogadores.append({"id": part.jogador_id, "nome": part.nome, "sigla": part.sigla, "pos": part.posicao.sigla,
                          "titular": part.situacao == SituacaoJogo.TITULAR, "min": part.minutos,
                          "nota": round(part.nota, 1), "gols": part.stats.gols, "ass": part.stats.assistencias})
    melhor = resultado.participacoes.get(resultado.melhor_em_campo_id) if resultado.melhor_em_campo_id else None
    classico = None
    if resultado.peso_classico > 0:
        achado = buscar_classico(resultado.casa.nome, resultado.fora.nome, resultado.casa.pais, resultado.fora.pais)
        classico = {"apelido": achado.apelido if achado else "Clássico", "peso": resultado.peso_classico}
    escalacoes = {}
    for sigla, tat in resultado.taticas_iniciais.items():
        clube = resultado.casa if resultado.casa.sigla == sigla else resultado.fora
        linhas = []
        for vaga in tat.vagas:
            jogador = clube.jogador(vaga.jogador_id)
            if jogador is not None:
                linhas.append({"pos": vaga.posicao.sigla, "lado": vaga.lado.name, "papel": vaga.papel.rotulo,
                               "nome": jogador.nome})
        escalacoes[sigla] = {"formacao": tat.formacao, "tatica": tat.nome, "titulares": linhas}
    return {
        "casa": dict(_lado(resultado, resultado.casa), id=ids.get(resultado.casa.id, "")),
        "fora": dict(_lado(resultado, resultado.fora), id=ids.get(resultado.fora.id, "")),
        "competicao": resultado.competicao, "classico": classico, "acrescimos": dict(resultado.acrescimos),
        "eventos": [{"m": e.minuto_texto, "tipo": e.tipo.name, "texto": _texto_limpo(e.texto), "nivel": e.nivel,
                     "sigla": e.sigla} for e in resultado.eventos if e.nivel <= 2],
        "finalizacoes": [{"m": f.minuto_texto, "sigla": f.sigla, "x": round(f.x, 1), "y": round(f.y, 1),
                          "xg": round(f.xg, 2), "res": f.resultado.name, "jogador": f.finalizador}
                         for f in resultado.finalizacoes],
        "jogadores": sorted(jogadores, key=lambda j: (-j["nota"], j["nome"])),
        "melhor": melhor.nome if melhor else "", "escalacoes": escalacoes,
    }


