def _ordem_posicao(jogador: Jogador) -> int:
    return [Posicao.GOL, Posicao.ZAG, Posicao.LAT, Posicao.VOL, Posicao.MEI, Posicao.PON, Posicao.ATA].index(
        jogador.posicao)


def _texto_idade(jogador: Jogador) -> str:
    nascimento = jogador.data_nascimento or ""
    if not nascimento or "CONFIRMAR" in nascimento.upper():
        return "CONFIRMAR"
    return str(jogador.idade)


class Carreira:
    """Uma temporada de liga com o clube escolhido. Determinística pela semente."""

    def __init__(self, clube_id: str, semente: int = 2026, data_inicio: date = INICIO_DA_TEMPORADA,
                 fabrica: Optional[FabricaDeClubes] = None):
        self.fabrica = fabrica or FabricaDeClubes()
        if clube_id not in self.fabrica.ids:
            raise ValueError("Clube não encontrado no catálogo")
        self.clube_id = clube_id
        self.semente = semente
        catalogado = self.fabrica.ids[clube_id]
        if not self.fabrica.tem_elenco(clube_id):
            raise ValueError(f"{catalogado.nome}: elenco real ainda não importado")
        da_liga = [chave for chave, c in sorted(self.fabrica.ids.items())
                   if c.pais == catalogado.pais and c.liga == catalogado.liga]
        faltando = [self.fabrica.ids[k].nome for k in da_liga if not self.fabrica.tem_elenco(k)]
        if faltando:
            raise ValueError(f"{catalogado.liga}: faltam os elencos de {len(faltando)} clubes ({', '.join(faltando[:4])})")
        self.clubes: List[Clube] = [self.fabrica.montar(chave, numero) for numero, chave in enumerate(da_liga)]
        self.ids_texto: Dict[int, str] = {c.id: chave for c, chave in zip(self.clubes, da_liga)}
        self.usuario = next(c for c in self.clubes if self.ids_texto[c.id] == clube_id)
        ranking = sorted(self.clubes, key=lambda c: (-c.reputacao, c.nome))
        self.taticas_preset: Dict[int, str] = {c.id: preset_por_reputacao(i, len(ranking)) for i, c in enumerate(ranking)}
        taticas = {cid: tatica(preset) for cid, preset in self.taticas_preset.items()}
        self.mundo = MundoMegafut(self.clubes, taticas, data_inicio - timedelta(days=1), semente=semente)
        self.liga = Liga(catalogado.liga, self.clubes, data_inicio, semente=semente)
        self._jogos: Dict[Tuple[int, int, int], Any] = {}
        for partida in self.liga.partidas:
            casa, fora = self.liga.clubes[partida.casa_id], self.liga.clubes[partida.fora_id]
            peso = buscar_classico(casa.nome, fora.nome, casa.pais, fora.pais)
            jogo = self.mundo.agendar(partida.data, casa, fora, self.liga.nome, jogo_grande=peso is not None)
            self._jogos[(partida.rodada, partida.casa_id, partida.fora_id)] = jogo
        self.noticias: List[str] = []
        self.ultima_partida: Optional[Dict[str, Any]] = None

    # --------------------------------------------------------------
    def definir_tatica(self, preset: str) -> None:
        if preset in TATICAS:
            self.taticas_preset[self.usuario.id] = preset
            self.mundo.taticas[self.usuario.id] = tatica(preset)

    def jogar_proxima_rodada(self) -> Dict[str, Any]:
        rodada = self.liga.proxima_rodada()
        if rodada is None:
            return {"fim": True, "estado": self.estado()}
        partidas = self.liga.partidas_da_rodada(rodada)
        ultima_data = max(p.data for p in partidas)
        noticias: List[str] = []
        mudancas = []
        while self.mundo.data <= ultima_data:
            relatorio = self.mundo.avancar_dia()
            noticias.extend(relatorio.noticias)
            mudancas.extend(relatorio.mudancas_moral.get(self.usuario.sigla, []))
        partida_usuario = None
        outros = []
        for partida in partidas:
            jogo = self._jogos.pop((partida.rodada, partida.casa_id, partida.fora_id), None)
            if jogo is None or jogo.resultado is None:
                continue
            r = jogo.resultado
            self.liga.registrar(partida, r.gols_casa, r.gols_fora)
            if self.usuario in (r.casa, r.fora):
                partida_usuario = resultado_para_dict(r, self.ids_texto)
            else:
                outros.append({"casa": r.casa.nome, "fora": r.fora.nome, "casa_sigla": r.casa.sigla,
                               "fora_sigla": r.fora.sigla, "gols_casa": r.gols_casa, "gols_fora": r.gols_fora})
            if jogo in self.mundo.agenda:
                self.mundo.agenda.remove(jogo)
        del self.mundo.historico[:-3]
        nomes_do_clube = {j.nome for j in self.usuario.elenco} | {self.usuario.nome, self.usuario.sigla}
        importantes = [n for n in noticias if any(nome in n for nome in nomes_do_clube)]
        self.noticias = (importantes + self.noticias)[:40]
        self.ultima_partida = partida_usuario
        moral = [{"nome": m.jogador.nome, "antes": round(m.antes), "depois": round(m.depois), "motivo": m.motivo}
                 for m in sorted(mudancas, key=lambda m: -abs(m.depois - m.antes))[:6]]
        return {"fim": False, "rodada": rodada, "partida": partida_usuario, "outros": outros,
                "tabela": self.tabela(), "estado": self.estado(), "noticias": importantes[:10], "moral": moral}

    # --------------------------------------------------------------
    def estado(self) -> Dict[str, Any]:
        u = self.usuario
        linha = self.liga.linhas[u.id]
        proxima = self.liga.proxima_partida_do_clube(u.id)
        proximo = None
        if proxima is not None:
            casa = proxima.casa_id == u.id
            adversario = self.liga.clubes[proxima.fora_id if casa else proxima.casa_id]
            classico = buscar_classico(u.nome, adversario.nome, u.pais, adversario.pais)
            proximo = {"rodada": proxima.rodada, "data": proxima.data.strftime("%d/%m/%Y"), "casa": casa,
                       "adversario": {"id": self.ids_texto[adversario.id], "nome": adversario.nome,
                                      "sigla": adversario.sigla, "posicao": self.liga.posicao(adversario.id)},
                       "classico": {"apelido": classico.apelido, "peso": classico.peso} if classico else None}
        fim = self.liga.proxima_rodada() is None
        tabela = self.liga.classificacao()
        estado = {
            "clube": {"id": self.clube_id, "nome": u.nome, "sigla": u.sigla, "tecnico": u.tecnico.nome,
                      "estadio": u.estadio, "liga": self.liga.nome},
            "data": self.mundo.data.strftime("%d/%m/%Y"), "rodada": self.liga.ultima_rodada_jogada(),
            "total_rodadas": self.liga.total_rodadas, "posicao": self.liga.posicao(u.id), "clubes_na_liga": len(tabela),
            "pontos": linha.pontos, "jogos": linha.jogos, "v": linha.vitorias, "e": linha.empates, "d": linha.derrotas,
            "gp": linha.gols_pro, "gc": linha.gols_contra, "ultimos": list(linha.ultimos),
            "objetivo": u.objetivo, "torcida": {"valor": round(u.satisfacao_torcida),
                                                "rotulo": rotulo_satisfacao(u.satisfacao_torcida)},
            "diretoria": {"valor": round(u.satisfacao_diretoria), "rotulo": rotulo_satisfacao(u.satisfacao_diretoria)},
            "moral_media": round(u.moral_media()),
            "orcamento": {"transferencias": u.orcamento_transferencias, "folha_mensal": u.orcamento_salarial,
                          "estimativa": True},
            "tatica": self.taticas_preset[u.id],
            "taticas": [{"id": k, "nome": v[0], "descricao": v[1]} for k, v in TATICAS.items()],
            "proximo": proximo, "fim": fim, "noticias": self.noticias[:12],
        }
        if fim:
            campeao = tabela[0]
            estado["campeao"] = campeao.nome
            estado["avaliacao"] = self._avaliacao_final()
        return estado

    def _avaliacao_final(self) -> str:
        posicao = self.liga.posicao(self.usuario.id)
        total = len(self.liga.clubes)
        objetivo = self.usuario.objetivo
        metas = {OBJETIVOS[0]: 1, OBJETIVOS[1]: 6, OBJETIVOS[2]: total - 6, OBJETIVOS[3]: total - 4}
        alvo = metas.get(objetivo)
        if alvo is None:
            return f"Terminou em {posicao}º lugar."
        if posicao <= alvo:
            return f"Objetivo cumprido: {posicao}º lugar (meta: {objetivo.lower()})."
        return f"Objetivo não cumprido: {posicao}º lugar (meta: {objetivo.lower()})."

    def tabela(self) -> List[Dict[str, Any]]:
        saida = []
        for posicao, l in enumerate(self.liga.classificacao(), start=1):
            saida.append({"pos": posicao, "id": self.ids_texto[l.clube_id], "nome": l.nome, "sigla": l.sigla,
                          "p": l.pontos, "j": l.jogos, "v": l.vitorias, "e": l.empates, "d": l.derrotas,
                          "gp": l.gols_pro, "gc": l.gols_contra, "sg": l.saldo, "ultimos": list(l.ultimos),
                          "usuario": l.clube_id == self.usuario.id})
        return saida

    def calendario(self) -> List[Dict[str, Any]]:
        u = self.usuario
        saida = []
        for p in self.liga.partidas:
            if u.id not in (p.casa_id, p.fora_id):
                continue
            casa = p.casa_id == u.id
            adversario = self.liga.clubes[p.fora_id if casa else p.casa_id]
            item = {"rodada": p.rodada, "data": p.data.strftime("%d/%m/%Y"), "casa": casa, "adversario": adversario.nome,
                    "sigla": adversario.sigla, "jogada": p.jogada}
            if p.jogada:
                pro, contra = (p.gols_casa, p.gols_fora) if casa else (p.gols_fora, p.gols_casa)
                item.update(pro=pro, contra=contra, letra="V" if pro > contra else ("E" if pro == contra else "D"))
            saida.append(item)
        return saida

    def elenco(self, clube_id: Optional[str] = None) -> List[Dict[str, Any]]:
        clube = self.usuario
        if clube_id:
            clube = next((c for c in self.clubes if self.ids_texto[c.id] == clube_id), self.usuario)
        saida = []
        for j in sorted(clube.elenco, key=lambda j: (_ordem_posicao(j), -nivel_geral(j))):
            saida.append({
                "id": j.id, "nome": j.nome, "pos": j.posicao.sigla, "sec": [p.sigla for p in j.posicoes_secundarias],
                "nivel": round(nivel_geral(j), 1), "moral": round(j.moral), "condicao": round(j.condicao),
                "ritmo": round(j.ritmo_de_jogo), "status": j.status.rotulo, "lesao": j.dias_lesionado,
                "suspenso": j.suspenso_jogos, "jogos": j.jogos, "gols": j.gols, "ass": j.assistencias,
                "media": round(j.soma_notas / j.jogos, 1) if j.jogos else None, "nacionalidade": j.nacionalidade,
                "idade": _texto_idade(j), "altura": j.altura_cm, "lider": j.hierarquia == Hierarquia.LIDER,
                "insatisfeito": j.insatisfeito, "craque": j.nome in PERFIS_MEGAFUT or j.origem != ORIGEM_ELENCO_COM_FONTE
                and "pesquisados" in j.origem.lower(),
            })
        return saida

    # --------------------------------------------------------------
    def salvar(self) -> Dict[str, Any]:
        """Save compacto: o resto se reconstrói pelos dados e pela semente."""
        estado_rng = self.mundo.rng.getstate()
        jogadores = {}
        for clube in self.clubes:
            for j in clube.elenco:
                jogadores[str(j.id)] = [round(j.moral, 2), round(j.condicao, 2), round(j.ritmo_de_jogo, 2),
                                        j.dias_lesionado, j.suspenso_jogos, j.amarelos_acumulados, j.jogos_sem_atuar,
                                        j.jogos_sem_ser_titular, int(j.insatisfeito), j.jogos, j.gols,
                                        j.assistencias, round(j.soma_notas, 2), j.peso_kg]
        return {
            "versao": 1, "clube_id": self.clube_id, "semente": self.semente,
            "data": self.mundo.data.isoformat(), "rng": [estado_rng[0], list(estado_rng[1]), estado_rng[2]],
            "partidas": [[p.rodada, p.casa_id, p.fora_id, p.gols_casa, p.gols_fora] for p in self.liga.partidas
                         if p.jogada],
            "clubes": {str(c.id): [round(c.satisfacao_torcida, 2), round(c.satisfacao_diretoria, 2),
                                   list(c.ultimos_resultados), c.saldo_caixa] for c in self.clubes},
            "jogadores": jogadores, "taticas": {str(k): v for k, v in self.taticas_preset.items()},
            "noticias": self.noticias[:40],
        }

    @classmethod
    def carregar(cls, dados: Dict[str, Any], fabrica: Optional[FabricaDeClubes] = None) -> "Carreira":
        carreira = cls(dados["clube_id"], int(dados.get("semente", 2026)), fabrica=fabrica)
        indice = {(p.rodada, p.casa_id, p.fora_id): p for p in carreira.liga.partidas}
        for rodada, casa_id, fora_id, gols_casa, gols_fora in dados.get("partidas", []):
            partida = indice.get((rodada, casa_id, fora_id))
            if partida is None:
                continue
            carreira.liga.registrar(partida, gols_casa, gols_fora)
            jogo = carreira._jogos.pop((rodada, casa_id, fora_id), None)
            if jogo is not None and jogo in carreira.mundo.agenda:
                carreira.mundo.agenda.remove(jogo)
        por_id = {c.id: c for c in carreira.clubes}
        for chave, valores in dados.get("clubes", {}).items():
            clube = por_id.get(int(chave))
            if clube is None:
                continue
            clube.satisfacao_torcida, clube.satisfacao_diretoria, ultimos, clube.saldo_caixa = valores
            clube.ultimos_resultados = list(ultimos)
        jogadores = {j.id: j for c in carreira.clubes for j in c.elenco}
        for chave, v in dados.get("jogadores", {}).items():
            j = jogadores.get(int(chave))
            if j is None:
                continue
            (j.moral, j.condicao, j.ritmo_de_jogo, j.dias_lesionado, j.suspenso_jogos, j.amarelos_acumulados,
             j.jogos_sem_atuar, j.jogos_sem_ser_titular, insatisfeito, j.jogos, j.gols, j.assistencias,
             j.soma_notas, j.peso_kg) = v
            j.insatisfeito = bool(insatisfeito)
        for chave, preset in dados.get("taticas", {}).items():
            cid = int(chave)
            if cid in carreira.taticas_preset and preset in TATICAS:
                carreira.taticas_preset[cid] = preset
                carreira.mundo.taticas[cid] = tatica(preset)
        carreira.mundo.data = date.fromisoformat(dados["data"])
        versao, interno, gauss = dados["rng"]
        carreira.mundo.rng.setstate((versao, tuple(interno), gauss))
        carreira.noticias = list(dados.get("noticias", []))
        return carreira


# ============================================================================
# Partida rápida: qualquer clube com elenco, mais as duas seleções de craques
# ============================================================================

SELECOES = {"selecao_brasileirao": "Seleção do Brasileirão", "selecao_americas": "Seleção das Américas"}


def montar_clube_para_amistoso(clube_id: str, numero: int, fabrica: FabricaDeClubes) -> Clube:
    if clube_id in SELECOES:
        grupos = carregar_craques(carregar_listas_de_craques(), fabrica.referencia, id_inicial=10_000 + numero * 500)
        if clube_id == "selecao_brasileirao":
            return montar_selecao("Seleção do Brasileirão", "BRA", grupos["brasileirao"], 900 + numero,
                                  tecnico_de_selecao("Comissão do Brasileirão", ousado=False), "Brasil")
        return montar_selecao("Seleção das Américas", "AME", grupos["americas"], 900 + numero,
                              tecnico_de_selecao("Comissão das Américas", ousado=True), "Américas")
    return fabrica.montar(clube_id, numero)


def amistoso(casa_id: str, fora_id: str, semente: int = 2026, fabrica: Optional[FabricaDeClubes] = None,
             tatica_casa: str = "", tatica_fora: str = "") -> Dict[str, Any]:
    fabrica = fabrica or FabricaDeClubes()
    casa = montar_clube_para_amistoso(casa_id, 1, fabrica)
    fora = montar_clube_para_amistoso(fora_id, 2, fabrica)
    if casa.sigla == fora.sigla:
        fora.sigla = (fora.sigla[:2] + "2")[:3]
    preset_casa = tatica_casa or ("posse" if casa.reputacao >= fora.reputacao else "equilibrada")
    preset_fora = tatica_fora or ("contragolpe" if fora.reputacao < casa.reputacao else "equilibrada")
    classico = buscar_classico(casa.nome, fora.nome, casa.pais, fora.pais)
    resultado = simular_partida(casa, fora, escalar_melhor_time(casa, tatica(preset_casa)),
                                escalar_melhor_time(fora, tatica(preset_fora)), semente=semente,
                                jogo_grande=classico is not None, competicao="Amistoso",
                                peso_classico=classico.peso if classico else 0.0)
    return resultado_para_dict(resultado, {casa.id: casa_id, fora.id: fora_id})


def clubes_para_partida_rapida(fabrica: Optional[FabricaDeClubes] = None) -> List[Dict[str, Any]]:
    fabrica = fabrica or FabricaDeClubes()
    saida = [{"id": chave, "nome": nome, "grupo": "Seleções de craques"} for chave, nome in SELECOES.items()]
    for chave in fabrica.ids_jogaveis():
        clube = fabrica.ids[chave]
        saida.append({"id": chave, "nome": clube.nome, "grupo": f"{clube.liga} ({clube.pais})"})
    return saida

