"""Carreira do técnico: confiança da diretoria, metas por competição, patrocinadores, comunicações internas,
sala de imprensa, propostas de outros clubes e risco de demissão.

Tudo aqui é regra do jogo (estimativa do Megafut). Patrocinadores são marcas fictícias geradas pelo jogo.
"""
from __future__ import annotations

import math
import random
from datetime import date
from typing import Any, Dict, List, Optional

SETORES = {
    "dm": "Departamento médico", "diretoria": "Diretoria", "imprensa": "Assessoria de imprensa",
    "patrocinio": "Marketing e patrocínio", "base": "Categorias de base", "financeiro": "Financeiro",
    "carreira": "Seu empresário",
}

_MARCA_A = ("Banco", "Construtora", "Rede", "Supermercados", "Laboratório", "Seguros", "Energia", "Transportes",
            "Telecom", "Atacado", "Farmácias", "Concessionária", "Universidade", "Cervejaria", "Agro", "Imobiliária",
            "Combustíveis", "Água Mineral", "Moda", "Móveis")
_MARCA_B = ("Horizonte", "Atlântico", "Sertão Forte", "Litoral", "Aurora", "Pioneira", "Vale Verde", "Cruzeiro do Sul",
            "Estrela Guia", "Nova Era", "Boa Vista", "Rio Claro", "Serra Azul", "Primavera", "Ponte Nova", "Mar Aberto",
            "Bandeirante", "Sol Nascente", "Terra Firme", "Lagoa Grande")

PESO_DA_COMPETICAO = {"liga": 1.0, "copa": 0.8, "continental": 1.0, "supercopa": 0.3, "estadual": 0.5,
                      "regional": 0.5}


def tipo_da_competicao(comp: Any) -> str:
    if comp.tipo in ("continental", "copa", "supercopa"):
        return comp.tipo
    if comp.regras.get("liga"):
        return "liga"
    if "EST" in comp.id:
        return "estadual"
    return "regional"


class CarreiraDoTecnico:
    def __init__(self, reputacao: int = 30) -> None:
        self.reputacao = int(max(15, min(95, reputacao)))
        self.confianca = 65.0
        self.passagens: List[Dict[str, Any]] = []
        self.metas: Dict[str, Dict[str, Any]] = {}
        self.ofertas_patrocinio: List[Dict[str, Any]] = []
        self.patrocinadores: List[Dict[str, Any]] = []
        self.comunicados: List[Dict[str, Any]] = []
        self.coletiva: Optional[Dict[str, Any]] = None
        self.promessa: str = ""
        self.ofertas_emprego: List[Dict[str, Any]] = []
        self.desempregado = False
        self.ultima_oferta = 0
        self.titulos: List[List[Any]] = []
        self.temas_recentes: List[str] = []
        self.vazamento: Optional[Dict[str, Any]] = None
        self.promessas_minutos: List[Dict[str, Any]] = []
        self.insatisfeitos: Dict[str, int] = {}

    # ------------------------------------------------------------------
    CAMPOS = ("reputacao", "confianca", "passagens", "metas", "ofertas_patrocinio", "patrocinadores", "comunicados",
              "coletiva", "promessa", "ofertas_emprego", "desempregado", "ultima_oferta", "titulos",
              "temas_recentes", "vazamento", "promessas_minutos", "insatisfeitos")

    def para_dict(self) -> Dict[str, Any]:
        d = {c: getattr(self, c) for c in self.CAMPOS}
        d["comunicados"] = self.comunicados[:120]
        return d

    @classmethod
    def de_dict(cls, d: Optional[Dict[str, Any]], reputacao: int) -> "CarreiraDoTecnico":
        c = cls(reputacao)
        for campo in cls.CAMPOS:
            if d and campo in d:
                setattr(c, campo, d[campo])
        return c

    # ------------------------------------------------------------------
    def comunicar(self, dia: date, setor: str, texto: str, importante: bool = False) -> None:
        self.comunicados.insert(0, {"data": dia.strftime("%d/%m/%Y"), "setor": setor, "texto": texto,
                                    "importante": importante})
        del self.comunicados[150:]

    def passagem_atual(self) -> Optional[Dict[str, Any]]:
        return self.passagens[-1] if self.passagens and not self.passagens[-1].get("fim") else None

    def iniciar_passagem(self, clube_id: int, nome: str, dia: date) -> None:
        self.passagens.append({"clube": clube_id, "nome": nome, "inicio": dia.strftime("%d/%m/%Y"), "fim": "",
                               "j": 0, "v": 0, "e": 0, "d": 0, "titulos": [], "saida": ""})
        self.confianca = 65.0
        self.metas = {}
        self.patrocinadores = []
        self.ofertas_patrocinio = []
        self.coletiva = None
        self.promessa = ""
        self.ultima_oferta = dia.toordinal()  # ninguém faz proposta na primeira semana de trabalho

    def encerrar_passagem(self, dia: date, motivo: str) -> None:
        p = self.passagem_atual()
        if p is not None:
            p["fim"] = dia.strftime("%d/%m/%Y")
            p["saida"] = motivo

    # ------------------------------------------------------------------
    @staticmethod
    def chance_de_vitoria(forca_eu: float, forca_rival: float, em_casa: bool) -> float:
        """Probabilidade aproximada de vitória pela diferença de força (nível de 0 a 20)."""
        x = 1.1 * (forca_eu - forca_rival) + (0.3 if em_casa else -0.3)
        return 1.0 / (1.0 + math.exp(-x))

    def apos_jogo(self, gols_pro: int, gols_contra: int, p_vitoria: float, peso: float) -> float:
        p = self.passagem_atual()
        if p is not None:
            p["j"] += 1
            p["v" if gols_pro > gols_contra else ("e" if gols_pro == gols_contra else "d")] += 1
        pontos = 3 if gols_pro > gols_contra else (1 if gols_pro == gols_contra else 0)
        esperado = 3 * p_vitoria + 0.27 * (1 - abs(2 * p_vitoria - 1)) * 3 / 3
        delta = (pontos - esperado) * 2.4 * peso
        if self.promessa == "favorito" and pontos < 3:
            delta -= 2.5
        elif self.promessa == "azarao" and pontos > 0:
            delta += 1.5
        self.promessa = ""
        self.confianca = max(0.0, min(100.0, self.confianca + delta))
        return delta

    def limiar_de_demissao(self, reputacao_clube: int) -> float:
        """Diretoria ambiciosa (clube grande) tem menos paciência."""
        return 14.0 + 0.22 * reputacao_clube

    def risco(self, reputacao_clube: int) -> str:
        folga = self.confianca - self.limiar_de_demissao(reputacao_clube)
        return "alto" if folga < 5 else ("médio" if folga < 18 else "baixo")

    def sorteia_demissao(self, reputacao_clube: int, rng: random.Random) -> bool:
        limiar = self.limiar_de_demissao(reputacao_clube)
        if self.confianca >= limiar:
            return False
        return rng.random() < min(0.6, (limiar - self.confianca) / 30.0)

    # ------------------------------------------------------------------
    @staticmethod
    def nome_de_marca(rng: random.Random) -> str:
        return f"{rng.choice(_MARCA_A)} {rng.choice(_MARCA_B)}"

    def gerar_patrocinios(self, ano: int, receita: float, rng: random.Random) -> List[Dict[str, Any]]:
        livres = 3 - len([p for p in self.patrocinadores if p["ate"] >= ano])
        self.patrocinadores = [p for p in self.patrocinadores if p["ate"] >= ano]
        if livres <= 0:
            self.ofertas_patrocinio = []
            return []
        usados = {p["nome"] for p in self.patrocinadores}
        ofertas = []
        while len(ofertas) < 6:
            nome = self.nome_de_marca(rng)
            if nome in usados:
                continue
            usados.add(nome)
            temporadas = rng.choice((1, 1, 2, 2, 3))
            valor = receita * rng.uniform(0.03, 0.075) * (1.0 + 0.04 * (temporadas - 1))
            bonus = valor * rng.uniform(0.06, 0.18)
            ofertas.append({"id": len(ofertas), "nome": nome, "anual": round(valor, -3), "temporadas": temporadas,
                            "bonus_meta": round(bonus, -3), "ate": ano + temporadas - 1})
        self.ofertas_patrocinio = ofertas
        return ofertas

    def receita_mensal_patrocinio(self, ano: int) -> float:
        return sum(p["anual"] / 12.0 for p in self.patrocinadores if p["ate"] >= ano)

    # ------------------------------------------------------------------
    @staticmethod
    def texto_da_meta(alvo: int, total: int, tipo: str) -> str:
        if alvo <= 1:
            return "Ser campeão"
        if tipo == "liga":
            return f"Terminar entre os {alvo} primeiros"
        if alvo > 32 or alvo >= total * 0.5:
            return "Avançar pelo menos uma fase"
        nomes = {2: "Chegar à final", 4: "Chegar à semifinal", 8: "Chegar às quartas de final",
                 16: "Chegar às oitavas de final", 32: "Passar da primeira fase"}
        return nomes.get(alvo, f"Terminar entre os {alvo} primeiros")

arquivos.megafut/coletiva.py:
"""Sala de imprensa: banco de perguntas que mudam com o momento do clube.

Cada pergunta tem um tema e uma condição; cada resposta tem efeitos (moral do elenco ou de um jogador, torcida,
confiança da diretoria, verba, promessa de resultado) e um texto de consequência. Regras do jogo.
"""
from __future__ import annotations

import random
from typing import Any, Callable, Dict, List

Pergunta = Dict[str, Any]


def _feminino(nome: str) -> bool:
    primeira = nome.split()[0].lower() if nome else ""
    return primeira in ("copa", "recopa", "supercopa", "liga", "conmebol", "concacaf", "primera", "série", "taça")


def no(nome: str) -> str:
    return ("na " if _feminino(nome) else "no ") + nome


def pelo(nome: str) -> str:
    return ("pela " if _feminino(nome) else "pelo ") + nome


def _op(texto: str, consequencia: str, **efeitos: Any) -> Dict[str, Any]:
    return {"texto": texto, "consequencia": consequencia, "efeitos": efeitos}


def _confronto(c: Dict[str, Any], rng: random.Random) -> Pergunta:
    rival, comp = c["rival"], c["comp"]
    if c["final"]:
        texto = rng.choice((f"É decisão contra o {rival}. O que muda na preparação?",
                            f"Jogo grande valendo vaga contra o {rival}. Como o grupo chega?"))
        return {"tema": "decisao", "texto": texto, "opcoes": [
            _op("Decisão se ganha com cabeça fria", "O elenco entra mais concentrado.", moral=2),
            _op("Viemos para levantar a taça", "A torcida vibrou, a diretoria vai cobrar.", promessa="favorito", torcida=3),
            _op("O peso está do lado deles", "Menos pressão no vestiário; a torcida não gostou.", promessa="azarao",
                torcida=-2, moral=1)]}
    if c["classico"]:
        texto = rng.choice((f"Semana de clássico contra o {rival}. O que vale esse jogo?",
                            f"A cidade só fala do clássico com o {rival}. Recado para a torcida?"))
        return {"tema": "classico", "texto": texto, "opcoes": [
            _op("Clássico não tem favorito", "Resposta equilibrada, sem polêmica."),
            _op("Vamos impor nosso jogo, a cidade é nossa", "A torcida comprou a ideia; a diretoria quer a vitória.",
                promessa="favorito", torcida=4, moral=2),
            _op("Eles têm mais investimento, vamos competir", "Tirou a pressão do elenco, mas irritou a torcida.",
                promessa="azarao", torcida=-3, moral=1)]}
    variantes = (f"Como você vê o jogo contra o {rival} {pelo(comp)}?",
                 f"O que esperar do {rival}?", f"Qual o plano para enfrentar o {rival}?")
    return {"tema": "confronto", "texto": rng.choice(variantes), "opcoes": [
        _op("Somos favoritos e vamos buscar a vitória", "A diretoria vai cobrar a vitória.", promessa="favorito", moral=1),
        _op("Respeito o adversário, mas jogamos para vencer", "Resposta equilibrada, sem polêmica."),
        _op("O adversário é melhor, vamos competir", "O elenco sentiu menos pressão; a torcida não gostou.",
