def montar_coletiva(contexto: Dict[str, Any], recentes: List[str], rng: random.Random) -> List[Pergunta]:
    """Uma pergunta sobre o jogo e mais duas sobre o momento do clube, evitando repetir temas recentes."""
    perguntas = [_confronto(contexto, rng)]
    possiveis = [p for p in (f(contexto, rng) for f in _temas()) if p]
    novos = [p for p in possiveis if p["tema"] not in recentes[:3] or (p.get("prioridade") and p["tema"] not in recentes[:2])]
    rng.shuffle(novos)
    novos.sort(key=lambda p: -p.get("prioridade", 0))  # polêmica quente sempre entra
    escolhidas = novos[:2]
    if len(escolhidas) < 2:
        resto = [p for p in possiveis if p not in escolhidas]
        rng.shuffle(resto)
        escolhidas += resto[:2 - len(escolhidas)]
    return perguntas + escolhidas

