"""Competições: liga em pontos corridos, com turno, returno e tabela.

O calendário sai pelo método do círculo: cada clube enfrenta todos os outros
uma vez em casa e uma vez fora. A ordem dos confrontos é sorteada pela
semente, então a mesma semente repete o mesmo calendário.

Critérios de desempate aplicados: pontos, vitórias, saldo de gols e gols
marcados. Confronto direto e cartões ainda não entram.
"""
from __future__ import annotations

import random
from dataclasses import dataclass, field
from datetime import date, timedelta
from typing import Dict, List, Optional, Sequence, Tuple

from .entidades import Clube


@dataclass
class LinhaTabela:
    clube_id: int
    nome: str
    sigla: str
    jogos: int = 0
    vitorias: int = 0
    empates: int = 0
    derrotas: int = 0
    gols_pro: int = 0
    gols_contra: int = 0
    ultimos: List[str] = field(default_factory=list)  # "V", "E", "D", do mais antigo ao mais recente

    @property
    def pontos(self) -> int:
        return 3 * self.vitorias + self.empates

    @property
    def saldo(self) -> int:
        return self.gols_pro - self.gols_contra

    @property
    def aproveitamento(self) -> float:
        return 100.0 * self.pontos / (3 * self.jogos) if self.jogos else 0.0

    def registrar(self, pro: int, contra: int) -> None:
        self.jogos += 1
        self.gols_pro += pro
        self.gols_contra += contra
        if pro > contra:
            self.vitorias += 1
            self.ultimos.append("V")
        elif pro == contra:
            self.empates += 1
            self.ultimos.append("E")
        else:
            self.derrotas += 1
            self.ultimos.append("D")
        del self.ultimos[:-5]


@dataclass
class PartidaDaLiga:
    rodada: int
    data: date
    casa_id: int
    fora_id: int
    gols_casa: Optional[int] = None
    gols_fora: Optional[int] = None

    @property
    def jogada(self) -> bool:
        return self.gols_casa is not None


def calendario_turno_e_returno(ids: Sequence[int]) -> List[List[Tuple[int, int]]]:
    """Rodadas de (mandante, visitante). Com número ímpar de clubes, um folga por rodada."""
    times: List[Optional[int]] = list(ids)
    if len(times) % 2:
        times.append(None)
    n = len(times)
    fixo, giro = times[0], times[1:]
    turno: List[List[Tuple[int, int]]] = []
    for numero in range(n - 1):
        ordem = [fixo] + giro
        jogos = []
        for i in range(n // 2):
            a, b = ordem[i], ordem[n - 1 - i]
            if a is None or b is None:
                continue
            jogos.append((a, b) if (numero + i) % 2 == 0 else (b, a))
        turno.append(jogos)
        giro = giro[-1:] + giro[:-1]
    returno = [[(fora, casa) for casa, fora in rodada] for rodada in turno]
    return turno + returno


class Liga:
    """Liga em pontos corridos com calendário fixo e tabela atualizada a cada jogo."""

    def __init__(self, nome: str, clubes: Sequence[Clube], data_inicio: date, semente: int = 0,
                 dias_entre_rodadas: Sequence[int] = (3, 4), turnos: int = 2,
                 datas: Optional[Sequence[date]] = None):
        self.nome = nome
        self.clubes: Dict[int, Clube] = {c.id: c for c in clubes}
        ordem = sorted(self.clubes)
        random.Random(semente).shuffle(ordem)
        self.partidas: List[PartidaDaLiga] = []
        rodadas = calendario_turno_e_returno(ordem)
        if turnos == 1:
            rodadas = rodadas[: len(rodadas) // 2]
        data = data_inicio
        for numero, jogos in enumerate(rodadas, start=1):
            if datas is not None and numero <= len(datas):
                data = datas[numero - 1]
            for casa_id, fora_id in jogos:
                self.partidas.append(PartidaDaLiga(numero, data, casa_id, fora_id))
            data += timedelta(days=dias_entre_rodadas[(numero - 1) % len(dias_entre_rodadas)])
        self.linhas: Dict[int, LinhaTabela] = {cid: LinhaTabela(cid, c.nome, c.sigla) for cid, c in self.clubes.items()}

    @property
    def total_rodadas(self) -> int:
        return max((p.rodada for p in self.partidas), default=0)

    def partidas_da_rodada(self, rodada: int) -> List[PartidaDaLiga]:
        return [p for p in self.partidas if p.rodada == rodada]

    def proxima_rodada(self) -> Optional[int]:
        pendentes = [p.rodada for p in self.partidas if not p.jogada]
        return min(pendentes) if pendentes else None

    def ultima_rodada_jogada(self) -> int:
        jogadas = [p.rodada for p in self.partidas if p.jogada]
        return max(jogadas) if jogadas else 0

    def proxima_partida_do_clube(self, clube_id: int) -> Optional[PartidaDaLiga]:
        pendentes = [p for p in self.partidas if not p.jogada and clube_id in (p.casa_id, p.fora_id)]
        return min(pendentes, key=lambda p: (p.rodada, p.data)) if pendentes else None

    def registrar(self, partida: PartidaDaLiga, gols_casa: int, gols_fora: int) -> None:
        if partida.jogada:
            return
        partida.gols_casa, partida.gols_fora = gols_casa, gols_fora
        self.linhas[partida.casa_id].registrar(gols_casa, gols_fora)
        self.linhas[partida.fora_id].registrar(gols_fora, gols_casa)

    def classificacao(self) -> List[LinhaTabela]:
        return sorted(self.linhas.values(),
                      key=lambda l: (-l.pontos, -l.vitorias, -l.saldo, -l.gols_pro, l.nome))

    def rodadas_por_turno(self) -> int:
        return max(1, len(self.clubes) - 1 + (len(self.clubes) % 2))

    def posicao(self, clube_id: int) -> int:
        for indice, linha in enumerate(self.classificacao(), start=1):
            if linha.clube_id == clube_id:
                return indice
        return 0

