"""Escalação automática: titulares, banco, capitão e cobradores de bola parada."""
from __future__ import annotations

from typing import List, Optional, Set

from .avaliacao import PAPEIS_DE_GOLEIRO, PESOS_ESPECIAIS, adequacao_posicao, composto_fase, media_ponderada, nivel_geral
from .entidades import Clube, Jogador
from .enums import Fase, Hierarquia, InstrucaoIndividual, Lado, Papel, Posicao
from .tatica import PERFIS, Tatica, Vaga


def fator_de_prontidao(jogador: Jogador) -> float:
    """Jogador cansado ou de moral baixa perde prioridade na escalação."""
    return (0.80 + 0.20 * jogador.condicao / 100.0) * (0.97 + 0.06 * jogador.moral / 100.0)


def fator_do_pe(jogador: Jogador, vaga: Vaga) -> float:
    """Lateral e ponta rendem melhor com o pé do lado certo; o ponta invertido, com o pé trocado."""
    if vaga.lado == Lado.CENTRO:
        return 1.0
    lado = getattr(jogador, "lado_origem", "")
    if lado and vaga.posicao in (Posicao.LAT, Posicao.PON):
        # a fonte diz o lado de origem: lateral direito na esquerda é improviso
        return 1.0 if lado == ("E" if vaga.lado == Lado.ESQUERDA else "D") else 0.92
    if jogador.pe_preferido in ("Ambos", "CONFIRMAR"):
        return 1.0
    pe_do_lado = "Esquerdo" if vaga.lado == Lado.ESQUERDA else "Direito"
    invertido = vaga.papel == Papel.PONTA_INVERTIDO or InstrucaoIndividual.CORTAR_PARA_DENTRO in vaga.instrucoes
    combina = (jogador.pe_preferido == pe_do_lado) != invertido
    if combina:
        return 1.0
    return 0.95 if vaga.posicao == Posicao.LAT else 0.98


def nota_para_vaga(jogador: Jogador, vaga: Vaga) -> float:
    """Quão bem o jogador cumpre aquela vaga (posição, papel e pé)."""
    perfil = PERFIS[vaga.papel]
    if vaga.papel in PAPEIS_DE_GOLEIRO:
        base = (0.8 * media_ponderada(jogador, PESOS_ESPECIAIS["goleiro_defesa"])
                + 0.2 * composto_fase(jogador, Fase.CONSTRUCAO, vaga.papel))
    else:
        soma = 0.0
        total = 0.0
        for fase, peso in perfil.presenca.items():
            soma += peso * composto_fase(jogador, fase, vaga.papel)
            total += peso
        base = soma / total if total else 0.0
        if perfil.peso_finalizacao > 0:
            fatia = min(0.5, perfil.peso_finalizacao)
            base = (1.0 - fatia) * base + fatia * media_ponderada(jogador, PESOS_ESPECIAIS["chute_pe"])
    return base * adequacao_posicao(jogador, vaga.posicao) * fator_do_pe(jogador, vaga)


def escalar_melhor_time(clube: Clube, tatica: Tatica, tamanho_banco: int = 7,
                        excluir: Optional[Set[int]] = None) -> Tatica:
    """Preenche a tática com os melhores titulares disponíveis, o banco e os cobradores.

    Usa escolha gulosa global: ordena todos os pares (vaga, jogador) pela nota
    e vai ocupando, o que evita gastar um craque numa vaga que não é a dele.
    """
    excluir = excluir or set()
    disponiveis = [j for j in clube.elenco if j.disponivel and j.id not in excluir]
    for vaga in tatica.vagas:
        vaga.jogador_id = None
    pares = []
    for indice, vaga in enumerate(tatica.vagas):
        for jogador in disponiveis:
            pares.append((nota_para_vaga(jogador, vaga) * fator_de_prontidao(jogador), indice, jogador))
    pares.sort(key=lambda item: item[0], reverse=True)
    vagas_ocupadas: Set[int] = set()
    usados: Set[int] = set()
    for _nota, indice, jogador in pares:
        if indice in vagas_ocupadas or jogador.id in usados:
            continue
        tatica.vagas[indice].jogador_id = jogador.id
        vagas_ocupadas.add(indice)
        usados.add(jogador.id)
        if len(vagas_ocupadas) == len(tatica.vagas):
            break
    _melhorar_por_trocas(tatica, disponiveis)
    usados = {v.jogador_id for v in tatica.vagas if v.jogador_id is not None}
    restantes = [j for j in disponiveis if j.id not in usados]
    tatica.banco_ids = montar_banco(restantes, tamanho_banco)
    titulares = [j for j in (clube.jogador(v.jogador_id) for v in tatica.vagas) if j is not None]
    if titulares:
        definir_capitao_e_cobradores(tatica, titulares)
    return tatica


def _melhorar_por_trocas(tatica: Tatica, disponiveis: List[Jogador]) -> None:
    """Busca local depois da escolha gulosa: troca pares de vagas e testa quem ficou de fora.

    Resolve casos como o do zagueiro que também joga de lateral: em vez de
    improvisar outro zagueiro na lateral, o versátil vai para a lateral.
    """
    por_id = {j.id: j for j in disponiveis}

    def nota(jogador_id, vaga) -> float:
        jogador = por_id.get(jogador_id)
        return nota_para_vaga(jogador, vaga) * fator_de_prontidao(jogador) if jogador else 0.0

    melhorou = True
    voltas = 0
    while melhorou and voltas < 20:
        melhorou = False
        voltas += 1
        vagas = tatica.vagas
        for i in range(len(vagas)):
            for k in range(i + 1, len(vagas)):
                a, b = vagas[i].jogador_id, vagas[k].jogador_id
                atual = nota(a, vagas[i]) + nota(b, vagas[k])
                trocado = nota(b, vagas[i]) + nota(a, vagas[k])
                if trocado > atual + 1e-6:
                    vagas[i].jogador_id, vagas[k].jogador_id = b, a
                    melhorou = True
        em_campo = {v.jogador_id for v in vagas}
        for vaga in vagas:
            for jogador in disponiveis:
                if jogador.id in em_campo:
                    continue
                if nota(jogador.id, vaga) > nota(vaga.jogador_id, vaga) + 1e-6:
                    em_campo.discard(vaga.jogador_id)
                    vaga.jogador_id = jogador.id
                    em_campo.add(jogador.id)
                    melhorou = True


def montar_banco(restantes: List[Jogador], tamanho: int) -> List[int]:
    """Banco com goleiro reserva e pelo menos um nome de cada setor."""
    ordenados = sorted(restantes, key=lambda j: nivel_geral(j) * fator_de_prontidao(j), reverse=True)
    banco: List[Jogador] = []
    ids: Set[int] = set()

    def incluir(jogador: Jogador) -> None:
        banco.append(jogador)
        ids.add(jogador.id)

    goleiros = [j for j in ordenados if j.posicao == Posicao.GOL]
    if goleiros and tamanho > 0:
        incluir(goleiros[0])
    for grupo in ((Posicao.ZAG, Posicao.LAT), (Posicao.VOL, Posicao.MEI), (Posicao.PON, Posicao.ATA)):
        if len(banco) >= tamanho:
            break
        for jogador in ordenados:
            if jogador.posicao in grupo and jogador.id not in ids:
                incluir(jogador)
                break
    for jogador in ordenados:
        if len(banco) >= tamanho:
            break
        if jogador.id not in ids and jogador.posicao != Posicao.GOL:
            incluir(jogador)
    return [j.id for j in banco]


def definir_capitao_e_cobradores(tatica: Tatica, titulares: List[Jogador]) -> None:
    bonus = {Hierarquia.LIDER: 4, Hierarquia.INFLUENTE: 2}
    capitao = max(titulares, key=lambda j: j.mentais.lideranca + bonus.get(j.hierarquia, 0))
    tatica.capitao_id = capitao.id
    linha = [j for j in titulares if j.posicao != Posicao.GOL] or titulares
    tatica.cobrador_penalti_id = max(linha, key=lambda j: media_ponderada(j, PESOS_ESPECIAIS["penalti"])).id
    tatica.cobrador_falta_id = max(linha, key=lambda j: media_ponderada(j, PESOS_ESPECIAIS["falta_direta"])).id
    tatica.cobrador_escanteio_id = max(
        linha, key=lambda j: media_ponderada(j, PESOS_ESPECIAIS["cobranca_escanteio"])).id

