def _sortear(rng: random.Random, media: float, desvio: float = 1.6) -> int:
    return int(limitar(round(rng.gauss(media, desvio)), 1, 20))


def _arredondar(valor: float, passo: float) -> float:
    return max(passo, round(valor / passo) * passo)


def estimar_valor_de_mercado(nivel: float, idade: int, potencial: int, reputacao: int) -> float:
    """Fórmula de TESTE para valor de mercado em reais (não é dado real)."""
    base = 150_000.0 * 1.65 ** (nivel - 5.0)
    if idade <= 21:
        fator_idade = 1.25 + max(0.0, potencial - nivel) * 0.12
    elif idade <= 24:
        fator_idade = 1.2
    elif idade <= 28:
        fator_idade = 1.0
    elif idade <= 31:
        fator_idade = 0.7
    elif idade <= 33:
        fator_idade = 0.45
    else:
        fator_idade = 0.3
    valor = base * fator_idade * (0.55 + reputacao / 100.0)
    return _arredondar(valor, 50_000.0 if valor >= 1_000_000 else 10_000.0)


def estimar_salario(nivel: float, idade: int, reputacao: int) -> float:
    """Fórmula de TESTE para salário mensal em reais (não é dado real)."""
    salario = 7_000.0 * 1.38 ** (nivel - 5.0) * (0.5 + reputacao / 100.0) * (1.1 if idade >= 28 else 0.9)
    return _arredondar(salario, 500.0)


class GeradorDeJogadores:
    """Cria jogadores fictícios coerentes com a posição, a idade e o nível."""

    def __init__(self, rng: random.Random, id_inicial: int = 1):
        self.rng = rng
        self._proximo_id = id_inicial

    def novo_id(self) -> int:
        valor = self._proximo_id
        self._proximo_id += 1
        return valor

    def _nome(self) -> str:
        return f"{self.rng.choice(PRIMEIROS_NOMES)} {self.rng.choice(SOBRENOMES)}"

    def jogador(self, posicao: Posicao, nivel: float, reputacao_clube: int, idade: Optional[int] = None,
                canhoto: Optional[bool] = None, jovem: bool = False) -> Jogador:
        rng = self.rng
        if idade is None:
            idade = rng.randint(18, 20) if jovem else int(round(rng.triangular(19, 35, 26)))
        chaves, secundarios = ATRIBUTOS_POR_POSICAO[posicao]

        def media_de(nome: str) -> float:
            if nome in chaves:
                return nivel + 1.0
            if nome in secundarios:
                return nivel - 1.0
            if nome in ATRIBUTOS_UNIVERSAIS:
                return nivel - 1.5
            return nivel - 4.0

        tecnicos = AtributosTecnicos(**{f.name: _sortear(rng, media_de(f.name)) for f in fields(AtributosTecnicos)})
        mentais = AtributosMentais(**{f.name: _sortear(rng, media_de(f.name)) for f in fields(AtributosMentais)})
        fisicos = AtributosFisicos(**{f.name: _sortear(rng, media_de(f.name)) for f in fields(AtributosFisicos)})
        if posicao == Posicao.GOL:
            goleiro = AtributosGoleiro(**{nome: _sortear(rng, media_de(nome)) for nome in ATRIBUTOS_DE_GOLEIRO})
        else:
            goleiro = AtributosGoleiro(**{nome: _sortear(rng, 2.5, 1.0) for nome in ATRIBUTOS_DE_GOLEIRO})
        # Idade: jovens ainda sem maturidade, veteranos perdendo arranque.
        if idade <= 20:
            for nome in ("decisao", "compostura", "posicionamento", "concentracao"):
                setattr(mentais, nome, int(limitar(getattr(mentais, nome) - 2, 1, 20)))
        if idade >= 31:
            perda = int(round((idade - 30) * 0.6))
            for nome in ("aceleracao", "velocidade", "resistencia"):
                setattr(fisicos, nome, int(limitar(getattr(fisicos, nome) - perda, 1, 20)))
        potencial_extra = rng.uniform(1.5, 5.0) if idade <= 21 else (rng.uniform(0.0, 1.5) if idade <= 26 else 0.0)
        ocultos = AtributosOcultos(
            consistencia=_sortear(rng, 7 + nivel * 0.35, 3.0),
            jogos_grandes=_sortear(rng, 10.5, 3.5),
            propensao_lesao=_sortear(rng, 8.0 + (idade - 26) * 0.15, 3.5),
            versatilidade=_sortear(rng, 10.0, 3.5),
            deslealdade=_sortear(rng, 10.0 if posicao in (Posicao.ZAG, Posicao.VOL) else 8.0, 3.5),
            potencial=int(limitar(round(nivel + potencial_extra), 1, 20)),
        )
        personalidade = Personalidade(**{f.name: _sortear(rng, 11.5, 3.5) for f in fields(Personalidade)})
        if canhoto is None:
            canhoto = rng.random() < 0.2
        pe = "Esquerdo" if canhoto else ("Ambos" if rng.random() < 0.05 else "Direito")
        secundarias = [p for p in POSICOES_VIZINHAS[posicao] if rng.random() < 0.3]
        altura = int(round(rng.gauss(ALTURA_MEDIA_POR_POSICAO[posicao], 5.0)))
        imc = rng.gauss(23.2, 1.1)
        peso = round(imc * (altura / 100.0) ** 2, 1)
        jogador = Jogador(
            id=self.novo_id(), nome=self._nome(), idade=idade, nacionalidade="Brasil", posicao=posicao,
            posicoes_secundarias=secundarias, pe_preferido=pe, altura_cm=altura, peso_kg=peso,
            tecnicos=tecnicos, mentais=mentais, fisicos=fisicos, goleiro=goleiro,
            ocultos=ocultos, personalidade=personalidade,
            moral=limitar(rng.gauss(65.0, 7.0), 40.0, 85.0),
        )
        nivel_real = nivel_geral(jogador)
        jogador.valor_mercado = estimar_valor_de_mercado(nivel_real, idade, ocultos.potencial, reputacao_clube)
        jogador.salario_mensal = estimar_salario(nivel_real, idade, reputacao_clube)
        return jogador

    def clube(self, clube_id: int, nome: str, sigla: str, nivel: float, reputacao: int,
              orcamento_transferencias: float, tecnico: Optional[Tecnico] = None,
              cidade: str = "", estadio: str = "") -> Clube:
        """Clube fictício com elenco de 24 jogadores e hierarquia montada."""
        rng = self.rng
        elenco: List[Jogador] = []
        for posicao, quantidade in COMPOSICAO_DO_ELENCO:
            for indice in range(quantidade):
                jovem = indice == quantidade - 1 and posicao != Posicao.GOL and rng.random() < 0.6
                if indice < 2:
                    nivel_jogador = nivel + rng.uniform(0.0, 1.0)
                elif jovem:
                    nivel_jogador = nivel - rng.uniform(1.5, 2.5)
                else:
                    nivel_jogador = nivel - rng.uniform(0.5, 1.8)
                canhoto = (indice % 2 == 1) if posicao in (Posicao.LAT, Posicao.PON) else None
                elenco.append(self.jogador(posicao, nivel_jogador, reputacao, canhoto=canhoto, jovem=jovem))
        definir_status_e_hierarquia(elenco)
        clube = Clube(
            id=clube_id, nome=nome, sigla=sigla, reputacao=reputacao,
            orcamento_transferencias=orcamento_transferencias, orcamento_salarial=0.0,
            elenco=elenco, tecnico=tecnico or Tecnico(), cidade=cidade, estadio=estadio,
        )
        clube.orcamento_salarial = _arredondar(clube.folha_salarial * 1.1, 10_000.0)
        return clube


# Vagas de um time titular típico, para saber quem tem lugar garantido.
VAGAS_TIPICAS_POR_POSICAO = {
    Posicao.GOL: 1, Posicao.ZAG: 2, Posicao.LAT: 2, Posicao.VOL: 2, Posicao.MEI: 1, Posicao.PON: 2, Posicao.ATA: 1,
}


def titulares_provaveis(elenco: Sequence[Jogador]) -> List[Jogador]:
    """Os onze que um técnico escalaria: os melhores de cada posição, depois as posições secundárias.

    Assim o segundo goleiro, por melhor que seja, não conta como titular prometido.
    """
    por_nivel = sorted(elenco, key=nivel_geral, reverse=True)
    vagas = dict(VAGAS_TIPICAS_POR_POSICAO)
    escolhidos: List[Jogador] = []
    for jogador in por_nivel:
        if vagas.get(jogador.posicao, 0) > 0:
            vagas[jogador.posicao] -= 1
            escolhidos.append(jogador)
    for jogador in por_nivel:
        if jogador in escolhidos:
            continue
        for posicao in jogador.posicoes_secundarias:
            if vagas.get(posicao, 0) > 0 and posicao != Posicao.GOL:
                vagas[posicao] -= 1
                escolhidos.append(jogador)
                break
    for jogador in por_nivel:
        if len(escolhidos) >= 11:
            break
        if jogador not in escolhidos and jogador.posicao != Posicao.GOL:
            escolhidos.append(jogador)
    return escolhidos[:11]


def definir_status_e_hierarquia(elenco: Sequence[Jogador]) -> None:
    """Promessas de tempo de jogo pelo lugar no time provável e liderança pelo peso no grupo."""
    titulares = sorted(titulares_provaveis(elenco), key=nivel_geral, reverse=True)
    demais = sorted((j for j in elenco if j not in titulares), key=nivel_geral, reverse=True)
    for posicao_no_ranking, jogador in enumerate(titulares):
        jogador.status = StatusElenco.JOGADOR_CHAVE if posicao_no_ranking < 3 else StatusElenco.TITULAR
    for posicao_no_ranking, jogador in enumerate(demais):
        jogador.status = StatusElenco.RODIZIO if posicao_no_ranking < 6 else StatusElenco.RESERVA
    for posicao_no_ranking, jogador in enumerate(titulares + demais):
        if jogador.idade <= 20 and jogador.ocultos.potencial >= nivel_geral(jogador) + 2 and posicao_no_ranking >= 3:
            jogador.status = StatusElenco.JOVEM_PROMESSA

    def influencia(j: Jogador) -> float:
        return j.mentais.lideranca * 0.5 + min(j.idade, 33) * 0.3 + nivel_geral(j) * 0.4 + j.mentais.determinacao * 0.2

    por_influencia = sorted(elenco, key=influencia, reverse=True)
    for indice, jogador in enumerate(por_influencia):
        if indice < 2:
            jogador.hierarquia = Hierarquia.LIDER
        elif indice < 5:
            jogador.hierarquia = Hierarquia.INFLUENTE
        elif jogador.idade <= 20:
            jogador.hierarquia = Hierarquia.NOVATO
        else:
            jogador.hierarquia = Hierarquia.REGULAR

