"""Gestão do clube do usuário: investimentos, departamento médico, peneiras da base, imprevistos e extrato.

Tudo aqui é regra do jogo (estimativa do Megafut). Os níveis vão de 1 a 10 e custam uma fração da receita
anual do clube, então um clube pequeno investe valores pequenos e um grande, valores grandes.
"""
from __future__ import annotations

import random
from datetime import date, timedelta
from typing import Any, Dict, List, Optional, Tuple

AREAS: Dict[str, Tuple[str, str]] = {
    "estrutura": ("Infraestrutura", "Estádio, CT, gramado e ônibus. Aumenta a receita de jogo e deixa os "
                                    "imprevistos mais raros e mais baratos."),
    "dm": ("Departamento médico", "Médicos, fisioterapia e fisiologia. Lesões duram menos."),
    "base": ("Categorias de base", "Estrutura para formar jovens. Peneiras trazem garotos melhores."),
    "olheiros": ("Olheiros", "Rede de observação. Peneiras com mais candidatos, potencial mais alto e "
                             "avaliação mais precisa do que cada garoto pode virar."),
}
PESO_DO_CUSTO = {"estrutura": 0.10, "dm": 0.05, "base": 0.06, "olheiros": 0.035}
MANUTENCAO = 0.000025  # por mês, sobre a receita anual, vezes o nível ao quadrado (cada nível custa mais que o anterior)
INTERVALO_DA_PENEIRA = 45  # dias
AVISO_A_CADA_JOGOS = 5

IMPREVISTOS = (  # texto, fração da receita anual (mínimo, máximo), só com infraestrutura até este nível
    ("O ônibus da delegação quebrou na estrada e precisou de conserto e de um fretado às pressas", 0.002, 0.006, 10),
    ("Um vazamento no vestiário do estádio exigiu reparo de emergência", 0.001, 0.004, 10),
    ("O gramado do CT precisou de replantio depois das chuvas", 0.002, 0.007, 8),
    ("Parte dos refletores do estádio queimou e teve de ser trocada", 0.002, 0.005, 9),
    ("Multa da federação por atraso na documentação do jogo", 0.0005, 0.002, 10),
    ("A conta de energia do CT veio muito acima do previsto", 0.001, 0.003, 10),
    ("Material esportivo furtado do almoxarifado precisou ser reposto", 0.001, 0.003, 7),
    ("A academia do CT teve aparelhos quebrados e foi preciso trocar", 0.002, 0.005, 8),
    ("Reforma emergencial em um setor da arquibancada exigida pelos bombeiros", 0.006, 0.015, 5),
    ("Pane no sistema de drenagem do estádio alagou parte do campo", 0.004, 0.01, 6),
)

LESOES = {
    "leve": ("pancada no tornozelo", "desconforto muscular na coxa", "entorse leve no tornozelo",
             "contratura na panturrilha", "pancada no joelho", "dores lombares"),
    "media": ("estiramento na coxa", "lesão muscular grau 1 na posterior da coxa", "entorse no joelho",
              "lesão no adutor", "lesão muscular na panturrilha", "contusão óssea no pé"),
    "grave": ("lesão muscular grau 2 na coxa", "entorse grave no tornozelo", "fratura no pé",
              "lesão no menisco", "lesão no ligamento do tornozelo", "fratura de costela"),
    "muito_grave": ("lesão no ligamento colateral do joelho", "fratura na perna", "lesão grau 3 na coxa",
                    "lesão no tendão de Aquiles", "ruptura do ligamento cruzado anterior"),
}


def nivel_inicial(reputacao: int) -> int:
    return int(max(1, min(9, 1 + reputacao // 11)))


def gravidade(dias: int) -> str:
    return "leve" if dias <= 7 else ("media" if dias <= 21 else ("grave" if dias <= 60 else "muito_grave"))


ROTULO_GRAVIDADE = {"leve": "leve", "media": "média", "grave": "grave", "muito_grave": "muito grave"}


class GestaoDoClube:
    def __init__(self, reputacao: int = 30) -> None:
        inicial = nivel_inicial(reputacao)
        self.niveis: Dict[str, int] = {a: inicial for a in AREAS}
        self.candidatos: List[Dict[str, Any]] = []
        self.ultima_peneira = 0
        self.jogos = 0
        self.lesoes: Dict[int, Dict[str, Any]] = {}
        self.extrato: List[List[Any]] = []  # [data, texto, valor (+ entrada, menos saída)]
        self.premios: List[List[Any]] = []  # [ano, competição, colocação, valor]

    # ------------------------------------------------------------------
    def para_dict(self) -> Dict[str, Any]:
        return {"niveis": self.niveis, "candidatos": self.candidatos, "ultima_peneira": self.ultima_peneira,
                "jogos": self.jogos, "lesoes": [[k, v] for k, v in self.lesoes.items()],
                "extrato": self.extrato[:120], "premios": self.premios[:80]}

    @classmethod
    def de_dict(cls, d: Optional[Dict[str, Any]], reputacao: int) -> "GestaoDoClube":
        g = cls(reputacao)
        if not d:
            return g
        g.niveis.update({k: int(v) for k, v in d.get("niveis", {}).items() if k in AREAS})
        g.candidatos = list(d.get("candidatos", []))
        g.ultima_peneira = int(d.get("ultima_peneira", 0))
        g.jogos = int(d.get("jogos", 0))
        g.lesoes = {int(k): v for k, v in d.get("lesoes", [])}
        g.extrato = list(d.get("extrato", []))
        g.premios = list(d.get("premios", []))
        return g

    # ------------------------------------------------------------------
    def lancar(self, dia: date, texto: str, valor: float) -> None:
        self.extrato.insert(0, [dia.strftime("%d/%m/%Y"), texto, round(valor, -2)])
        del self.extrato[150:]

    def custo_melhoria(self, area: str, receita: float) -> float:
        nivel = self.niveis[area]
        if nivel >= 10:
            return 0.0
        return float(max(20000.0, round(receita * PESO_DO_CUSTO[area] * (nivel + 1) / 10.0, -4)))

    def manutencao_da_area(self, area: str, receita: float, nivel: Optional[int] = None) -> float:
        n = self.niveis[area] if nivel is None else nivel
        return round(receita * MANUTENCAO * n * n, -2)

    def manutencao_mensal(self, receita: float) -> float:
        return round(sum(self.manutencao_da_area(a, receita) for a in AREAS), -2)

    def fator_de_receita(self) -> float:
        return 0.94 + 0.012 * self.niveis["estrutura"]

    def fator_de_recuperacao(self) -> float:
        """Nível 1: lesões 20% mais longas; nível 5: normal; nível 10: 25% mais curtas."""
        return 1.25 - 0.05 * self.niveis["dm"]

    def custo_da_peneira(self, receita: float) -> float:
        return float(max(15000.0, round(receita * 0.003 * (1 + self.niveis["olheiros"] / 5.0), -3)))

    # ------------------------------------------------------------------
    def diagnostico(self, dias: int, rng: random.Random) -> Tuple[str, str]:
        g = gravidade(dias)
        opcoes = LESOES[g]
        if g == "muito_grave" and dias < 120:
            opcoes = opcoes[:-1]  # cruzado só nas mais longas
        return rng.choice(opcoes), ROTULO_GRAVIDADE[g]

    def imprevisto_do_dia(self, hoje: date, receita: float, rng: random.Random) -> Optional[Tuple[str, float]]:
        """Em média dois ou três por temporada; com infraestrutura alta, mais raro e mais barato."""
        nivel = self.niveis["estrutura"]
        chance = (1.0 / 160.0) * (1.3 - 0.08 * nivel)
        if rng.random() >= chance:
            return None
        possiveis = [i for i in IMPREVISTOS if nivel <= i[3]]
        texto, minimo, maximo, _ = rng.choice(possiveis)
        custo = receita * rng.uniform(minimo, maximo) * (1.15 - 0.05 * nivel)
        return texto, float(max(3000.0, round(custo, -3)))

    def peneira(self, hoje: date, pais: str, nivel_do_clube: float, rng: random.Random,
                nome_do_pais: Any) -> List[Dict[str, Any]]:
        olheiros, base = self.niveis["olheiros"], self.niveis["base"]
        quantidade = 3 + olheiros // 3
        candidatos = []
        vizinhos = {"Brasil": ["Argentina", "Uruguai", "Paraguai", "Colômbia"],
                    "Argentina": ["Uruguai", "Paraguai", "Chile"], "México": ["Estados Unidos", "Colômbia"]}
        posicoes = ["GOL", "ZAG", "ZAG", "LAT", "LAT", "VOL", "MEI", "PON", "PON", "ATA", "ATA"]
        for _ in range(quantidade):
            origem = pais
            if olheiros >= 6 and rng.random() < 0.04 * (olheiros - 5):
                origem = rng.choice(vizinhos.get(pais, [pais]))
            nivel = nivel_do_clube - 2.6 + 0.15 * base + rng.gauss(0.0, 0.6)
            pot = nivel + 1.0 + 0.18 * olheiros + 0.1 * base + rng.uniform(0.0, 2.2)
            margem = max(0.4, 2.4 - 0.2 * olheiros)  # olheiro melhor erra menos o potencial
            chute = pot + rng.uniform(-margem, margem) / 2
            candidatos.append({
                "nome": nome_do_pais(origem, rng), "pais": origem, "pos": rng.choice(posicoes),
                "idade": rng.randint(15, 18), "nivel": round(nivel, 2), "pot": round(pot, 2),
                "pot_min": round(chute - margem, 2), "pot_max": round(chute + margem, 2),
                "salario": 0.0,
            })
        self.candidatos = candidatos
        self.ultima_peneira = hoje.toordinal()
        return candidatos

    def peneira_liberada(self, hoje: date) -> Optional[date]:
        """None se pode fazer hoje; senão, a data em que libera."""
        if not self.ultima_peneira:
            return None
        libera = date.fromordinal(self.ultima_peneira) + timedelta(days=INTERVALO_DA_PENEIRA)
        return None if hoje >= libera else libera

arquivos.megafut/ia_tecnico.py:
"""Técnico controlado pela IA: lê a partida e muda a postura no meio do jogo.

A cada checagem (15, 30, intervalo, 60, 70, 80 e 86 minutos) o técnico:
1. Reage ao placar conforme o perfil (ousado, equilibrado ou cauteloso).
2. Tenta perceber padrões do adversário. A chance de perceber depende da
   leitura de jogo dele (1 a 20), o que torna as reações imprevisíveis.
3. Faz substituições por cansaço, rendimento ou necessidade tática.

O técnico conversa com o motor por estes métodos: registrar_tatica,
pode_substituir, substituir e nota_parcial.
"""
from __future__ import annotations

import random
from dataclasses import dataclass, field
from typing import Callable, Dict, List, Optional, Set, Tuple

from .avaliacao import nivel_geral
from .entidades import Jogador, Tecnico
from .enums import (
    AlturaLinha, AoPerder, AoRecuperar, EstiloPasse, InstrucaoIndividual, IntensidadePressao,
    Lado, Largura, Mentalidade, Papel, PerfilTecnico, Posicao, Ritmo, Setor, lado_espelho,
)
from .escalacao import fator_de_prontidao, nota_para_vaga
from .tatica import PAPEL_PADRAO_POSICAO, Vaga
from .util import icone


@dataclass
class Fotografia:
    """Recorte das estatísticas no momento da última checagem."""

    perdas_defesa: int = 0
    entradas_adversario: Dict[Lado, int] = field(default_factory=dict)
    finalizacoes: int = 0
    xg: float = 0.0
    posse: float = 0.0
    posse_adversario: float = 0.0
    contragolpes_adversario: int = 0

    @classmethod
    def de(cls, time) -> "Fotografia":
        st = time.stats
        adv = time.adversario.stats
        return cls(
            perdas_defesa=st.perdas_por_setor[Setor.DEFESA],
            entradas_adversario=dict(adv.entradas_ataque),
            finalizacoes=st.finalizacoes,
            xg=st.xg,
            posse=st.posse_segundos,
            posse_adversario=adv.posse_segundos,
            contragolpes_adversario=adv.finalizacoes_contragolpe,
        )


REACAO_AO_PLACAR = {PerfilTecnico.OUSADO: 55, PerfilTecnico.EQUILIBRADO: 60, PerfilTecnico.CAUTELOSO: 66}
SEGURAR_PLACAR = {PerfilTecnico.OUSADO: 80, PerfilTecnico.EQUILIBRADO: 74, PerfilTecnico.CAUTELOSO: 66}


class TecnicoIA:
    def __init__(self, tecnico: Tecnico, rng: random.Random):
        self.tecnico = tecnico
        self.rng = rng
        self.feitos: Set[str] = set()
        self.foto = Fotografia()
        self._abriu_janela = False

    @property
    def nome(self) -> str:
        return self.tecnico.nome

    def percebe(self) -> bool:
        """Chance de enxergar um padrão: de 38% (leitura 1) a 95% (leitura 20)."""
        chance = 0.35 + self.tecnico.leitura_de_jogo / 20.0 * 0.6
        return self.rng.random() < chance

    # ==================================================================
    # Ponto de entrada
    # ==================================================================
    def avaliar(self, motor, time, minuto: int, intervalo: bool = False) -> None:
        if self.tecnico.controlado_pelo_usuario:
            self.foto = Fotografia.de(time)
            return
        self._abriu_janela = False
        mudou = self._ajuste_por_placar(motor, time, minuto)
        if not mudou and self.percebe():
            self._ler_padroes(motor, time)
        if intervalo or minuto >= 55:
            self._substituicoes(motor, time, minuto, intervalo)
        if self._abriu_janela and not intervalo:
            time.janelas += 1
        self.foto = Fotografia.de(time)

    def _mudar(self, motor, time, chave: str, texto: str, acao: Callable[[], None]) -> bool:
        if chave in self.feitos:
            return False
        acao()
        self.feitos.add(chave)
        motor.registrar_tatica(time, f"{icone('tatica')} {self.nome} ({time.sigla}): {texto}")
        return True

    # ==================================================================
    # 1. Placar
    # ==================================================================
    def _ajuste_por_placar(self, motor, time, minuto: int) -> bool:
        if minuto < 45:
            return False
        saldo = time.stats.gols - time.adversario.stats.gols
        t = time.tatica
        perfil = self.tecnico.perfil
        favorito = time.clube.reputacao >= time.adversario.clube.reputacao + 15

        if saldo < 0 and minuto >= 78:
            def tudo() -> None:
                t.mentalidade = Mentalidade.MUITO_OFENSIVA
                t.altura_linha = AlturaLinha.ALTA
                t.pressao = IntensidadePressao.ALTA
                t.ritmo = Ritmo.RAPIDO
            if self._mudar(motor, time, "pressao_total", "pressão total, todo mundo para o ataque", tudo):
                self._troca_ofensiva(motor, time)
                return True

        if saldo < 0 and minuto >= REACAO_AO_PLACAR[perfil]:
            passos = 2 if saldo <= -2 else 1

            def subir() -> None:
                t.mentalidade = t.mentalidade.deslocar(passos)
                t.ritmo = Ritmo.RAPIDO
            if self._mudar(motor, time, "reagir", "precisa do gol: sobe a mentalidade e acelera o jogo", subir):
                self._troca_ofensiva(motor, time)
                return True

        if saldo == 0 and favorito and minuto >= REACAO_AO_PLACAR[perfil] + 8:
            def buscar() -> None:
                t.mentalidade = t.mentalidade.deslocar(1)
            if self._mudar(motor, time, "buscar_vitoria", "o empate não serve: manda o time para cima", buscar):
                return True

        if saldo == 1 and minuto >= SEGURAR_PLACAR[perfil]:
            def segurar() -> None:
                t.mentalidade = t.mentalidade.deslocar(-1)
                t.ritmo = Ritmo.LENTO
            if self._mudar(motor, time, "segurar", "administra a vantagem: recua um pouco e esfria o jogo", segurar):
                self._troca_defensiva(motor, time)
                return True

        if saldo >= 2 and minuto >= 70:
            def poupar() -> None:
                t.pressao = t.pressao.deslocar(-1)
                t.ritmo = Ritmo.LENTO
            if self._mudar(motor, time, "poupar", "jogo controlado: alivia a pressão para poupar energia", poupar):
                return True
        return False

    # ==================================================================
    # 2. Leitura de padrões do adversário
    # ==================================================================
    def _ler_padroes(self, motor, time) -> bool:
        st = time.stats
        adv = time.adversario
        t = time.tatica
        foto = self.foto

        # Pressão alta adversária roubando bolas na nossa saída.
        perdas = st.perdas_por_setor[Setor.DEFESA] - foto.perdas_defesa
        if perdas >= 4 and t.estilo_passe != EstiloPasse.DIRETO:
            def ligar() -> None:
                t.estilo_passe = EstiloPasse.DIRETO
            if self._mudar(motor, time, "fugir_pressao",
                           "percebe a pressão alta e manda ligar direto, pulando o meio", ligar):
                return True

        # Corredor mais atacado pelo adversário.
        entradas = {lado: adv.stats.entradas_ataque[lado] - foto.entradas_adversario.get(lado, 0) for lado in Lado}
        total = sum(entradas.values())
        if total >= 6:
            lado_atacado, quantidade = max(entradas.items(), key=lambda item: item[1])
            if lado_atacado != Lado.CENTRO and quantidade / total >= 0.5:
                nosso_lado = lado_espelho(lado_atacado)
                if self._mudar(motor, time, f"fechar_{nosso_lado.name}",
                               f"fecha o lado {nosso_lado.lado_masculino}: o lateral passa a segurar posição",
                               lambda: self._fechar_lado(time, nosso_lado)):
                    return True

        # Contragolpes do adversário machucando.
        contragolpes = adv.stats.finalizacoes_contragolpe - foto.contragolpes_adversario
        if contragolpes >= 2:
            if t.ao_perder == AoPerder.CONTRAPRESSAO:
                def recompor() -> None:
                    t.ao_perder = AoPerder.RECOMPOR
                if self._mudar(motor, time, "recompor",
                               "sofre nos contragolpes e manda o time recompor ao perder a bola", recompor):
                    return True
            if t.altura_linha == AlturaLinha.ALTA:
                def baixar() -> None:
                    t.altura_linha = AlturaLinha.MEDIA
                if self._mudar(motor, time, "baixar_linha", "baixa a linha para não dar espaço nas costas", baixar):
                    return True

        # Muitas finalizações ruins: o adversário está fechado.
        chutes = st.finalizacoes - foto.finalizacoes
        xg = st.xg - foto.xg
        if chutes >= 4 and xg / chutes < 0.07:
            if t.largura != Largura.LARGA:
                def abrir() -> None:
                    t.largura = Largura.LARGA
                if self._mudar(motor, time, "abrir_campo",
                               "o time só chuta de longe: abre o campo para buscar cruzamentos", abrir):
                    return True
            else:
                def por_dentro() -> None:
                    t.largura = Largura.ESTREITA
                if self._mudar(motor, time, "por_dentro", "troca os cruzamentos por tabelas por dentro", por_dentro):
                    return True

        # Dominado na posse: abre mão da bola e sai no contragolpe.
        posse = st.posse_segundos - foto.posse
        posse_adv = adv.stats.posse_segundos - foto.posse_adversario
        if posse + posse_adv > 0 and posse_adv / (posse + posse_adv) >= 0.64 and t.ao_recuperar != AoRecuperar.CONTRAGOLPE:
            def recuar() -> None:
                t.altura_linha = AlturaLinha.BAIXA
                t.ao_recuperar = AoRecuperar.CONTRAGOLPE
            if self._mudar(motor, time, "contragolpe",
                           "abre mão da bola: bloco baixo e saída rápida no contragolpe", recuar):
                return True
        return False

    def _fechar_lado(self, time, lado: Lado) -> None:
        for jc in time.em_campo:
            if jc.vaga.posicao == Posicao.LAT and jc.vaga.lado == lado:
                jc.vaga.instrucoes.add(InstrucaoIndividual.SEGURAR_POSICAO)
        time.reforco_corredor[lado] = time.reforco_corredor.get(lado, 0.0) + 0.6

    # ==================================================================
    # 3. Substituições
    # ==================================================================
    def melhor_reserva(self, time, vaga: Vaga, excluidos: Optional[Set[int]] = None) -> Optional[Jogador]:
        melhor = None
        melhor_nota = -1.0
        for jogador in time.banco:
            if excluidos and jogador.id in excluidos:
                continue
            if (jogador.posicao == Posicao.GOL) != (vaga.posicao == Posicao.GOL):
                continue
            nota = nota_para_vaga(jogador, vaga) * fator_de_prontidao(jogador)
            if nota > melhor_nota:
                melhor, melhor_nota = jogador, nota
        return melhor

    def _substituicoes(self, motor, time, minuto: int, intervalo: bool) -> None:
        if not motor.pode_substituir(time, intervalo):
            return
        if minuto < 70:
            limite_condicao = 77.0
        elif minuto < 80:
            limite_condicao = 81.0
        else:
            limite_condicao = 86.0
        restantes = motor.p.max_substituicoes - time.substituicoes
        trocas: List[Tuple[object, Jogador, str]] = []
        reservados: Set[int] = set()
        candidatos = sorted((jc for jc in time.em_campo if not jc.eh_goleiro), key=lambda jc: jc.condicao)
        for jc in candidatos:
            if len(trocas) >= min(3, restantes):
                break
            nota = motor.nota_parcial(jc)
            cansado = jc.condicao < limite_condicao
            mal = nota < (5.6 if intervalo else 5.8) and (intervalo or minuto >= 60)
            pendurado = intervalo and jc.stats.amarelos >= 1 and jc.jogador.mentais.agressividade >= 15
            if not (cansado or mal or pendurado):
                continue
            reserva = self.melhor_reserva(time, jc.vaga, reservados)
            if reserva is None:
                continue
            atual = nota_para_vaga(jc.jogador, jc.vaga) - jc.penalidade_fadiga()
            novo = nota_para_vaga(reserva, jc.vaga) * fator_de_prontidao(reserva)
            tolerancia = 1.2 if (cansado and minuto >= 70) else 0.6
            if novo < atual - tolerancia and not mal:
                continue
            reservados.add(reserva.id)
            motivo = "pendurado com amarelo" if pendurado else ("cansado" if cansado else "abaixo no jogo")
            trocas.append((jc, reserva, motivo))
        for jc, reserva, motivo in trocas:
            if motor.pode_substituir(time, intervalo):
                motor.substituir(time, jc, reserva, motivo)
                self._abriu_janela = True

    def _troca_ofensiva(self, motor, time) -> None:
        if not motor.pode_substituir(time):
            return
        zagueiros = [jc for jc in time.em_campo if jc.vaga.posicao == Posicao.ZAG]
        defensivos = [
            jc for jc in time.em_campo
            if jc.vaga.papel in (Papel.TRINCO, Papel.LATERAL_DEFENSIVO, Papel.ZAGUEIRO)
            and not (jc.vaga.posicao == Posicao.ZAG and len(zagueiros) <= 2)
        ]
        atacantes = [j for j in time.banco if j.posicao in (Posicao.ATA, Posicao.PON, Posicao.MEI)]
        if not defensivos or not atacantes:
            return
        sai = min(defensivos, key=motor.nota_parcial)
        entra = max(atacantes, key=lambda j: nivel_geral(j) * fator_de_prontidao(j))
        if entra.posicao in (Posicao.ATA, Posicao.MEI):
            lado = Lado.CENTRO
        else:
            lado = sai.vaga.lado if sai.vaga.lado != Lado.CENTRO else Lado.DIREITA
        nova = Vaga(entra.posicao, lado, PAPEL_PADRAO_POSICAO[entra.posicao])
        motor.substituir(time, sai, entra, "mudança ofensiva", nova_vaga=nova)
        self._abriu_janela = True

    def _troca_defensiva(self, motor, time) -> None:
        if not motor.pode_substituir(time):
            return
        ofensivos = [jc for jc in time.em_campo if jc.vaga.posicao in (Posicao.ATA, Posicao.PON, Posicao.MEI)]
        defensores = [j for j in time.banco if j.posicao in (Posicao.VOL, Posicao.ZAG)]
        if len(ofensivos) <= 1 or not defensores:
            return
        sai = min(ofensivos, key=lambda jc: jc.condicao)
        entra = max(defensores, key=lambda j: nivel_geral(j) * fator_de_prontidao(j))
        if entra.posicao == Posicao.VOL:
            nova = Vaga(Posicao.VOL, Lado.CENTRO, Papel.TRINCO)
        else:
            nova = Vaga(Posicao.ZAG, Lado.CENTRO, Papel.ZAGUEIRO)
        motor.substituir(time, sai, entra, "fechar o time", nova_vaga=nova)
        self._abriu_janela = True

    # ==================================================================
    # Reações a expulsões
    # ==================================================================
    def reagir_expulsao(self, motor, time, propria: bool) -> None:
        if self.tecnico.controlado_pelo_usuario:
            return
        t = time.tatica
        if propria:
            def fechar() -> None:
                t.mentalidade = t.mentalidade.deslocar(-1)
                t.altura_linha = t.altura_linha.deslocar(-1)
            self._mudar(motor, time, "recompor_expulsao", "com um a menos, recua o bloco e fecha os espaços", fechar)
        else:
            saldo = time.stats.gols - time.adversario.stats.gols
            if saldo <= 0:
                def empurrar() -> None:
                    t.mentalidade = t.mentalidade.deslocar(1)
                self._mudar(motor, time, "aproveitar_expulsao",
                            "com um a mais, empurra o adversário para trás", empurrar)

arquivos.megafut/mercado.py:
"""Mercado de transferências: contratos, as sete modalidades de negócio e o mercado dos outros clubes.

Modalidades:
1. Definitiva: taxa para o clube dono dos direitos e contrato novo com o jogador.
2. Agente livre: sem taxa; o custo é salário, luvas e comissão do empresário.
3. Pré contrato: jogador com 6 meses ou menos de vínculo assina direto; chega de graça no fim do contrato.
4. Empréstimo: seco (volta no fim), com opção de compra (valor fixado) ou com obrigação de compra
   (dispara se o jogador atuar na meta de jogos). O destino paga a parte combinada do salário.
5. Multa rescisória: quem deposita a multa leva sem o clube poder recusar; só falta o jogador aceitar.
6. Troca: jogadores dos dois lados, com compensação em dinheiro quando os valores diferem.
7. Venda com recompra: o vendedor guarda o direito de comprar de volta por valor e prazo fixados.

Valores, salários, multas e prazos de contrato dos jogadores reais não estão nos dados: o jogo usa
estimativas próprias (marcadas na interface) e o real fica CONFIRMAR.

Cada negócio passa por duas etapas: o clube (pedida que sobe com a importância do jogador, contrato
longo, rivalidade e reputação do comprador, e cai com contrato acabando e caixa apertado) e o jogador
(pedida de salário que sobe ao descer de patamar, ao ir para rival e sem garantia de titularidade).
Cada etapa aceita, recusa ou faz contraproposta. O humor do dia entra como pequena sorte, fixa pela semente.
"""
from __future__ import annotations

import random
import zlib
from dataclasses import dataclass, field
from datetime import date, timedelta
from typing import Any, Callable, Dict, List, Optional, Sequence, Tuple

from .avaliacao import nivel_geral
from .classicos import buscar_classico
from .entidades import Clube, Jogador
from .enums import Posicao, StatusElenco
from .gerador import definir_status_e_hierarquia, estimar_salario, estimar_valor_de_mercado

TIPOS = ("definitiva", "livre", "pre_contrato", "emprestimo", "multa", "troca")
TIPOS_DE_EMPRESTIMO = ("seco", "opcao", "obrigacao")
PAPEIS = ("Titular", "Rodízio", "Reserva")
LIMITE_DO_ELENCO = 40


def meses_entre(inicio: date, fim: date) -> int:
    return (fim.year - inicio.year) * 12 + (fim.month - inicio.month) - (1 if fim.day < inicio.day else 0)


def _sorte(*partes: Any) -> float:
    """Número entre 0 e 1 fixo para a combinação (mesma proposta, mesmo dia, mesmo resultado)."""
    return (zlib.crc32("|".join(str(p) for p in partes).encode("utf8")) % 10_000) / 10_000.0


@dataclass
class Contrato:
    jogador_id: int
    dono_id: int  # clube dono dos direitos (0: sem clube)
    salario_mensal: float
    fim: date
    multa: float
    estimado: bool = True
    recompra_clube_id: int = 0
    recompra_valor: float = 0.0
    recompra_ate: Optional[date] = None
    pre_contrato_clube_id: int = 0
    pre_contrato_salario: float = 0.0
    pre_contrato_anos: int = 0


@dataclass
class Emprestimo:
    jogador_id: int
    origem_id: int
    destino_id: int
    inicio: date
    fim: date
    tipo: str  # seco, opcao, obrigacao
    valor_compra: float = 0.0
    meta_percentual: float = 0.5
    salario_destino_pct: float = 1.0
    jogos_do_jogador_no_inicio: int = 0
    jogos_do_destino_no_inicio: int = 0


@dataclass
class Proposta:
    id: int
    tipo: str
    jogador_id: int
    comprador_id: int
    vendedor_id: int
    data: date
    valor: float = 0.0
    trocas: List[int] = field(default_factory=list)
    emprestimo_tipo: str = "seco"
    emprestimo_meses: int = 6
    emprestimo_valor_compra: float = 0.0
    emprestimo_salario_pct: float = 1.0
    recompra_valor: float = 0.0
    recompra_anos: int = 2
    salario: float = 0.0
    luvas: float = 0.0
    comissao: float = 0.0
    anos: int = 3
    papel: str = "Rodízio"
    etapa: str = "clube"  # clube, jogador, concluida, recusada, expirada, aguardando_usuario
    historico: List[str] = field(default_factory=list)
    pedida_clube: float = 0.0
    pedida_salario: float = 0.0
    compensacao: float = 0.0  # pago pelo vendedor ao comprador numa troca desequilibrada
    expira: Optional[date] = None
    do_usuario: bool = False  # proposta feita pelo usuário (True) ou recebida por ele


@dataclass
class Resposta:
    decisao: str  # aceita, recusa, contraproposta
    motivo: str
    valor: float = 0.0  # pedida quando é contraproposta


# ============================================================================
# Valores de jogo (estimativas)
# ============================================================================

def valor_de_jogo(jogador: Jogador, clube: Optional[Clube]) -> float:
    reputacao = clube.reputacao if clube is not None else 40
    return estimar_valor_de_mercado(nivel_geral(jogador), jogador.idade, jogador.ocultos.potencial, reputacao)


def salario_de_jogo(jogador: Jogador, clube: Optional[Clube]) -> float:
    reputacao = clube.reputacao if clube is not None else 40
    return estimar_salario(nivel_geral(jogador), jogador.idade, reputacao)


def arredondar_dinheiro(valor: float) -> float:
    if valor >= 10_000_000:
        return round(valor / 500_000) * 500_000
    if valor >= 1_000_000:
        return round(valor / 100_000) * 100_000
    if valor >= 100_000:
        return round(valor / 10_000) * 10_000
    return round(valor / 500) * 500


def contrato_inicial(jogador: Jogador, clube: Clube, ano: int) -> Contrato:
    """Contrato estimado para quem não tem dados de contrato (real: CONFIRMAR)."""
    anos = (0, 1, 1, 2, 2, 3, 3, 4)[zlib.crc32(("contrato" + jogador.nome).encode("utf8")) % 8]
    if jogador.idade >= 33:
        anos = min(anos, 1)
    salario = salario_de_jogo(jogador, clube)
    valor = valor_de_jogo(jogador, clube)
    return Contrato(jogador.id, clube.id, salario, date(ano + anos, 12, 31), arredondar_dinheiro(valor * 3.0))


# ============================================================================
# Avaliação pelo clube dono dos direitos
# ============================================================================

_IMPORTANCIA = {StatusElenco.JOGADOR_CHAVE: 1.7, StatusElenco.TITULAR: 1.35, StatusElenco.JOVEM_PROMESSA: 1.5,
                StatusElenco.RODIZIO: 1.05, StatusElenco.RESERVA: 0.85}


def _entre_os_dois_melhores(jogador: Jogador, clube: Clube) -> bool:
    mesma = sorted((j for j in clube.elenco if j.posicao == jogador.posicao), key=nivel_geral, reverse=True)
    return jogador in mesma[:2]


# Jogadores que os clubes da IA colocaram na lista: id -> ("venda", desconto) ou ("emprestimo", 1.0).
# Preenchido pelo MercadoMundo; aqui só é lido.
LISTA_DOS_CLUBES: Dict[int, Tuple[str, float]] = {}


def pedida_do_clube(jogador: Jogador, vendedor: Clube, comprador: Clube, contrato: Contrato, hoje: date,
                    semente: int, sorte: Optional[float] = None) -> float:
    """Valor que o clube pede. sorte=1.0 dá o pior caso (o teto da variação do dia), usado na sugestão."""
    pedida = valor_de_jogo(jogador, vendedor) * _IMPORTANCIA.get(jogador.status, 1.0)
    if _entre_os_dois_melhores(jogador, vendedor):
        pedida *= 1.1
    restantes = meses_entre(hoje, contrato.fim)
    if restantes <= 6:
        pedida *= 0.55
    elif restantes <= 12:
        pedida *= 0.8
    elif restantes >= 36:
        pedida *= 1.1
    if buscar_classico(vendedor.nome, comprador.nome, vendedor.pais, comprador.pais):
        pedida *= 1.35
    if comprador.reputacao < vendedor.reputacao - 10:
        pedida *= 1.05
    elif comprador.reputacao > vendedor.reputacao + 15:
        pedida *= 0.97
    if vendedor.orcamento_transferencias < 0:
        pedida *= 0.9
    fator = _sorte(semente, "clube", jogador.id, comprador.id, hoje.isoformat()) if sorte is None else sorte
    pedida *= 0.92 + 0.16 * fator
    lista = LISTA_DOS_CLUBES.get(jogador.id)
    if lista and lista[0] == "venda":
        pedida *= lista[1]  # na lista de transferência: o clube quer vender e aceita menos
    return arredondar_dinheiro(pedida)


def _valor_na_troca(jogador: Jogador, dono: Clube, recebedor: Clube) -> float:
    interesse = 0.9 if len([j for j in recebedor.elenco if j.posicao == jogador.posicao]) < 3 else 0.6
    if jogador.idade > 30:
        interesse *= 0.8
    return valor_de_jogo(jogador, dono) * interesse


def avaliar_pelo_clube(proposta: Proposta, jogador: Jogador, vendedor: Clube, comprador: Clube,
                       contrato: Contrato, trocas: Sequence[Jogador], hoje: date, semente: int) -> Resposta:
    """Decisão do clube dono dos direitos (ou do clube de origem, no empréstimo)."""
    if proposta.tipo == "multa":
        if proposta.valor + 0.5 < contrato.multa:
            return Resposta("recusa", f"O depósito precisa ser a multa inteira: R$ {contrato.multa:,.0f}".replace(",", "."))
        return Resposta("aceita", "Multa rescisória depositada: o clube não pode recusar")
    pedida = pedida_do_clube(jogador, vendedor, comprador, contrato, hoje, semente)
    proposta.pedida_clube = pedida
    rival = buscar_classico(vendedor.nome, comprador.nome, vendedor.pais, comprador.pais) is not None
    if proposta.tipo == "emprestimo":
        lista = LISTA_DOS_CLUBES.get(jogador.id)
        if lista and lista[0] == "emprestimo" and not rival:
            if proposta.emprestimo_salario_pct < 1.0 and proposta.emprestimo_tipo == "seco":
                return Resposta("contraproposta", "Está na lista de empréstimo: libera sem custo se você pagar o "
                                "salário inteiro", 0.0)
            return Resposta("aceita", "Empréstimo aceito: o clube só queria tirar o salário da folha")
        if jogador.status in (StatusElenco.JOGADOR_CHAVE,) or (
                jogador.status == StatusElenco.TITULAR and proposta.valor < 0.35 * pedida):
            return Resposta("recusa", "É peça importante do elenco e não sai emprestado")
        if rival:
            return Resposta("recusa", "Não empresta para o rival")
        if proposta.emprestimo_salario_pct < 0.7:
            return Resposta("contraproposta", "Quer que o destino pague pelo menos 70% do salário", 0.0)
        if proposta.emprestimo_tipo == "opcao" and proposta.emprestimo_valor_compra < pedida:
            return Resposta("contraproposta", "Aceita com opção de compra, mas pelo valor pedido", pedida)
        if proposta.emprestimo_tipo == "obrigacao" and proposta.emprestimo_valor_compra < 0.9 * pedida:
            return Resposta("contraproposta", "Aceita com obrigação de compra, mas por mais", arredondar_dinheiro(0.9 * pedida))
        return Resposta("aceita", "Empréstimo aceito")
    oferta = proposta.valor + sum(_valor_na_troca(t, comprador, vendedor) for t in trocas)
    if rival and oferta < 1.2 * pedida:
        return Resposta("recusa", "Para o rival, só com uma proposta muito acima")
    if oferta >= pedida:
        if trocas and oferta > 1.15 * pedida:
            proposta.compensacao = arredondar_dinheiro((oferta - pedida) / 2)
            return Resposta("aceita", "Aceita a troca e paga compensação pela diferença")
        return Resposta("aceita", "Proposta aceita")
    if oferta >= 0.75 * pedida:
        return Resposta("contraproposta", "Quer mais pela liberação", pedida)
    return Resposta("recusa", "Proposta muito abaixo do que o clube pede (cerca de "
                    + f"R$ {pedida:,.0f}".replace(",", ".") + ")")


# ============================================================================
# Avaliação pelo jogador (termos pessoais)
# ============================================================================

def _seria_titular(jogador: Jogador, destino: Clube) -> bool:
    mesma = sorted((j for j in destino.elenco if j.posicao == jogador.posicao and j.id != jogador.id),
                   key=nivel_geral, reverse=True)
    vagas = {Posicao.GOL: 1, Posicao.ZAG: 2, Posicao.LAT: 2, Posicao.VOL: 2, Posicao.MEI: 1, Posicao.PON: 2,
             Posicao.ATA: 1}[jogador.posicao]
    return len(mesma) < vagas or nivel_geral(jogador) >= nivel_geral(mesma[vagas - 1]) - 0.3


def pedida_do_jogador(jogador: Jogador, origem: Optional[Clube], destino: Clube, contrato: Optional[Contrato],
                      papel: str, anos: int, hoje: date, semente: int, sorte: Optional[float] = None) -> float:
    atual = contrato.salario_mensal if contrato else salario_de_jogo(jogador, origem)
    pedida = max(atual * 1.12, salario_de_jogo(jogador, destino) * 0.9)
    reputacao_origem = origem.reputacao if origem is not None else 45
    diferenca = destino.reputacao - reputacao_origem
    if diferenca < 0:
        pedida *= 1 + 0.025 * min(30, -diferenca)
    else:
        pedida *= max(0.85, 1 - 0.01 * diferenca)
    if origem is not None and buscar_classico(origem.nome, destino.nome, origem.pais, destino.pais):
        pedida *= 1.25
    if papel == "Titular":
        pedida *= 0.95 if _seria_titular(jogador, destino) else 1.05
    elif papel == "Reserva":
        pedida *= 1.2
    else:
        pedida *= 1.05
    if jogador.idade >= 31 and anos < 2:
        pedida *= 1.1
    fator = _sorte(semente, "jogador", jogador.id, destino.id, hoje.isoformat()) if sorte is None else sorte
    pedida *= 0.95 + 0.13 * fator
    return arredondar_dinheiro(pedida)


def avaliar_pelo_jogador(proposta: Proposta, jogador: Jogador, origem: Optional[Clube], destino: Clube,
                         contrato: Optional[Contrato], hoje: date, semente: int) -> Resposta:
    if proposta.tipo == "emprestimo":
        if destino.reputacao < (origem.reputacao if origem else 0) - 35 and jogador.status != StatusElenco.RESERVA:
            return Resposta("recusa", "Não quer cair tanto de patamar num empréstimo")
        return Resposta("aceita", "Topa o empréstimo")
    anos = max(1, min(5, proposta.anos))
    pedida = pedida_do_jogador(jogador, origem, destino, contrato, proposta.papel, anos, hoje, semente)
    proposta.pedida_salario = pedida
    if origem is not None and buscar_classico(origem.nome, destino.nome, origem.pais, destino.pais):
        if _sorte(semente, "rival", jogador.id, destino.id) < 0.3:
            return Resposta("recusa", "Não aceita defender o maior rival do clube")
    if origem is not None and destino.reputacao < origem.reputacao - 30 and proposta.salario < 2 * pedida:
        return Resposta("recusa", "Não quer descer tanto de patamar")
    luvas_esperadas = 3 * pedida if proposta.tipo in ("livre", "pre_contrato") else 0.0
    comissao_esperada = 0.05 * pedida * 12 * anos if proposta.tipo in ("livre", "pre_contrato") else 0.0
    mensal_efetivo = proposta.salario + (proposta.luvas - luvas_esperadas) / (12.0 * anos)
    if proposta.comissao + 1 < comissao_esperada:
        mensal_efetivo -= (comissao_esperada - proposta.comissao) / (12.0 * anos)
    if mensal_efetivo >= pedida:
        return Resposta("aceita", "Acertou os termos pessoais")
    if mensal_efetivo >= 0.85 * pedida:
        return Resposta("contraproposta", "O empresário pede um salário maior", pedida)
    return Resposta("recusa", "A proposta salarial ficou muito abaixo do que ele pede (cerca de "
                    + f"R$ {pedida:,.0f} por mês".replace(",", ".") + ")")


# ============================================================================
# Execução
# ============================================================================

def ajustar_elenco_apos_mudanca(*clubes: Clube) -> None:
    for clube in clubes:
        if clube is not None and clube.elenco:
            definir_status_e_hierarquia(clube.elenco)


@dataclass
class LivroDoMercado:
    """Contratos, empréstimos, propostas e agentes livres de todo o mundo detalhado."""

    contratos: Dict[int, Contrato] = field(default_factory=dict)
    emprestimos: Dict[int, Emprestimo] = field(default_factory=dict)
    propostas: Dict[int, Proposta] = field(default_factory=dict)
    agentes_livres: Dict[int, Jogador] = field(default_factory=dict)
    historico: List[Dict[str, Any]] = field(default_factory=list)
    proximo_id: int = 1

    def nova_proposta(self, **dados: Any) -> Proposta:
        proposta = Proposta(id=self.proximo_id, **dados)
        self.proximo_id += 1
        self.propostas[proposta.id] = proposta
        return proposta

    def registrar(self, texto: str, dia: date, tipo: str, valor: float = 0.0, **extra: Any) -> None:
        self.historico.insert(0, dict(texto=texto, data=dia.strftime("%d/%m/%Y"), tipo=tipo, valor=valor, **extra))
        del self.historico[200:]


def executar_transferencia(livro: LivroDoMercado, proposta: Proposta, jogador: Jogador, vendedor: Optional[Clube],
                           comprador: Clube, trocas: Sequence[Jogador], hoje: date) -> str:
    """Move o jogador e o dinheiro. Devolve a manchete."""
    tipo = proposta.tipo
    taxa = proposta.valor
    if tipo in ("definitiva", "troca", "multa", "emprestimo"):
        comprador.orcamento_transferencias -= taxa + proposta.luvas + proposta.comissao
        if vendedor is not None:
            vendedor.orcamento_transferencias += taxa
    else:
        comprador.orcamento_transferencias -= proposta.luvas + proposta.comissao
    if proposta.compensacao and vendedor is not None:
        vendedor.orcamento_transferencias -= proposta.compensacao
        comprador.orcamento_transferencias += proposta.compensacao
    if tipo == "pre_contrato":
        contrato = livro.contratos[jogador.id]
        contrato.pre_contrato_clube_id = comprador.id
        contrato.pre_contrato_salario = proposta.salario
        contrato.pre_contrato_anos = proposta.anos
        comprador.orcamento_transferencias += proposta.luvas + proposta.comissao  # pagos só na chegada
        return f"{jogador.nome} assina pré contrato com o {comprador.nome} e chega em {contrato.fim.strftime('%d/%m/%Y')}"
    if vendedor is not None and vendedor.jogador(jogador.id) is not None:
        vendedor.remover_jogador(jogador.id)
    livro.agentes_livres.pop(jogador.id, None)
    if comprador.jogador(jogador.id) is None:
        comprador.adicionar_jogador(jogador)
    for t in trocas:
        if comprador.jogador(t.id) is not None:
            comprador.remover_jogador(t.id)
        if vendedor is not None and vendedor.jogador(t.id) is None:
            vendedor.adicionar_jogador(t)
            if t.id in livro.contratos:
                livro.contratos[t.id].dono_id = vendedor.id
    if tipo == "emprestimo":
        fim = hoje + timedelta(days=int(30.4 * max(1, proposta.emprestimo_meses)))
        livro.emprestimos[jogador.id] = Emprestimo(
            jogador.id, vendedor.id if vendedor else 0, comprador.id, hoje, fim, proposta.emprestimo_tipo,
            proposta.emprestimo_valor_compra, 0.5, proposta.emprestimo_salario_pct, jogador.jogos, 0)
        manchete = f"{jogador.nome} chega emprestado ao {comprador.nome} até {fim.strftime('%d/%m/%Y')}"
    else:
        contrato = livro.contratos.get(jogador.id)
        salario = proposta.salario or (contrato.salario_mensal if contrato else salario_de_jogo(jogador, comprador))
        novo = Contrato(jogador.id, comprador.id, salario, date(hoje.year + max(1, proposta.anos), 12, 31),
                        arredondar_dinheiro(valor_de_jogo(jogador, comprador) * 3.0))
        if proposta.recompra_valor and vendedor is not None:
            novo.recompra_clube_id = vendedor.id
            novo.recompra_valor = proposta.recompra_valor
            novo.recompra_ate = date(hoje.year + max(1, proposta.recompra_anos), 12, 31)
        livro.contratos[jogador.id] = novo
        jogador.salario_mensal = salario
        nomes = {"definitiva": "contratado", "troca": "chega em troca", "multa": "chega pela multa rescisória",
                 "livre": "assina como agente livre"}
        manchete = f"{jogador.nome} é {nomes.get(tipo, 'contratado')} pelo {comprador.nome}"
        if taxa:
            manchete += f" por R$ {formatar_milhoes(taxa)}"
        if vendedor is not None and tipo != "livre":
            manchete += f", vindo do {vendedor.nome}"
    if proposta.papel == "Titular":
        jogador.status = StatusElenco.TITULAR
    jogador.moral = min(100.0, jogador.moral + 8)
    ajustar_elenco_apos_mudanca(vendedor, comprador)
    if proposta.papel == "Titular":
        jogador.status = StatusElenco.TITULAR
    return manchete


def formatar_milhoes(valor: float) -> str:
    if valor >= 1_000_000:
        return f"{valor / 1_000_000:.1f} mi".replace(".", ",")
    return f"{valor / 1_000:.0f} mil"


def encerrar_emprestimo(livro: LivroDoMercado, emprestimo: Emprestimo, clubes: Dict[int, Clube],
                        jogador: Jogador, comprar: Optional[bool], hoje: date) -> str:
    """Fim do empréstimo: volta, compra pela opção ou compra obrigatória pela meta."""
    origem, destino = clubes.get(emprestimo.origem_id), clubes.get(emprestimo.destino_id)
    livro.emprestimos.pop(jogador.id, None)
    jogos_no_periodo = jogador.jogos - emprestimo.jogos_do_jogador_no_inicio
    meta_cumprida = jogos_no_periodo >= 10 * emprestimo.meta_percentual
    compra = (emprestimo.tipo == "obrigacao" and meta_cumprida) or (emprestimo.tipo == "opcao" and comprar)
    if compra and destino is not None:
        destino.orcamento_transferencias -= emprestimo.valor_compra
        if origem is not None:
            origem.orcamento_transferencias += emprestimo.valor_compra
        contrato = livro.contratos.get(jogador.id)
        if contrato:
            contrato.dono_id = destino.id
        motivo = "meta da obrigação cumprida" if emprestimo.tipo == "obrigacao" else "opção de compra exercida"
        return f"{destino.nome} compra {jogador.nome} em definitivo ({motivo})"
    if destino is not None and destino.jogador(jogador.id) is not None:
        destino.remover_jogador(jogador.id)
    if origem is not None and origem.jogador(jogador.id) is None:
        origem.adicionar_jogador(jogador)
    ajustar_elenco_apos_mudanca(origem, destino)
    return f"{jogador.nome} volta ao {origem.nome if origem else 'clube de origem'} após o empréstimo"


def _arredondar_para_cima(valor: float) -> float:
    """Arredonda no padrão do jogo sem nunca ficar abaixo do valor exato (a sugestão precisa garantir o sim)."""
    r = arredondar_dinheiro(valor)
    passo = 1.0
    while r < valor:
        passo *= 1.01
        r = arredondar_dinheiro(valor * passo)
    return r


def sugerir_termos(jogador: Jogador, vendedor: Optional[Clube], comprador: Clube, contrato: Optional[Contrato],
                   tipo: str, papel: str, anos: int, hoje: date, semente: int) -> Dict[str, Any]:
    """Faixa de negociação pelas mesmas regras da resposta: mínimo para conversar e valor que garante o sim."""
    anos = max(1, min(5, int(anos)))
    saida: Dict[str, Any] = {"avisos": []}
    if vendedor is not None and contrato is not None and tipo in ("definitiva", "troca"):
        teto = pedida_do_clube(jogador, vendedor, comprador, contrato, hoje, semente, sorte=1.0)
        piso = pedida_do_clube(jogador, vendedor, comprador, contrato, hoje, semente, sorte=0.0)
        rival = buscar_classico(vendedor.nome, comprador.nome, vendedor.pais, comprador.pais) is not None
        if rival:
            teto, piso = teto * 1.2, piso * 1.2
            saida["avisos"].append("Clube rival: o vendedor só libera com proposta bem acima do normal.")
        saida["valor_seguro"] = _arredondar_para_cima(teto)
        saida["valor_minimo"] = arredondar_dinheiro(piso if rival else 0.75 * piso)
    teto_s = pedida_do_jogador(jogador, vendedor, comprador, contrato, papel, anos, hoje, semente, sorte=1.0)
    piso_s = pedida_do_jogador(jogador, vendedor, comprador, contrato, papel, anos, hoje, semente, sorte=0.0)
    if vendedor is not None and comprador.reputacao < vendedor.reputacao - 30:
        teto_s, piso_s = 2 * teto_s, 2 * piso_s
        saida["avisos"].append("Ele vem de um clube bem maior: só aceita descer de patamar ganhando o dobro.")
    if vendedor is not None and buscar_classico(vendedor.nome, comprador.nome, vendedor.pais, comprador.pais):
        saida["avisos"].append("Vindo do rival, existe chance de ele recusar seja qual for o salário.")
    saida["salario_seguro"] = _arredondar_para_cima(teto_s)
    saida["salario_minimo"] = arredondar_dinheiro(0.85 * piso_s)
    if tipo in ("livre", "pre_contrato"):
        saida["luvas"] = _arredondar_para_cima(3 * teto_s)
        saida["comissao"] = _arredondar_para_cima(0.05 * teto_s * 12 * anos)
    else:
        saida["luvas"] = 0.0
        saida["comissao"] = 0.0
    return saida

arquivos.megafut/mercado_mundo.py:
"""Mercado do mundo inteiro: janelas por país, negócios entre clubes da IA e as negociações do usuário.

Tipos de negócio (pedido do usuário): definitiva, livre, pré contrato, empréstimo (seco, com
opção ou com obrigação de compra), multa rescisória, troca e venda com cláusula de recompra.
As propostas do usuário passam por duas etapas, como na vida real: o clube dono dos
direitos e depois o jogador (salário, luvas, comissão, anos e papel no elenco). A resposta
chega no dia seguinte. Clubes da IA também fazem propostas pelos jogadores do usuário.
Valores, salários e contratos são estimativas do Megafut (o real fica CONFIRMAR).
"""
from __future__ import annotations

import random
from datetime import date, timedelta
from typing import Any, Dict, List, Optional, Sequence, Tuple

from .calendario import janela_aberta, janelas
from .classicos import buscar_classico
from .elencos import Ficha, definir_status_das_fichas, jogador_da_ficha, onze_provavel
from .enums import Posicao, StatusElenco
from .gerador import estimar_salario
from .mercado import (LISTA_DOS_CLUBES, sugerir_termos, Contrato, Proposta, arredondar_dinheiro, avaliar_pelo_clube, avaliar_pelo_jogador,
                      formatar_milhoes)

MINIMO_POR_POSICAO = {Posicao.GOL: 3, Posicao.ZAG: 4, Posicao.LAT: 4, Posicao.VOL: 3, Posicao.MEI: 3,
                      Posicao.PON: 3, Posicao.ATA: 3}
LIMITE_DO_ELENCO = 38
IMPORTANCIA = {"JOGADOR_CHAVE": 1.7, "TITULAR": 1.35, "JOVEM_PROMESSA": 1.5, "RODIZIO": 1.05, "RESERVA": 0.85}
DIAS_PARA_RESPONDER = 5


def _texto_dinheiro(valor: float) -> str:
    return formatar_milhoes(valor)


class MercadoMundo:
    def __init__(self, mundo: Any):
        self.mundo = mundo
        self.propostas: Dict[int, Dict[str, Any]] = {}
        self.historico: List[Dict[str, Any]] = []
        self.proximo = 1
        self.atencao = False
        self.listados: Dict[int, str] = {}  # jogadores do usuário oferecidos: venda ou empréstimo
        self._indice_dia = -1
        self._indice: Dict[Tuple[str, Posicao], List[Ficha]] = {}
        self.lista_ia: Dict[int, List[Any]] = {}  # jogadores que os clubes da IA oferecem: [modo, desconto]
        self.lista_mes = 0

    # ------------------------------------------------------------------
    # Estado
    # ------------------------------------------------------------------
    def para_dict(self) -> Dict[str, Any]:
        return {"propostas": list(self.propostas.values()), "historico": self.historico[:200],
                "proximo": self.proximo, "listados": [[k, v] for k, v in self.listados.items()],
                "lista_ia": [[k, v] for k, v in self.lista_ia.items()], "lista_mes": self.lista_mes}

    def de_dict(self, d: Dict[str, Any]) -> None:
        self.propostas = {p["id"]: p for p in d.get("propostas", [])}
        self.historico = list(d.get("historico", []))
        self.proximo = int(d.get("proximo", 1))
        self.listados = {k: v for k, v in d.get("listados", [])}
        self.lista_ia = {int(k): list(v) for k, v in d.get("lista_ia", [])}
        self.lista_mes = int(d.get("lista_mes", 0))
        self._sincronizar_lista()

    def precisa_de_atencao(self) -> bool:
        valor = self.atencao
        self.atencao = False
        return valor

    def janela(self, pais: str, dia: date) -> Optional[Any]:
        return janela_aberta(pais, dia)

    def _registrar(self, texto: str, dia: date, tipo: str, valor: float = 0.0, **extra: Any) -> None:
        self.historico.insert(0, dict(texto=texto, data=dia.strftime("%d/%m/%Y"), tipo=tipo, valor=valor, **extra))
        del self.historico[400:]

    # ------------------------------------------------------------------
    # O dia do mercado
    # ------------------------------------------------------------------
    def _sincronizar_lista(self) -> None:
        LISTA_DOS_CLUBES.clear()
        for fid, (modo, desconto) in self.lista_ia.items():
            LISTA_DOS_CLUBES[fid] = (modo, float(desconto))

    def atualizar_listas(self, hoje: date) -> None:
        """Todo mês cada clube da IA oferece quem sobra: reservas mais velhos à venda com desconto e
        jovens ou reservas por empréstimo (quem leva paga o salário, sem taxa)."""
        mundo = self.mundo
        rng = random.Random(f"{mundo.semente}|listas|{hoje.year}|{hoje.month}")
        self.lista_ia = {}
        for clube in mundo.clubes.values():
            if clube.id == mundo.usuario or not clube.tem_elenco:
                continue
            ordem = sorted(clube.elenco, key=lambda f: -f.nivel)
            sobra = [f for f in ordem[14:] if not f.emp and not f.pre and f.dono == clube.id and f.jogador is None]
            if not sobra:
                continue
            venda = [f for f in sobra if f.idade >= 24]
            emprestimo = [f for f in sobra if f.idade <= 23 or f.status == "RESERVA"]
            for f in rng.sample(venda, min(len(venda), rng.choice((0, 1, 1, 2, 2, 3)))):
                self.lista_ia[f.id] = ["venda", round(rng.uniform(0.55, 0.8), 2)]
            for f in rng.sample(emprestimo, min(len(emprestimo), rng.choice((0, 1, 1, 2, 2)))):
                if f.id not in self.lista_ia:
                    self.lista_ia[f.id] = ["emprestimo", 1.0]
            if len(clube.elenco) > 32 and rng.random() < 0.5:  # elenco inchado: até um titular de rodízio sai
                extra = [f for f in ordem[8:14] if not f.emp and f.dono == clube.id and f.id not in self.lista_ia]
                if extra:
                    self.lista_ia[rng.choice(extra).id] = ["venda", round(rng.uniform(0.75, 0.9), 2)]
        self.lista_mes = hoje.year * 12 + hoje.month
        self._sincronizar_lista()

    def dia(self, hoje: date) -> List[str]:
        noticias: List[str] = []
        if self.lista_mes != hoje.year * 12 + hoje.month:
            self.atualizar_listas(hoje)
        noticias.extend(self._fim_de_emprestimos(hoje))
        if (hoje.month, hoje.day) in ((10, 1), (11, 15), (12, 5)):
            noticias.extend(self._aviso_de_contratos(hoje))
        paises = {c.pais for c in self.mundo.clubes.values() if c.tem_elenco}
        abertos = {p for p in paises if janela_aberta(p, hoje)}
        rng = random.Random(f"{self.mundo.semente}|mercado|{hoje.toordinal()}")
        if abertos:
            self._atividade_da_ia(hoje, abertos, rng)
        usuario = self.mundo.clubes[self.mundo.usuario]
        if usuario.pais in abertos:
            self._propostas_para_o_usuario(hoje, rng)
        noticias.extend(self._processar_propostas(hoje))
        return noticias

    def _indice_do_dia(self, hoje: date) -> Dict[Tuple[str, Posicao], List[Ficha]]:
        if self._indice_dia == hoje.toordinal():
            return self._indice
        self._indice = {}
        usuario = self.mundo.usuario
        for ficha in self.mundo.fichas.values():
            if ficha.clube == usuario or ficha.clube < 0 or ficha.emp or ficha.pre:
                continue
            pais = self.mundo.clubes[ficha.clube].pais if ficha.clube > 0 else "livre"
            self._indice.setdefault((pais, ficha.pos), []).append(ficha)
        self._indice_dia = hoje.toordinal()
        return self._indice

    def _necessidade(self, clube: Any) -> Optional[Tuple[Posicao, float]]:
        contagem: Dict[Posicao, List[Ficha]] = {p: [] for p in Posicao}
        for f in clube.elenco:
            contagem[f.pos].append(f)
        faltas = [(MINIMO_POR_POSICAO[p] - len(v), p) for p, v in contagem.items()]
        faltas.sort(key=lambda t: -t[0])
        if faltas[0][0] > 0:
            return faltas[0][1], clube.nivel - 1.0
        onze = onze_provavel(clube.elenco, so_disponiveis=False)
        if not onze:
            return None
        pior = min(onze, key=lambda f: f.nivel)
        if pior.nivel < clube.nivel - 0.8:
            return pior.pos, max(pior.nivel + 0.4, clube.nivel - 0.3)
        return None

    def _atividade_da_ia(self, hoje: date, abertos: set, rng: random.Random) -> None:
        mundo = self.mundo
        compradores = [c for c in mundo.clubes.values()
                       if c.pais in abertos and c.tem_elenco and c.id != mundo.usuario]
        if not compradores:
            return
        tentativas = max(1, int(len(compradores) * 0.035))
        indice = self._indice_do_dia(hoje)
        for clube in rng.sample(compradores, min(tentativas, len(compradores))):
            necessidade = self._necessidade(clube)
            if necessidade is None:
                if rng.random() < 0.85:
                    continue
                posicao, minimo = rng.choice(list(Posicao)), clube.nivel + 0.2
            else:
                posicao, minimo = necessidade
            self._tentar_contratar(clube, posicao, minimo, hoje, rng, indice)
            if len(clube.elenco) > LIMITE_DO_ELENCO:
                self._dispensar_excedente(clube, hoje)

    def _tentar_contratar(self, clube: Any, posicao: Posicao, minimo: float, hoje: date, rng: random.Random,
                          indice: Dict[Tuple[str, Posicao], List[Ficha]]) -> None:
        mundo = self.mundo
        pools = list(indice.get((clube.pais, posicao), [])) + list(indice.get(("livre", posicao), []))
        if clube.reputacao >= 65:
            for (pais, pos), lista in indice.items():
                if pos == posicao and pais not in (clube.pais, "livre"):
                    pools.extend(lista)
        candidatos = []
        for ficha in rng.sample(pools, min(len(pools), 250)):
            if ficha.nivel < minimo or ficha.idade > 33 or ficha.clube == clube.id or ficha.lesao > 20:
                continue
            vendedor = mundo.clubes.get(ficha.clube) if ficha.clube > 0 else None
            if vendedor is not None and vendedor.reputacao > clube.reputacao + 8:
                continue
            candidatos.append(ficha)
        if not candidatos:
            return
        candidatos.sort(key=lambda f: -f.nivel)
        alvo = rng.choice(candidatos[:4])
        vendedor = mundo.clubes.get(alvo.clube) if alvo.clube > 0 else None
        if vendedor is None:
            salario = estimar_salario(alvo.nivel, alvo.idade, clube.reputacao) * rng.uniform(0.9, 1.15)
            if salario * 12 > clube.receita * 0.08 and rng.random() < 0.7:
                return
            self._mover(alvo, None, clube, 0.0, salario, rng.randint(1, 3), hoje, "livre")
            return
        restante = (alvo.fim - hoje.toordinal()) / 30.0 if alvo.fim else 0
        preco = alvo.valor(vendedor.reputacao) * IMPORTANCIA.get(alvo.status, 1.0)
        preco *= 0.55 if restante <= 6 else (0.8 if restante <= 12 else 1.0)
        rival = buscar_classico(vendedor.nome, clube.nome, vendedor.pais, clube.pais) is not None
        if rival:
            preco *= 1.4
        preco = arredondar_dinheiro(preco * rng.uniform(0.92, 1.1))
        chance = 0.55 * (0.4 if rival else 1.0) * (0.5 if alvo.status == "JOGADOR_CHAVE" else 1.0)
        if preco > clube.orcamento:
            if alvo.status in ("RESERVA", "RODIZIO", "JOVEM_PROMESSA") and rng.random() < 0.5 and not rival:
                salario = alvo.salario
                if rng.random() < chance:
                    self._emprestar(alvo, vendedor, clube, hoje, rng.choice((6, 12)), "seco", 0.0, 1.0)
            return
        if rng.random() > chance:
            return
        salario = max(alvo.salario * 1.1, estimar_salario(alvo.nivel, alvo.idade, clube.reputacao))
        self._mover(alvo, vendedor, clube, preco, salario * rng.uniform(0.95, 1.1), rng.randint(2, 4), hoje,
                    "definitiva")

    def _dispensar_excedente(self, clube: Any, hoje: date) -> None:
        livres = sorted((f for f in clube.elenco if not f.emp and f.jogador is None), key=lambda f: (f.nivel, -f.idade))
        while len(clube.elenco) > LIMITE_DO_ELENCO and livres:
            ficha = livres.pop(0)
            self._liberar(ficha, clube, hoje, "dispensado")

    # ------------------------------------------------------------------
    # Movimentos
    # ------------------------------------------------------------------
    def _tirar_do_clube(self, ficha: Ficha, clube: Any) -> None:
        mundo = self.mundo
        if ficha in clube.elenco:
            clube.elenco.remove(ficha)
        clube.forca_dia = -1
        if clube.id == mundo.usuario and ficha.jogador is not None and mundo.clube_usuario is not None:
            if ficha.jogador in mundo.clube_usuario.elenco:
                mundo.clube_usuario.elenco.remove(ficha.jogador)
            from .elencos import copiar_estado_para_ficha
            copiar_estado_para_ficha(ficha.jogador, ficha)
            ficha.jogador = None
        self.listados.pop(ficha.id, None)
        if self.lista_ia.pop(ficha.id, None) is not None:
            LISTA_DOS_CLUBES.pop(ficha.id, None)

    def _por_no_clube(self, ficha: Ficha, clube: Any) -> None:
        mundo = self.mundo
        ficha.clube = clube.id
        clube.elenco.append(ficha)
        clube.forca_dia = -1
        if ficha.id in mundo.livres:
            mundo.livres.remove(ficha.id)
        if clube.id == mundo.usuario and mundo.clube_usuario is not None:
            ficha.jogador = jogador_da_ficha(ficha, clube.nome, mundo.data)
            mundo.clube_usuario.elenco.append(ficha.jogador)
        definir_status_das_fichas(clube.elenco)
        if clube.id == mundo.usuario and mundo.clube_usuario is not None:
            from .mercado import ajustar_elenco_apos_mudanca
            ajustar_elenco_apos_mudanca(mundo.clube_usuario)

    def _mover(self, ficha: Ficha, vendedor: Optional[Any], comprador: Any, taxa: float, salario: float, anos: int,
               hoje: date, tipo: str, luvas: float = 0.0, comissao: float = 0.0) -> str:
        if vendedor is not None:
            self._tirar_do_clube(ficha, vendedor)
            vendedor.caixa += taxa
            vendedor.orcamento += 0.5 * taxa
            definir_status_das_fichas(vendedor.elenco)
        comprador.caixa -= taxa + luvas + comissao
        comprador.orcamento = max(0.0, comprador.orcamento - taxa - luvas)
        ficha.dono = comprador.id
        ficha.emp = None
        ficha.pre = None
        ficha.salario = round(salario, -2)
        ficha.fim = date(hoje.year + max(0, anos - 1) + (1 if hoje.month > 6 else 0), 12, 31).toordinal()
        ficha.multa = round(3.0 * ficha.valor(comprador.reputacao), -4)
        ficha.moral = min(90.0, ficha.moral + 5)
        self._por_no_clube(ficha, comprador)
        origem = vendedor.nome if vendedor is not None else "sem clube"
        if tipo == "livre":
            texto = f"{comprador.nome} contrata {ficha.nome} ({ficha.pos.value}), que estava sem clube."
        elif tipo == "multa":
            texto = f"{comprador.nome} paga a multa de {_texto_dinheiro(taxa)} e tira {ficha.nome} do {origem}."
        else:
            texto = f"{ficha.nome} ({ficha.pos.value}) troca o {origem} pelo {comprador.nome} por {_texto_dinheiro(taxa)}."
        self._registrar(texto, hoje, tipo, taxa, jogador=ficha.id, de=vendedor.id if vendedor else 0, para=comprador.id)
        self._noticiar_se_relevante(texto, taxa, vendedor, comprador)
        return texto

    def _emprestar(self, ficha: Ficha, dono: Any, destino: Any, hoje: date, meses: int, tipo: str,
                   valor_compra: float, salario_pct: float, meta: float = 0.5) -> str:
        self._tirar_do_clube(ficha, dono)
        definir_status_das_fichas(dono.elenco)
        fim = hoje + timedelta(days=int(30.4 * meses))
        fim = date(fim.year, 12, 31) if fim.month >= 12 or (fim.month == 1) else date(fim.year, fim.month, 28)
        ficha.dono = dono.id
        ficha.emp = [dono.id, fim.toordinal(), tipo, float(valor_compra), float(salario_pct), ficha.jogos, meta,
                     round(ficha.nivel, 2), hoje.toordinal()]
        self._por_no_clube(ficha, destino)
        detalhe = {"seco": "", "opcao": f", com opção de compra de {_texto_dinheiro(valor_compra)}",
                   "obrigacao": f", com obrigação de compra de {_texto_dinheiro(valor_compra)}"}.get(tipo, "")
        texto = f"{ficha.nome} vai emprestado do {dono.nome} ao {destino.nome} até {fim.strftime('%d/%m/%Y')}{detalhe}."
        self._registrar(texto, hoje, "emprestimo", 0.0, jogador=ficha.id, de=dono.id, para=destino.id)
        self._noticiar_se_relevante(texto, 0.0, dono, destino)
        return texto

    def _liberar(self, ficha: Ficha, clube: Any, hoje: date, motivo: str) -> None:
        self._tirar_do_clube(ficha, clube)
        ficha.clube = 0
        ficha.dono = 0
        ficha.emp = None
        ficha.salario = 0.0
        ficha.fim = 0
        self.mundo.livres.append(ficha.id)
        self._registrar(f"{ficha.nome} deixa o {clube.nome} ({motivo}).", hoje, "saida", 0.0, jogador=ficha.id,
                        de=clube.id, para=0)

    def _noticiar_se_relevante(self, texto: str, taxa: float, a: Optional[Any], b: Any) -> None:
        mundo = self.mundo
        envolvidos = {x.id for x in (a, b) if x is not None}
        usuario = mundo.usuario
        liga_usuario = mundo.clubes[usuario].liga
        if usuario in envolvidos:
            mundo.noticia(texto, "mercado", usuario)
            self.atencao = True
        elif taxa >= 15_000_000 or any(mundo.clubes[c].liga == liga_usuario for c in envolvidos):
            mundo.noticia(texto, "mercado")

    def multa_de_retorno(self, ficha: Ficha, hoje: date) -> float:
        """Multa para encerrar o empréstimo antes do fim: proporcional ao tempo que falta (estimativa do Megafut)."""
        if not ficha.emp:
            return 0.0
        fim = int(ficha.emp[1])
        inicio = int(ficha.emp[8]) if len(ficha.emp) > 8 else fim - 365
        total = max(30, fim - inicio)
        resta = max(0, fim - hoje.toordinal())
        dono = self.mundo.clubes.get(int(ficha.emp[0]))
        base = max(0.12 * ficha.valor(dono.reputacao if dono else 40), 3 * ficha.salario)
        return round(base * resta / total, -3)

    def chamar_de_volta(self, ficha_id: int, hoje: date) -> Dict[str, Any]:
        """O usuário encerra o empréstimo de um jogador seu e paga a multa ao clube que estava com ele."""
        mundo = self.mundo
        ficha = mundo.fichas.get(int(ficha_id))
        if ficha is None or not ficha.emp or int(ficha.emp[0]) != mundo.usuario or ficha.clube == mundo.usuario:
            return {"ok": False, "erro": "Esse jogador não está emprestado pelo seu clube."}
        dono = mundo.clubes[mundo.usuario]
        if self.janela(dono.pais, hoje) is None:
            return {"ok": False, "erro": "Só dá para chamar de volta com a janela de transferências aberta."}
        multa = self.multa_de_retorno(ficha, hoje)
        if multa > dono.caixa:
            return {"ok": False, "erro": f"Caixa insuficiente para a multa de {_texto_dinheiro(multa)}."}
        if ficha.clube > 0:
            atual = mundo.clubes[ficha.clube]
            self._tirar_do_clube(ficha, atual)
            atual.caixa = round(atual.caixa + multa, -2)
            nome_atual = atual.nome
        else:
            if ficha in dono.cedidos:
                dono.cedidos.remove(ficha)
            nome_atual = "clube de fora"
        ficha.emp = None
        dono.caixa = round(dono.caixa - multa, -2)
        if mundo.clube_usuario is not None:
            mundo.clube_usuario.saldo_caixa = dono.caixa
        self._por_no_clube(ficha, dono)
        if mundo.gestao is not None and multa:
            mundo.gestao.lancar(hoje, f"Multa para encerrar o empréstimo de {ficha.nome}", -multa)
        texto = (f"{ficha.nome} volta ao {dono.nome} antes do fim do empréstimo no {nome_atual}. "
                 f"Multa paga: {_texto_dinheiro(multa)}.")
        self._registrar(texto, hoje, "retorno", multa, jogador=ficha.id, de=ficha.clube, para=dono.id)
        mundo.noticia(texto, "mercado", mundo.usuario)
        return {"ok": True, "texto": texto, "multa": multa}

    def _fim_de_emprestimos(self, hoje: date) -> List[str]:
        noticias = []
        dia = hoje.toordinal()
        mundo = self.mundo
        for ficha in list(mundo.fichas.values()):
            if not ficha.emp or ficha.emp[1] > dia:
                continue
            origem, _fim, tipo, valor, _pct, jogos_inicio, meta = ficha.emp[:7]
            atual = mundo.clubes.get(ficha.clube) if ficha.clube > 0 else None
            if origem == -1:  # volta a um clube fora do jogo
                if atual is not None:
                    self._tirar_do_clube(ficha, atual)
                mundo._remover_ficha(ficha)
                continue
            dono = mundo.clubes.get(origem)
            if dono is None:
                ficha.emp = None
                continue
            if ficha.clube == -1:  # estava num clube fora do jogo: volta ao dono
                if ficha in dono.cedidos:
                    dono.cedidos.remove(ficha)
                ficha.emp = None
                self._por_no_clube(ficha, dono)
                continue
            if atual is None:
                ficha.emp = None
                continue
            jogou = ficha.jogos - int(jogos_inicio)
            comprar = False
            if tipo == "obrigacao" and jogou >= 10 * float(meta):
                comprar = True
            elif tipo == "opcao" and atual.id != mundo.usuario:
                comprar = ficha.nivel >= atual.nivel - 0.3 and valor <= atual.orcamento
            if comprar:
                ficha.emp = None
                texto = self._mover(ficha, dono, atual, float(valor), ficha.salario, 3, hoje, "definitiva")
                noticias.append(texto)
                continue
            ficha.emp = None
            self._tirar_do_clube(ficha, atual)
            self._por_no_clube(ficha, dono)
            texto = f"{ficha.nome} volta ao {dono.nome} ao fim do empréstimo no {atual.nome}."
            self._registrar(texto, hoje, "retorno", 0.0, jogador=ficha.id, de=atual.id, para=dono.id)
            if mundo.usuario in (dono.id, atual.id):
                mundo.noticia(texto, "mercado", mundo.usuario)
        return noticias

    def _aviso_de_contratos(self, hoje: date) -> List[str]:
        mundo = self.mundo
        limite = date(hoje.year, 12, 31).toordinal()
        vencendo = [f for f in mundo.clubes[mundo.usuario].elenco if f.dono == mundo.usuario and f.fim and
                    f.fim <= limite and not f.pre]
        if not vencendo:
            return []
        nomes = ", ".join(f.nome for f in sorted(vencendo, key=lambda f: -f.nivel)[:6])
        texto = (f"{len(vencendo)} jogadores com contrato até 31/12 ({nomes}). Sem renovação, eles saem no "
                 "fim do ano: veja a tela de contratos.")
        mundo.noticia(texto, "contratos", mundo.usuario)
        self.atencao = True
        return [texto]

    # ------------------------------------------------------------------
    # IA quer jogadores do usuário
    # ------------------------------------------------------------------
    def _propostas_para_o_usuario(self, hoje: date, rng: random.Random) -> None:
        mundo = self.mundo
        usuario = mundo.clubes[mundo.usuario]
        recebidas = [p for p in self.propostas.values() if not p["do_usuario"] and p["etapa"] == "aguardando_usuario"]
        if len(recebidas) >= 3:
            return
        chance = 0.10 + (0.25 if self.listados else 0.0)
        if rng.random() > chance:
            return
        elenco = [f for f in usuario.elenco if not f.emp and f.lesao == 0]
        if not elenco:
            return
        listados = [f for f in elenco if f.id in self.listados]
        pesos = [f.nivel ** 2 * (3.0 if f.id in self.listados else 1.0) for f in elenco]
        alvo = listados[0] if listados and rng.random() < 0.6 else _sortear(elenco, pesos, rng)
        interessados = [c for c in mundo.clubes.values() if c.tem_elenco and c.id != usuario.id and
                        c.reputacao >= usuario.reputacao - 15 and c.orcamento > 0 and
                        janela_aberta(c.pais, hoje)]
        if not interessados:
            return
        comprador = rng.choice(interessados)
        modo = self.listados.get(alvo.id, "venda")
        valor = arredondar_dinheiro(alvo.valor(usuario.reputacao) * IMPORTANCIA.get(alvo.status, 1.0)
                                    * rng.uniform(0.7, 1.15))
        if modo == "emprestimo" or valor > comprador.orcamento * 1.2:
            proposta = self._nova(tipo="emprestimo", jogador=alvo.id, comprador=comprador.id, vendedor=usuario.id,
                                  hoje=hoje, do_usuario=False, emprestimo_tipo=rng.choice(("seco", "opcao")),
                                  emprestimo_meses=rng.choice((6, 12)), emprestimo_salario_pct=rng.choice((0.7, 1.0)),
                                  emprestimo_valor_compra=arredondar_dinheiro(valor * 1.1), valor=0.0)
        else:
            proposta = self._nova(tipo="definitiva", jogador=alvo.id, comprador=comprador.id, vendedor=usuario.id,
                                  hoje=hoje, do_usuario=False, valor=valor)
        proposta["etapa"] = "aguardando_usuario"
        proposta["maximo"] = arredondar_dinheiro(valor * rng.uniform(1.1, 1.45))
        proposta["expira"] = (hoje + timedelta(days=DIAS_PARA_RESPONDER)).toordinal()
        proposta["historico"].append(f"{hoje.strftime('%d/%m')}: {comprador.nome} oferece "
                                     f"{_texto_dinheiro(proposta['valor']) if proposta['valor'] else 'empréstimo'} por "
                                     f"{alvo.nome}.")
        mundo.noticia(f"Proposta recebida: {comprador.nome} quer {alvo.nome}.", "proposta", usuario.id)
        self.atencao = True

    # ------------------------------------------------------------------
    # Propostas
    # ------------------------------------------------------------------
    def _nova(self, tipo: str, jogador: int, comprador: int, vendedor: int, hoje: date, do_usuario: bool,
              **extra: Any) -> Dict[str, Any]:
        proposta = {"id": self.proximo, "tipo": tipo, "jogador": jogador, "comprador": comprador,
                    "vendedor": vendedor, "data": hoje.toordinal(), "do_usuario": do_usuario, "etapa": "clube",
                    "historico": [], "valor": 0.0, "trocas": [], "emprestimo_tipo": "seco", "emprestimo_meses": 6,
                    "emprestimo_valor_compra": 0.0, "emprestimo_salario_pct": 1.0, "emprestimo_meta": 0.5,
                    "recompra_valor": 0.0, "recompra_anos": 0, "salario": 0.0, "luvas": 0.0, "comissao": 0.0,
                    "anos": 3, "papel": "Rodízio", "pedida_clube": 0.0, "pedida_salario": 0.0, "compensacao": 0.0,
                    "responder_em": hoje.toordinal(), "expira": 0}
        proposta.update(extra)
        self.propostas[proposta["id"]] = proposta
        self.proximo += 1
        return proposta

    def propor(self, dados: Dict[str, Any]) -> Dict[str, Any]:
        """Proposta do usuário. A resposta chega no dia seguinte (ou na hora, para recompra e multa)."""
        mundo = self.mundo
        hoje = mundo.data
        ficha = mundo.fichas.get(int(dados.get("jogador", 0)))
        if ficha is None:
            return {"ok": False, "erro": "Jogador não encontrado"}
        tipo = str(dados.get("tipo", "definitiva"))
        usuario = mundo.clubes[mundo.usuario]
        if ficha.clube == usuario.id and tipo not in ("recompra",):
            return {"ok": False, "erro": "O jogador já é do seu elenco"}
        vendedor_id = ficha.dono if ficha.dono > 0 else 0
        if tipo in ("definitiva", "emprestimo", "troca", "multa") and not vendedor_id:
            tipo = "livre"
        if tipo != "livre" and tipo != "pre_contrato" and not janela_aberta(usuario.pais, hoje):
            return {"ok": False, "erro": "Janela de transferências fechada no seu país"}
        if tipo == "pre_contrato":
            restante = (ficha.fim - hoje.toordinal()) if ficha.fim else 0
            if not ficha.fim or restante > 183:
                return {"ok": False, "erro": "Pré contrato só com seis meses ou menos de contrato"}
        if tipo == "recompra":
            return self._exercer_recompra(ficha, hoje)
        if not mundo.topa_o_projeto(ficha, tipo):
            return {"ok": False, "erro": f"{ficha.nome} agradece, mas não tem interesse em jogar no {usuario.nome} "
                                         "neste momento. Quer um clube de outro patamar."}
        campos = {k: dados[k] for k in ("valor", "salario", "luvas", "comissao", "anos", "papel", "emprestimo_tipo",
                                        "emprestimo_meses", "emprestimo_valor_compra", "emprestimo_salario_pct",
                                        "emprestimo_meta") if k in dados}
        campos["trocas"] = [int(t) for t in dados.get("trocas", []) if int(t) in mundo.fichas]
        for chave in ("valor", "salario", "luvas", "comissao", "emprestimo_valor_compra"):
            if chave in campos:
                campos[chave] = max(0.0, float(campos[chave]))
        proposta = self._nova(tipo, ficha.id, usuario.id, vendedor_id, hoje, True, **campos)
        proposta["etapa"] = "jogador" if tipo in ("livre", "pre_contrato") else "clube"
        proposta["historico"].append(f"{hoje.strftime('%d/%m')}: proposta enviada ({self._rotulo(tipo)}).")
        return {"ok": True, "proposta": proposta["id"]}

    def sugestao(self, jogador_id: int, tipo: str = "definitiva", papel: str = "Rodízio", anos: int = 3) -> Dict[str, Any]:
        """Quanto oferecer: mínimo para receber resposta e valor que garante o sim (mesmas regras da avaliação)."""
        mundo = self.mundo
        ficha = mundo.fichas.get(int(jogador_id))
        if ficha is None:
            return {"ok": False, "erro": "Jogador não encontrado"}
        vendedor_id = ficha.dono if ficha.dono > 0 else 0
        if not vendedor_id:
            tipo = "livre"
        falsa = {"jogador": ficha.id, "vendedor": vendedor_id, "comprador": mundo.usuario, "trocas": []}
        jogador, vendedor, comprador, _ = self._objetos(falsa)
        contrato = self._contrato_da_ficha(ficha) if vendedor_id else None
        dados = sugerir_termos(jogador, vendedor, comprador, contrato, tipo, papel, anos, mundo.data, mundo.semente)
        verba = float(getattr(comprador, "orcamento_transferencias", 0.0) or 0.0)
        dados.update({"ok": True, "tipo": tipo, "verba": arredondar_dinheiro(max(0.0, verba))})
        lista = self.lista_ia.get(ficha.id)
        if lista and lista[0] == "venda":
            dados["avisos"].insert(0, f"Está na lista de transferência do {vendedor.nome}: o clube aceita cerca de "
                                      f"{round(100 * float(lista[1]))}% do valor de mercado.")
        elif lista and lista[0] == "emprestimo":
            dados["avisos"].insert(0, f"Está na lista de empréstimo do {vendedor.nome}: sai sem taxa se você pagar "
                                      "100% do salário (empréstimo seco).")
        dados["lista"] = lista[0] if lista else ""
        if not mundo.topa_o_projeto(ficha, tipo):
            dados["avisos"].insert(0, f"{ficha.nome} não demonstra interesse em jogar no {comprador.nome} agora: "
                                      "procura um clube de outro patamar.")
            dados["recusa"] = True
        if dados.get("valor_seguro") and dados["valor_seguro"] > verba:
            dados["avisos"].append("O valor que garante o negócio passa da sua verba de transferências.")
        return dados

    @staticmethod
    def _rotulo(tipo: str) -> str:
        return {"definitiva": "transferência definitiva", "livre": "contratação de jogador livre",
                "pre_contrato": "pré contrato", "emprestimo": "empréstimo", "multa": "multa rescisória",
                "troca": "troca", "recompra": "recompra"}.get(tipo, tipo)

    def _contrato_da_ficha(self, ficha: Ficha) -> Contrato:
        fim = ficha.fim_data() or date(self.mundo.ano, 12, 31)
        return Contrato(ficha.id, ficha.dono, ficha.salario, fim, ficha.multa)

    def _objetos(self, proposta: Dict[str, Any]) -> Tuple[Any, Any, Any, List[Any]]:
        """Jogador, vendedor e comprador como objetos completos, para as regras de negociação."""
        mundo = self.mundo
        ficha = mundo.fichas[proposta["jogador"]]
        vendedor = None
        if proposta["vendedor"]:
            vendedor = mundo.clube_usuario if proposta["vendedor"] == mundo.usuario else \
                mundo._clube_temporario(proposta["vendedor"]) if mundo.clubes[proposta["vendedor"]].tem_elenco else None
            if vendedor is None:
                vendedor = mundo._montar_clube_completo(proposta["vendedor"])
        comprador = mundo.clube_usuario if proposta["comprador"] == mundo.usuario else \
            mundo._montar_clube_completo(proposta["comprador"])
        jogador = None
        if vendedor is not None:
            jogador = next((j for j in vendedor.elenco if j.id == ficha.id), None)
        if jogador is None:
            nome_clube = mundo.clubes[ficha.clube].nome if ficha.clube > 0 else "Sem clube"
            jogador = ficha.jogador or jogador_da_ficha(ficha, nome_clube, mundo.data)
            jogador.status = ficha.status_enum
        trocas = []
        for fid in proposta.get("trocas", []):
            f = mundo.fichas.get(fid)
            if f is not None:
                trocas.append(f.jogador or jogador_da_ficha(f, mundo.clubes[mundo.usuario].nome, mundo.data))
        return jogador, vendedor, comprador, trocas

    def _como_proposta(self, p: Dict[str, Any]) -> Proposta:
        return Proposta(id=p["id"], tipo=p["tipo"], jogador_id=p["jogador"], comprador_id=p["comprador"],
                        vendedor_id=p["vendedor"], data=date.fromordinal(p["data"]), valor=p["valor"],
                        trocas=list(p.get("trocas", [])), emprestimo_tipo=p["emprestimo_tipo"],
                        emprestimo_meses=int(p["emprestimo_meses"]),
                        emprestimo_valor_compra=p["emprestimo_valor_compra"],
                        emprestimo_salario_pct=float(p["emprestimo_salario_pct"]), salario=p["salario"],
                        luvas=p["luvas"], comissao=p["comissao"], anos=int(p["anos"]), papel=p["papel"],
                        do_usuario=p["do_usuario"])

    def _processar_propostas(self, hoje: date) -> List[str]:
        noticias = []
        dia = hoje.toordinal()
        for p in list(self.propostas.values()):
            if p["etapa"] in ("concluida", "recusada", "expirada", "cancelada"):
                if dia - p["data"] > 40:
                    del self.propostas[p["id"]]
                continue
            if p["etapa"] == "aguardando_usuario":
                if p.get("expira") and dia > p["expira"]:
                    p["etapa"] = "expirada"
                    p["historico"].append(f"{hoje.strftime('%d/%m')}: proposta expirou sem resposta.")
                continue
            if not p["do_usuario"] or p.get("responder_em", 0) > dia:
                continue
            noticias.extend(self._responder_ao_usuario(p, hoje))
        return noticias

    def _responder_ao_usuario(self, p: Dict[str, Any], hoje: date) -> List[str]:
        mundo = self.mundo
        ficha = mundo.fichas.get(p["jogador"])
        data = hoje.strftime("%d/%m")
        if ficha is None or (p["vendedor"] and ficha.dono != p["vendedor"] and ficha.clube != p["vendedor"]):
            p["etapa"] = "cancelada"
            p["historico"].append(f"{data}: o jogador não está mais disponível.")
            self.atencao = True
            return []
        jogador, vendedor, comprador, trocas = self._objetos(p)
        semente = mundo.semente
        proposta = self._como_proposta(p)
        if p["etapa"] == "clube":
            contrato = self._contrato_da_ficha(ficha)
            resposta = avaliar_pelo_clube(proposta, jogador, vendedor, comprador, contrato, trocas, hoje, semente)
            p["pedida_clube"] = proposta.pedida_clube
            p["compensacao"] = proposta.compensacao
            p["historico"].append(f"{data}: {mundo.clubes[p['vendedor']].nome}: {resposta.motivo}.")
            if resposta.decisao == "aceita":
                p["etapa"] = "jogador"
            elif resposta.decisao == "contraproposta":
                p["etapa"] = "aguardando_usuario"
                p["contra"] = resposta.valor
                p["expira"] = (hoje + timedelta(days=DIAS_PARA_RESPONDER)).toordinal()
                p["origem_contra"] = "clube"
                self.atencao = True
                return [f"Contraproposta do {mundo.clubes[p['vendedor']].nome} por {ficha.nome}."]
            else:
                p["etapa"] = "recusada"
                self.atencao = True
                return [f"Proposta por {ficha.nome} recusada."]
        if p["etapa"] == "jogador":
            contrato = self._contrato_da_ficha(ficha) if ficha.dono else None
            resposta = avaliar_pelo_jogador(proposta, jogador, vendedor, comprador, contrato, hoje, semente)
            p["pedida_salario"] = proposta.pedida_salario
            p["historico"].append(f"{data}: {ficha.nome}: {resposta.motivo}.")
            if resposta.decisao == "aceita":
                texto = self._executar(p, hoje)
                p["etapa"] = "concluida"
                self.atencao = True
                return [texto]
            if resposta.decisao == "contraproposta":
                p["etapa"] = "aguardando_usuario"
                p["contra_salario"] = resposta.valor
                p["origem_contra"] = "jogador"
                p["expira"] = (hoje + timedelta(days=DIAS_PARA_RESPONDER)).toordinal()
                self.atencao = True
                return [f"{ficha.nome} pede salário de {_texto_dinheiro(resposta.valor)} por mês."]
            p["etapa"] = "recusada"
            self.atencao = True
            return [f"{ficha.nome} recusou a proposta."]
        return []

    def responder(self, pid: int, decisao: str, valor: Optional[float] = None, salario: Optional[float] = None,
                  recompra_valor: float = 0.0, recompra_anos: int = 0) -> Dict[str, Any]:
        """O usuário responde: a uma proposta recebida ou a uma contraproposta (melhorar, aceitar, desistir)."""
        mundo = self.mundo
        hoje = mundo.data
        p = self.propostas.get(int(pid))
        if p is None or p["etapa"] != "aguardando_usuario":
            return {"ok": False, "erro": "Proposta não está esperando resposta"}
        data = hoje.strftime("%d/%m")
        if p["do_usuario"]:
            if decisao == "desistir":
                p["etapa"] = "cancelada"
                p["historico"].append(f"{data}: você desistiu.")
                return {"ok": True}
            if p.get("origem_contra") == "clube":
                p["valor"] = float(valor if valor is not None else p.get("contra", p["valor"]))
                p["etapa"] = "clube"
            else:
                p["salario"] = float(salario if salario is not None else p.get("contra_salario", p["salario"]))
                p["etapa"] = "jogador"
            p["responder_em"] = hoje.toordinal()
            p["historico"].append(f"{data}: nova oferta enviada.")
            return {"ok": True}
        ficha = mundo.fichas.get(p["jogador"])
        comprador = mundo.clubes.get(p["comprador"])
        if ficha is None or comprador is None or ficha.clube != mundo.usuario:
            p["etapa"] = "cancelada"
            return {"ok": False, "erro": "Negócio não é mais possível"}
        if decisao == "recusar":
            p["etapa"] = "recusada"
            p["historico"].append(f"{data}: você recusou.")
            return {"ok": True}
        if decisao == "contraproposta" and p["tipo"] == "definitiva":
            pedido = float(valor or 0.0)
            if pedido <= p.get("maximo", p["valor"]):
                p["valor"] = pedido
                decisao = "aceitar"
                p["historico"].append(f"{data}: {comprador.nome} aceitou pagar {_texto_dinheiro(pedido)}.")
            else:
                p["etapa"] = "recusada"
                p["historico"].append(f"{data}: {comprador.nome} achou caro e desistiu.")
                return {"ok": True, "resultado": "recusada"}
        if decisao == "aceitar":
            if recompra_valor > 0 and p["tipo"] == "definitiva":
                p["recompra_valor"] = float(recompra_valor)
                p["recompra_anos"] = int(recompra_anos or 2)
            texto = self._executar(p, hoje)
            p["etapa"] = "concluida"
            p["historico"].append(f"{data}: {texto}")
            return {"ok": True, "texto": texto}
        return {"ok": False, "erro": "Decisão inválida"}

    def _executar(self, p: Dict[str, Any], hoje: date) -> str:
        mundo = self.mundo
        ficha = mundo.fichas[p["jogador"]]
        comprador = mundo.clubes[p["comprador"]]
        vendedor = mundo.clubes.get(p["vendedor"]) if p["vendedor"] else None
        tipo = p["tipo"]
        if tipo == "emprestimo" and vendedor is not None:
            return self._emprestar(ficha, vendedor, comprador, hoje, int(p["emprestimo_meses"]), p["emprestimo_tipo"],
                                   float(p["emprestimo_valor_compra"]), float(p["emprestimo_salario_pct"]),
                                   float(p.get("emprestimo_meta", 0.5)))
        if tipo == "pre_contrato":
            ficha.pre = [comprador.id, float(p["salario"]), int(p["anos"])]
            texto = f"{ficha.nome} assina pré contrato com o {comprador.nome} e chega no fim do contrato atual."
            self._registrar(texto, hoje, "pre_contrato", 0.0, jogador=ficha.id, de=ficha.dono, para=comprador.id)
            mundo.noticia(texto, "mercado", comprador.id)
            return texto
        if tipo == "troca" and vendedor is not None:
            for fid in p.get("trocas", []):
                saida = mundo.fichas.get(fid)
                if saida is not None and saida.clube == comprador.id:
                    self._mover(saida, comprador, vendedor, 0.0, max(saida.salario, saida.salario_estimado(
                        vendedor.reputacao)), 3, hoje, "troca")
            if p.get("compensacao"):
                vendedor.caixa -= p["compensacao"]
                comprador.caixa += p["compensacao"]
        taxa = float(p["valor"]) if tipo in ("definitiva", "multa", "troca") else 0.0
        if tipo == "multa":
            taxa = max(taxa, ficha.multa)
        salario = float(p["salario"]) if p["do_usuario"] else max(ficha.salario * 1.1, ficha.salario_estimado(
            comprador.reputacao))
        texto = self._mover(ficha, vendedor, comprador, taxa, salario, int(p["anos"]) if p["do_usuario"] else 3, hoje,
                            "livre" if tipo == "livre" else ("multa" if tipo == "multa" else "definitiva"),
                            float(p.get("luvas", 0.0)), float(p.get("comissao", 0.0)))
        if p.get("recompra_valor") and vendedor is not None:
            ate = date(hoje.year + int(p.get("recompra_anos") or 2), 12, 31).toordinal()
            ficha.recompra = [vendedor.id, float(p["recompra_valor"]), ate]
            texto += f" Cláusula de recompra: {_texto_dinheiro(p['recompra_valor'])}."
        return texto

    def _exercer_recompra(self, ficha: Ficha, hoje: date) -> Dict[str, Any]:
        mundo = self.mundo
        if not ficha.recompra or ficha.recompra[0] != mundo.usuario or hoje.toordinal() > ficha.recompra[2]:
            return {"ok": False, "erro": "Sem cláusula de recompra válida para o seu clube"}
        if not janela_aberta(mundo.clubes[mundo.usuario].pais, hoje):
            return {"ok": False, "erro": "Janela de transferências fechada no seu país"}
        vendedor = mundo.clubes[ficha.clube]
        usuario = mundo.clubes[mundo.usuario]
        valor = float(ficha.recompra[1])
        ficha.recompra = None
        texto = self._mover(ficha, vendedor, usuario, valor, ficha.salario, 3, hoje, "definitiva")
        return {"ok": True, "texto": "Recompra exercida: " + texto}

    # ------------------------------------------------------------------
    # Ações do usuário sobre o próprio elenco
    # ------------------------------------------------------------------
    def listar(self, ficha_id: int, modo: str) -> Dict[str, Any]:
        ficha = self.mundo.fichas.get(int(ficha_id))
        if ficha is None or ficha.clube != self.mundo.usuario:
            return {"ok": False, "erro": "Jogador não é do seu elenco"}
        if modo in ("venda", "emprestimo"):
            self.listados[ficha.id] = modo
        else:
            self.listados.pop(ficha.id, None)
        return {"ok": True}

    def renovar(self, ficha_id: int, salario: float, anos: int) -> Dict[str, Any]:
        mundo = self.mundo
        ficha = mundo.fichas.get(int(ficha_id))
        if ficha is None or ficha.clube != mundo.usuario or ficha.dono != mundo.usuario:
            return {"ok": False, "erro": "Só renova quem tem contrato com o seu clube"}
        usuario = mundo.clubes[mundo.usuario]
        pedida = max(ficha.salario * 1.08, ficha.salario_estimado(usuario.reputacao) * 0.95)
        if ficha.status in ("JOGADOR_CHAVE", "TITULAR"):
            pedida *= 1.08
        if ficha.idade >= 31 and anos >= 3:
            pedida *= 0.95
        pedida = arredondar_dinheiro(pedida)
        if float(salario) + 1 < pedida:
            return {"ok": False, "pedida": pedida, "erro": f"{ficha.nome} pede {_texto_dinheiro(pedida)} por mês"}
        ficha.salario = float(salario)
        ficha.fim = date(mundo.ano + max(1, min(5, int(anos))), 12, 31).toordinal()
        ficha.multa = round(3.0 * ficha.valor(usuario.reputacao), -4)
        if ficha.jogador is not None:
            ficha.jogador.salario_mensal = ficha.salario
            ficha.jogador.contrato_ate = date.fromordinal(ficha.fim).year
        texto = f"{ficha.nome} renova com o {usuario.nome} até {date.fromordinal(ficha.fim).year}."
        mundo.noticia(texto, "mercado", usuario.id)
        return {"ok": True, "texto": texto}

    def rescindir(self, ficha_id: int) -> Dict[str, Any]:
        mundo = self.mundo
        ficha = mundo.fichas.get(int(ficha_id))
        if ficha is None or ficha.clube != mundo.usuario:
            return {"ok": False, "erro": "Jogador não é do seu elenco"}
        usuario = mundo.clubes[mundo.usuario]
        if ficha.emp and ficha.dono != usuario.id:
            dono = mundo.clubes.get(ficha.dono)
            self._tirar_do_clube(ficha, usuario)
            ficha.emp = None
            if dono is not None:
                self._por_no_clube(ficha, dono)
            return {"ok": True, "texto": f"{ficha.nome} devolvido ao {dono.nome if dono else 'clube de origem'}."}
        meses = max(0, (ficha.fim - mundo.data.toordinal()) // 30) if ficha.fim else 0
        multa = ficha.salario * meses
        usuario.caixa -= multa
        self._liberar(ficha, usuario, mundo.data, "contrato rescindido")
        return {"ok": True, "texto": f"Contrato de {ficha.nome} rescindido. Custo: {_texto_dinheiro(multa)}."}

    # ------------------------------------------------------------------
    # Fim do ano: contratos e pré contratos
    # ------------------------------------------------------------------
    def fim_de_ano(self, ano: int) -> List[str]:
        mundo = self.mundo
        rng = random.Random(f"{mundo.semente}|contratos|{ano}")
        limite = date(ano, 12, 31).toordinal()
        hoje = mundo.data
        textos = []
        for ficha in list(mundo.fichas.values()):
            if not ficha.fim or ficha.fim > limite or ficha.clube <= 0 and not ficha.pre:
                continue
            if ficha.emp and ficha.dono != ficha.clube:
                continue  # empréstimo: quem decide é o dono, no fim do empréstimo
            clube = mundo.clubes.get(ficha.clube)
            if ficha.pre:
                destino = mundo.clubes.get(ficha.pre[0])
                if destino is not None and clube is not None:
                    salario, anos = ficha.pre[1], ficha.pre[2]
                    ficha.pre = None
                    textos.append(self._mover(ficha, clube, destino, 0.0, salario, anos, hoje, "livre"))
                    continue
            if clube is None:
                continue
            if clube.id == mundo.usuario:
                textos.append(f"{ficha.nome} saiu do {clube.nome}: contrato terminou sem renovação.")
                self._liberar(ficha, clube, hoje, "fim de contrato")
                continue
            chance = {"JOGADOR_CHAVE": 0.85, "TITULAR": 0.72, "JOVEM_PROMESSA": 0.8, "RODIZIO": 0.5,
                      "RESERVA": 0.25}.get(ficha.status, 0.4)
            if ficha.idade >= 33:
                chance *= 0.5
            if rng.random() < chance:
                ficha.salario = round(max(ficha.salario, ficha.salario_estimado(clube.reputacao)) *
                                      rng.uniform(0.95, 1.12), -2)
                ficha.fim = date(ano + rng.randint(1, 3), 12, 31).toordinal()
                ficha.multa = round(3.0 * ficha.valor(clube.reputacao), -4)
            else:
                self._liberar(ficha, clube, hoje, "fim de contrato")
        return textos[:40]

    # ------------------------------------------------------------------
    # Consulta para a interface
    # ------------------------------------------------------------------
    def buscar(self, posicao: str = "", pais: str = "", idade_max: int = 99, nivel_min: float = 0.0,
               valor_max: float = 0.0, livres: bool = False, texto: str = "", limite: int = 80, liga: str = "",
               nacionalidade: str = "", valor_min: float = 0.0, idade_min: int = 0, situacao: str = "",
               ordem: str = "ovr") -> List[Ficha]:
        mundo = self.mundo
        alvo_pos = Posicao[posicao] if posicao in Posicao.__members__ else None
        termo = texto.lower().strip()
        nac = nacionalidade.lower().strip()
        saida = []
        for ficha in mundo.fichas.values():
            if ficha.clube == mundo.usuario or ficha.clube < 0:
                continue
            if (livres or situacao == "livres") and ficha.clube != 0:
                continue
            if situacao in ("venda", "emprestimo") and (self.lista_ia.get(ficha.id) or [""])[0] != situacao:
                continue
            if alvo_pos is not None and ficha.pos != alvo_pos:
                continue
            if ficha.idade > idade_max or ficha.idade < idade_min or ficha.nivel < nivel_min:
                continue
            if nac and ficha.nac.lower() != nac:
                continue
            clube = mundo.clubes.get(ficha.clube)
            if pais and (clube is None or clube.pais != pais):
                continue
            if liga and (clube is None or clube.liga != liga):
                continue
            if termo and termo not in ficha.nome.lower() and (clube is None or termo not in clube.nome.lower()):
                continue
            if valor_max or valor_min:
                valor = self.preco_pedido(ficha)
                if (valor_max and valor > valor_max) or valor < valor_min:
                    continue
            saida.append(ficha)
        if ordem == "barato":
            saida.sort(key=lambda f: (self.preco_pedido(f), -f.nivel))
        elif ordem == "jovem":
            saida.sort(key=lambda f: (f.idade, -f.nivel))
        else:
            saida.sort(key=lambda f: -f.nivel)
        return saida[:limite]

    def preco_pedido(self, ficha: Ficha) -> float:
        """Preço de referência na busca: valor de mercado, com o desconto de quem está na lista de transferência."""
        clube = self.mundo.clubes.get(ficha.clube)
        valor = ficha.valor(clube.reputacao if clube else 40)
        lista = self.lista_ia.get(ficha.id)
        if lista and lista[0] == "venda":
            valor *= float(lista[1])
        return arredondar_dinheiro(valor)


def _sortear(itens: Sequence[Any], pesos: Sequence[float], rng: random.Random) -> Any:
    total = sum(pesos)
    alvo = rng.random() * total
    acumulado = 0.0
    for item, peso in zip(itens, pesos):
        acumulado += peso
        if acumulado >= alvo:
            return item
    return itens[-1]

