"""Persistência: leitura dos dados reais, importação de elencos e gravação do estado.

Os dados do jogo moram na pasta dados/ (arquivos JSON). No arquivo único para
celular eles vêm embutidos, então nada precisa ser copiado à parte.
"""
from __future__ import annotations

import copy
import json
from dataclasses import fields, is_dataclass
from datetime import date
from enum import Enum
from pathlib import Path
from typing import Any, Dict, List, Optional

from .craques import estimar_nivel_por_valor, jogador_real, sem_hifen
from .entidades import (
    GRUPOS_DE_ATRIBUTOS, CategoriaDeBase, Clube, ContratoPatrocinio, Jogador, Tecnico, calcular_idade,
)
from .enums import Hierarquia, PerfilTecnico, Posicao, StatusElenco
from .gerador import definir_status_e_hierarquia
from .gestao import ReferenciaComercial

ARQUIVOS_DE_CRAQUES = {
    "brasileirao": ("craques_brasil_parte1.json", "craques_brasil_parte2.json"),
    "americas": ("craques_america_do_sul.json", "craques_america_do_norte.json"),
}
ARQUIVO_REFERENCIAS = "referencias_comerciais.json"
ARQUIVO_COMPETICOES = "competicoes_catalogo.json"

NIVEL_TIPICO_DA_DIVISAO = {"Série A": 12.5, "Série B": 11.0, "Série C": 10.0, "Série D": 9.0}
REPUTACAO_TIPICA_DA_DIVISAO = {"Série A": 70, "Série B": 50, "Série C": 35, "Série D": 25}

_DADOS_EMBUTIDOS: Dict[str, Any] = {}


def registrar_dados_embutidos(dados: Dict[str, Any]) -> None:
    """Usado pelo arquivo único: deixa os JSON dentro do próprio programa."""
    _DADOS_EMBUTIDOS.update(dados)


def pastas_de_dados() -> List[Path]:
    aqui = Path(__file__).resolve().parent
    return [aqui / "dados", aqui.parent / "dados", Path.cwd() / "dados"]


def ler_dados(nome_arquivo: str) -> Any:
    if nome_arquivo in _DADOS_EMBUTIDOS:
        return copy.deepcopy(_DADOS_EMBUTIDOS[nome_arquivo])
    for pasta in pastas_de_dados():
        caminho = pasta / nome_arquivo
        if caminho.exists():
            with caminho.open(encoding="utf8") as arquivo:
                return json.load(arquivo)
    raise FileNotFoundError(f"Arquivo de dados não encontrado: {nome_arquivo}")


def carregar_listas_de_craques() -> Dict[str, List[Dict]]:
    listas: Dict[str, List[Dict]] = {}
    for grupo, arquivos in ARQUIVOS_DE_CRAQUES.items():
        listas[grupo] = []
        for nome in arquivos:
            listas[grupo].extend(ler_dados(nome))
    return listas


def carregar_referencias_comerciais() -> List[ReferenciaComercial]:
    try:
        dados = ler_dados(ARQUIVO_REFERENCIAS)
    except FileNotFoundError:
        return []
    referencias = []
    for item in dados.get("referencias", []):
        valor = item.get("valor_anual_brl")
        referencias.append(ReferenciaComercial(
            faixa=item["faixa"], cota=item["cota"],
            valor_anual=float(valor) if isinstance(valor, (int, float)) else None,
            fonte=item.get("fonte", "CONFIRMAR"),
        ))
    return referencias


def carregar_catalogo_de_competicoes() -> Dict[str, Any]:
    try:
        return ler_dados(ARQUIVO_COMPETICOES)
    except FileNotFoundError:
        return {"paises": [], "continentais": []}


# ============================================================================
# Importação de elencos pesquisados ou licenciados
# ============================================================================

def importar_elenco_pesquisado(dados: Dict[str, Any], clube_id: int, id_inicial: int,
                               referencia: date) -> Clube:
    """Cria um clube real a partir de um arquivo de elenco (formato da pesquisa).

    Campos esperados por jogador: nome_exibicao, posicao, data_nascimento,
    nacionalidade, pe, altura_cm, peso_kg, valor_mercado_eur. Os atributos
    são estimados pelo valor de mercado e pela idade.
    """
    divisao = str(dados.get("divisao_2026", ""))
    chave_divisao = next((d for d in NIVEL_TIPICO_DA_DIVISAO if d.lower() in divisao.lower()), "Série A")
    nivel_divisao = NIVEL_TIPICO_DA_DIVISAO[chave_divisao]
    jogadores: List[Jogador] = []
    proximo = id_inicial
    for entrada in dados.get("jogadores", []):
        entrada = dict(entrada)
        entrada.setdefault("titulos", [])
        entrada.setdefault("fontes", dados.get("fontes", []))
        entrada["clube_atual"] = dados.get("clube", "")
        nascimento = entrada.get("data_nascimento") or ""
        idade = 26
        if nascimento and "CONFIRMAR" not in nascimento:
            idade = calcular_idade(nascimento, referencia)
        valor = entrada.get("valor_mercado_eur")
        nivel = estimar_nivel_por_valor(valor if isinstance(valor, (int, float)) else None, idade, nivel_divisao)
        jogador = jogador_real(entrada, proximo, referencia, nivel_estimado=nivel)
        proximo += 1
        if jogador is not None:
            jogadores.append(jogador)
    definir_status_e_hierarquia(jogadores)
    tecnico_dados = dados.get("tecnico") or {}
    clube = Clube(
        id=clube_id, nome=sem_hifen(str(dados.get("clube", ""))), sigla=str(dados.get("sigla", ""))[:3].upper(),
        reputacao=REPUTACAO_TIPICA_DA_DIVISAO[chave_divisao], orcamento_transferencias=0.0,
        orcamento_salarial=0.0, elenco=jogadores,
        tecnico=Tecnico(nome=sem_hifen(str(tecnico_dados.get("nome", "Técnico"))), leitura_de_jogo=13),
        cidade=str(dados.get("cidade", "")), estado=str(dados.get("estado", "")), pais="Brasil",
        estadio=sem_hifen(str(dados.get("estadio", ""))), divisao=chave_divisao,
        dados_reais=True, fontes=list(dados.get("fontes", [])),
    )
    if not clube.sigla:
        clube.sigla = clube.nome[:3].upper()
    return clube


# ============================================================================
# Gravação e leitura do estado do jogo
# ============================================================================

def _para_json(obj: Any) -> Any:
    if isinstance(obj, Enum):
        return obj.name
    if isinstance(obj, date):
        return obj.strftime("%d/%m/%Y")
    if is_dataclass(obj):
        return {f.name: _para_json(getattr(obj, f.name)) for f in fields(obj)}
    if isinstance(obj, (list, tuple)):
        return [_para_json(item) for item in obj]
    if isinstance(obj, set):
        return sorted(_para_json(item) for item in obj)
    if isinstance(obj, dict):
        return {str(_para_json(k)): _para_json(v) for k, v in obj.items()}
    return obj


def _jogador_de_dict(d: Dict[str, Any]) -> Jogador:
    argumentos: Dict[str, Any] = {}
    classes_dos_grupos = dict(GRUPOS_DE_ATRIBUTOS)
    for campo in fields(Jogador):
        if campo.name not in d:
            continue
        valor = d[campo.name]
        if campo.name in classes_dos_grupos:
            valor = classes_dos_grupos[campo.name](**valor)
        elif campo.name == "posicao":
            valor = Posicao[valor]
        elif campo.name == "posicoes_secundarias":
            valor = [Posicao[v] for v in valor]
        elif campo.name == "status":
            valor = StatusElenco[valor]
        elif campo.name == "hierarquia":
            valor = Hierarquia[valor]
        argumentos[campo.name] = valor
    return Jogador(**argumentos)


def _clube_de_dict(d: Dict[str, Any]) -> Clube:
    argumentos: Dict[str, Any] = {}
    for campo in fields(Clube):
        if campo.name not in d:
            continue
        valor = d[campo.name]
        if campo.name == "elenco":
            valor = [_jogador_de_dict(j) for j in valor]
        elif campo.name == "tecnico":
            valor = dict(valor)
            valor["perfil"] = PerfilTecnico[valor["perfil"]]
            valor = Tecnico(**valor)
        elif campo.name == "patrocinios":
            valor = [ContratoPatrocinio(**c) for c in valor]
        elif campo.name == "base":
            valor = dict(valor)
            valor["elenco"] = [_jogador_de_dict(j) for j in valor.get("elenco", [])]
            valor = CategoriaDeBase(**valor)
        argumentos[campo.name] = valor
    return Clube(**argumentos)


def salvar_clubes(caminho: str, clubes: List[Clube]) -> None:
    conteudo = {"versao": 1, "clubes": [_para_json(c) for c in clubes]}
    with open(caminho, "w", encoding="utf8") as arquivo:
        json.dump(conteudo, arquivo, ensure_ascii=False, indent=2)


def carregar_clubes(caminho: str) -> List[Clube]:
    with open(caminho, encoding="utf8") as arquivo:
        conteudo = json.load(arquivo)
    return [_clube_de_dict(c) for c in conteudo.get("clubes", [])]

