"""Funções utilitárias compartilhadas por todos os módulos do Megafut."""
from __future__ import annotations

import math
import random
import sys
from typing import Sequence, TypeVar

T = TypeVar("T")

# Sinal de menos tipográfico (U+2212). Os textos exibidos usam este caractere
# para números negativos, o que mantém todas as saídas livres de hífen.
MENOS = "−"


def limitar(valor: float, minimo: float, maximo: float) -> float:
    """Prende o valor dentro do intervalo [minimo, maximo]."""
    if valor < minimo:
        return minimo
    if valor > maximo:
        return maximo
    return valor


def sigmoide(x: float) -> float:
    """Função logística, estável para valores grandes."""
    if x >= 0:
        z = math.exp(-x)
        return 1.0 / (1.0 + z)
    z = math.exp(x)
    return z / (1.0 + z)


def logito(p: float) -> float:
    """Inversa da sigmoide."""
    p = limitar(p, 1e-6, 1.0 - 1e-6)
    return math.log(p / (1.0 - p))


def rolar_dados(rng: random.Random, quantidade: int = 3, faces: int = 6) -> int:
    """Rola N dados de F faces e devolve a soma (3d6 por padrão)."""
    total = 0
    for _ in range(quantidade):
        total += rng.randint(1, faces)
    return total


def escolher_ponderado(rng: random.Random, itens: Sequence[T], pesos: Sequence[float]) -> T:
    """Sorteia um item com probabilidade proporcional ao seu peso."""
    total = 0.0
    for peso in pesos:
        if peso > 0:
            total += peso
    if total <= 0:
        return itens[rng.randrange(len(itens))]
    alvo = rng.random() * total
    acumulado = 0.0
    for item, peso in zip(itens, pesos):
        if peso <= 0:
            continue
        acumulado += peso
        if alvo <= acumulado:
            return item
    return itens[-1]


def fmt_decimal(valor: float, casas: int = 1) -> str:
    """Número com vírgula decimal e sinal de menos tipográfico."""
    arredondado = round(valor, casas)
    texto = f"{abs(arredondado):.{casas}f}".replace(".", ",")
    return MENOS + texto if arredondado < 0 else texto


def fmt_sinal(valor: float, casas: int = 0) -> str:
    """Número com sinal explícito: +3, −2 ou 0."""
    arredondado = round(valor, casas)
    texto = f"{abs(arredondado):.{casas}f}".replace(".", ",")
    if arredondado > 0:
        return "+" + texto
    if arredondado < 0:
        return MENOS + texto
    return texto


def fmt_dinheiro(valor: float) -> str:
    """Valor em reais no formato curto do futebol: R$ 12,5 mi."""
    if valor >= 1_000_000_000:
        return f"R$ {fmt_decimal(valor / 1_000_000_000, 2)} bi"
    if valor >= 1_000_000:
        return f"R$ {fmt_decimal(valor / 1_000_000, 1)} mi"
    if valor >= 1_000:
        return f"R$ {valor / 1_000:.0f} mil"
    return f"R$ {valor:.0f}"


def fmt_dolares(valor: float) -> str:
    """Valor em dólares, como o almanaque informa (sem conversão de moeda): US$ 54,57 mi."""
    if valor >= 1_000_000:
        return f"US$ {fmt_decimal(valor / 1_000_000, 2)} mi"
    if valor >= 1_000:
        return f"US$ {fmt_decimal(valor / 1_000, 1)} mil"
    return f"US$ {valor:.0f}"


def fmt_dolares_exato(valor: float) -> str:
    """Valor exato em dólares com ponto de milhar: US$ 6.425.000."""
    return "US$ " + f"{valor:,.0f}".replace(",", ".")


def abreviar_nome(nome: str, limite: int = 15) -> str:
    """Encurta 'Lucas Andrade Silva' para 'L. Silva' quando passa do limite."""
    if len(nome) <= limite:
        return nome
    partes = nome.split()
    if len(partes) >= 2:
        sobrenome = partes[-1]
        if len(partes) >= 3 and partes[-2].lower() in ("de", "da", "do", "dos", "das", "di", "del", "van", "von"):
            sobrenome = f"{partes[-2]} {partes[-1]}"
        curto = f"{partes[0][0]}. {sobrenome}"
        if len(curto) <= limite:
            return curto
    return nome[:limite]


_ICONES = {
    "gol": ("⚽", "[GOL]"),
    "amarelo": ("🟨", "[AMARELO]"),
    "vermelho": ("🟥", "[VERMELHO]"),
    "troca": ("🔁", "[TROCA]"),
    "tatica": ("🧠", "[TÁTICA]"),
    "lesao": ("🚑", "[LESÃO]"),
    "defesa": ("🧤", "[DEFESA]"),
    "trave": ("🥅", "[TRAVE]"),
    "estrela": ("⭐", "*"),
    "apito": ("📣", "[APITO]"),
}
_USAR_EMOJI = True


def configurar_emojis(ativo: bool) -> None:
    """Liga ou desliga os emojis (alguns terminais antigos não mostram)."""
    global _USAR_EMOJI
    _USAR_EMOJI = bool(ativo)


def icone(nome: str) -> str:
    emoji, texto = _ICONES[nome]
    return emoji if _USAR_EMOJI else texto


def preparar_saida_utf8() -> None:
    """Garante acentos e símbolos corretos no terminal do celular."""
    codificacao = (getattr(sys.stdout, "encoding", "") or "").lower()
    if "utf" in codificacao and "8" in codificacao:
        return
    try:
        sys.stdout.reconfigure(encoding="utf8")
    except (AttributeError, ValueError, OSError):
        pass

