"""Psicologia do elenco: moral, disputa por titularidade, hierarquia e efeito cascata.

Regras principais:
1. O resultado mexe na moral conforme a expectativa (vencer um gigante vale
   muito; vencer quem devia vencer vale pouco).
2. Clássico pesa por si só: ganhar ou perder um clássico mexe com o grupo
   mesmo que os times estejam em divisões ou momentos diferentes.
3. Quem não joga perde moral conforme a promessa feita no contrato e conforme
   se acha melhor que o titular da posição (nível maior que o dele).
4. Líderes insatisfeitos contaminam o vestiário (efeito cascata).
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple

from .avaliacao import nivel_geral
from .entidades import Clube, Jogador
from .enums import Hierarquia, Posicao, SituacaoJogo, StatusElenco, TomDeclaracao
from .estatisticas import Participacao, ResultadoPartida
from .util import fmt_decimal, limitar, sigmoide


@dataclass
class MudancaMoral:
    jogador: Jogador
    antes: float
    depois: float
    motivo: str

    @property
    def delta(self) -> float:
        return self.depois - self.antes


PESO_HIERARQUIA = {Hierarquia.LIDER: 3.0, Hierarquia.INFLUENTE: 2.0, Hierarquia.REGULAR: 1.0, Hierarquia.NOVATO: 0.5}

PERDA_BANCO_POR_STATUS = {
    StatusElenco.JOGADOR_CHAVE: 9.0,
    StatusElenco.TITULAR: 6.0,
    StatusElenco.RODIZIO: 3.0,
    StatusElenco.RESERVA: 1.2,
    StatusElenco.JOVEM_PROMESSA: 0.5,
}

STATUS_QUE_ESPERAM_JOGAR = (StatusElenco.JOGADOR_CHAVE, StatusElenco.TITULAR)

GRUPO_DE_POSICAO = {
    Posicao.GOL: "goleiros", Posicao.ZAG: "zagueiros", Posicao.LAT: "laterais",
    Posicao.VOL: "meio", Posicao.MEI: "meio", Posicao.PON: "ataque", Posicao.ATA: "ataque",
}


def expectativa_de_pontos(clube: Clube, adversario: Clube, em_casa: bool) -> float:
    """Fração de pontos esperada pela reputação (0 a 1)."""
    return sigmoide((clube.reputacao - adversario.reputacao + (6 if em_casa else -6)) / 12.0)


def _aplicar(lista: List[MudancaMoral], jogador: Jogador, delta: float, motivo: str) -> None:
    antes = jogador.moral
    jogador.ajustar_moral(delta)
    lista.append(MudancaMoral(jogador, antes, jogador.moral, motivo))


def _rotulo_resultado(pontos: float, peso_classico: float) -> str:
    base = {1.0: "vitória", 0.5: "empate", 0.0: "derrota"}[pontos]
    return f"{base} no clássico" if peso_classico >= 0.5 else base


def processar_moral_pos_jogo(clube: Clube, resultado: ResultadoPartida) -> Tuple[List[MudancaMoral], List[str]]:
    """Atualiza a moral de todo o elenco depois de um jogo e devolve as mudanças e as notícias."""
    em_casa = resultado.casa is clube
    adversario = resultado.fora if em_casa else resultado.casa
    gols_pro, gols_contra = resultado.gols_de(clube)
    pontos = 1.0 if gols_pro > gols_contra else (0.5 if gols_pro == gols_contra else 0.0)
    expectativa = expectativa_de_pontos(clube, adversario, em_casa)
    peso = resultado.peso_classico
    efeito_resultado = 10.0 * (pontos - expectativa) + 3.0 * (pontos - 0.5)
    efeito_resultado += 12.0 * peso * (pontos - 0.5)
    rotulo = _rotulo_resultado(pontos, peso)

    # Nível do titular mais fraco de cada grupo de posição, para a comparação de quem ficou de fora.
    titular_mais_fraco: Dict[str, float] = {}
    for jogador in clube.elenco:
        part = resultado.participacoes.get(jogador.id)
        if part is not None and part.situacao == SituacaoJogo.TITULAR:
            grupo = GRUPO_DE_POSICAO[jogador.posicao]
            nivel = nivel_geral(jogador)
            titular_mais_fraco[grupo] = min(titular_mais_fraco.get(grupo, 99.0), nivel)

    mudancas: List[MudancaMoral] = []
    noticias: List[str] = []
    for jogador in clube.elenco:
        part: Optional[Participacao] = resultado.participacoes.get(jogador.id)
        p = jogador.personalidade
        ambicao = 0.8 + p.ambicao / 50.0
        fator_negativo = 1.3 - p.temperamento / 40.0
        if part is None:
            situacao = SituacaoJogo.INDISPONIVEL if not jogador.disponivel else SituacaoJogo.NAO_RELACIONADO
        else:
            situacao = part.situacao

        if situacao == SituacaoJogo.TITULAR:
            delta = efeito_resultado * ambicao + (part.nota - 6.6) * 4.0
            motivo = f"{rotulo} (nota {fmt_decimal(part.nota)})"
        elif situacao == SituacaoJogo.ENTROU:
            bonus = 1.5 if jogador.status not in STATUS_QUE_ESPERAM_JOGAR else -1.0
            delta = efeito_resultado * ambicao * 0.6 + (part.nota - 6.6) * 2.0 + bonus
            motivo = f"{rotulo}, saiu do banco"
        elif situacao == SituacaoJogo.NAO_UTILIZADO:
            perda = PERDA_BANCO_POR_STATUS[jogador.status] * (1 + 0.3 * min(jogador.jogos_sem_atuar, 4))
            delta = -perda * (0.7 + p.ambicao / 33.0) + efeito_resultado * 0.25
            motivo = f"ficou no banco sem jogar ({jogador.status.rotulo})"
        elif situacao == SituacaoJogo.NAO_RELACIONADO:
            peso_status = 1.2 if jogador.status in STATUS_QUE_ESPERAM_JOGAR else 0.6
            perda = PERDA_BANCO_POR_STATUS[jogador.status] * peso_status * (1 + 0.3 * min(jogador.jogos_sem_atuar, 4))
            delta = -perda * (0.7 + p.ambicao / 33.0) + efeito_resultado * 0.15
            motivo = f"fora da lista do jogo ({jogador.status.rotulo})"
        else:
            delta = efeito_resultado * 0.2
            motivo = "fora do jogo por lesão ou suspensão"

        # Disputa por titularidade: quem se acha melhor que o titular sofre mais.
        if situacao in (SituacaoJogo.ENTROU, SituacaoJogo.NAO_UTILIZADO, SituacaoJogo.NAO_RELACIONADO):
            jogador.jogos_sem_ser_titular += 1
            frustracao = 0.0
            if jogador.status in STATUS_QUE_ESPERAM_JOGAR:
                frustracao += 3.5 if jogador.status == StatusElenco.JOGADOR_CHAVE else 2.5
            rival = titular_mais_fraco.get(GRUPO_DE_POSICAO[jogador.posicao])
            meu_nivel = nivel_geral(jogador)
            if rival is not None and meu_nivel >= rival + 0.5:
                frustracao += 1.5 + (meu_nivel - rival) * 0.8
                motivo += ", se acha melhor que o titular"
            if frustracao > 0:
                frustracao *= (0.6 + p.ambicao / 25.0) * (1.0 + 0.2 * min(jogador.jogos_sem_ser_titular, 5))
                delta -= frustracao
                if jogador.jogos_sem_ser_titular >= 3 and frustracao >= 3.0 and not jogador.insatisfeito:
                    jogador.insatisfeito = True
                    noticias.append(f"{jogador.nome} ({clube.sigla}) está insatisfeito com a reserva "
                                    f"e pede uma conversa com o técnico.")
        elif situacao == SituacaoJogo.TITULAR:
            jogador.jogos_sem_ser_titular = 0
            if jogador.insatisfeito and jogador.moral >= 55:
                jogador.insatisfeito = False

        if delta < 0:
            delta *= fator_negativo
            if resultado.jogo_grande:
                delta *= 1.25 - p.pressao / 40.0
        _aplicar(mudancas, jogador, delta, motivo)

        if situacao in (SituacaoJogo.TITULAR, SituacaoJogo.ENTROU):
            jogador.jogos_sem_atuar = 0
        elif situacao in (SituacaoJogo.NAO_UTILIZADO, SituacaoJogo.NAO_RELACIONADO):
            jogador.jogos_sem_atuar += 1

    if peso >= 0.5:
        if pontos == 1.0:
            noticias.append(f"{clube.nome}: vestiário em festa, vencer o clássico levanta o grupo.")
        elif pontos == 0.0:
            noticias.append(f"{clube.nome}: clima pesado, perder o clássico dói mais que qualquer derrota.")
    return mudancas, noticias


def efeito_cascata(clube: Clube) -> Tuple[List[MudancaMoral], List[str]]:
    """O humor dos líderes contamina o resto do grupo."""
    total_peso = sum(PESO_HIERARQUIA[j.hierarquia] for j in clube.elenco) or 1.0
    clima = sum(j.moral * PESO_HIERARQUIA[j.hierarquia] for j in clube.elenco) / total_peso
    lideres_mal = [j for j in clube.elenco
                   if j.hierarquia == Hierarquia.LIDER and (j.moral < 35 or j.insatisfeito)]
    penalidade = sum(max(35.0 - j.moral, 0.0) * 0.15 + (2.0 if j.insatisfeito else 0.0) for j in lideres_mal)
    mudancas: List[MudancaMoral] = []
    noticias: List[str] = []
    for jogador in clube.elenco:
        if jogador in lideres_mal:
            continue
        suscetibilidade = 0.18 * (1.2 - jogador.personalidade.profissionalismo / 25.0)
        delta = (clima - jogador.moral) * suscetibilidade - penalidade
        if abs(delta) >= 0.5:
            _aplicar(mudancas, jogador, delta, "clima do vestiário")
    if lideres_mal:
        nomes = ", ".join(j.nome for j in lideres_mal)
        noticias.append(f"{clube.nome}: clima pesado, {nomes} está insatisfeito e o grupo sente.")
    return mudancas, noticias


def reagir_declaracao(clube: Clube, tom: TomDeclaracao, alvo: Optional[Jogador] = None,
                      resultado_recente: float = 0.5) -> Tuple[List[MudancaMoral], List[str]]:
    """Reação do elenco a uma resposta do técnico na coletiva de imprensa."""
    mudancas: List[MudancaMoral] = []
    noticias: List[str] = []
    for jogador in clube.elenco:
        p = jogador.personalidade
        det = jogador.mentais.determinacao
        if tom == TomDeclaracao.ELOGIAR_ELENCO:
            delta = 3.0 if resultado_recente >= 0.5 else 1.0
            motivo = "elogio público do técnico"
        elif tom == TomDeclaracao.MANTER_CALMA:
            delta = 1.0
            motivo = "técnico passou tranquilidade"
        elif tom == TomDeclaracao.COBRAR_PUBLICAMENTE:
            delta = (0.25 * (det - 10) + 0.2 * (p.profissionalismo - 10)
                     - 0.35 * max(0, 12 - p.temperamento) - 1.0)
            if jogador.hierarquia == Hierarquia.LIDER:
                delta -= 1.5
            motivo = "cobrança pública do técnico"
        else:
            if alvo is not None and jogador is alvo:
                delta = -(8.0 + 0.5 * max(0, 12 - p.temperamento))
                motivo = "criticado publicamente pelo técnico"
            elif alvo is not None and alvo.hierarquia == Hierarquia.LIDER:
                delta = -3.0 * (1.2 - p.profissionalismo / 25.0)
                motivo = f"elenco se fecha ao lado de {alvo.nome_curto}"
            else:
                delta = -0.8
                motivo = "ambiente tenso após crítica pública"
        _aplicar(mudancas, jogador, delta, motivo)
    if tom == TomDeclaracao.CRITICAR_JOGADOR and alvo is not None:
        alvo.insatisfeito = True
        noticias.append(f"{alvo.nome} não gostou da crítica pública do técnico.")
        if alvo.hierarquia == Hierarquia.LIDER:
            noticias.append(f"{clube.nome}: o elenco se fecha ao lado de {alvo.nome}.")
    cascata, noticias_cascata = efeito_cascata(clube)
    return mudancas + cascata, noticias + noticias_cascata


def consolidar(*listas: List[MudancaMoral]) -> List[MudancaMoral]:
    """Junta várias listas numa mudança por jogador (moral inicial, final e motivos)."""
    por_jogador: Dict[int, MudancaMoral] = {}
    for lista in listas:
        for m in lista:
            atual = por_jogador.get(m.jogador.id)
            if atual is None:
                por_jogador[m.jogador.id] = MudancaMoral(m.jogador, m.antes, m.depois, m.motivo)
            else:
                atual.depois = m.depois
                if m.motivo not in atual.motivo:
                    atual.motivo += "; " + m.motivo
    return sorted(por_jogador.values(), key=lambda m: m.delta)


def recuperacao_moral_diaria(jogador: Jogador) -> None:
    """A moral volta devagar para a linha de base de cada personalidade."""
    base = 55.0 + (jogador.personalidade.profissionalismo - 10) * 0.8
    if jogador.insatisfeito:
        base -= 10.0
    jogador.moral = limitar(jogador.moral + (base - jogador.moral) * 0.04, 0.0, 100.0)
